    #[test]
    fn pending_proposal_borrowed_encoding_matches_owned_for_inline_payloads() {
        let evm_payloads = [
            vec![],
            vec![vec![]],
            vec![vec![0x12; 131_072], vec![], vec![0x34; 257]],
        ];
        let core_payloads = [
            vec![],
            vec![torus_types::CoreWriterAction::PermanentStake {
                amount: U256::from(42),
            }; 3],
        ];
        for actions in [vec![], vec![sign_claim_rewards(1), sign_claim_rewards(2)]] {
            for evm in &evm_payloads {
                for core in &core_payloads {
                    let mut block = make_block(7, actions.clone());
                    block.header.evm_tx_count = evm.len() as u32;
                    block.evm_transactions = evm.clone();
                    block.core_writer_actions = core.clone();
                    let pending = PendingProposal::new(block.clone());
                    let encoded = pending.encode(true);
                    let owned = CompactBlock::from_block(&block);
                    assert_eq!(encoded, bincode::serialize(&owned).unwrap());
                    let decoded: CompactBlock = bincode::deserialize(&encoded).unwrap();
                    assert_eq!(decoded.native_action_hashes, owned.native_action_hashes);
                    assert_eq!(decoded.evm_transactions, block.evm_transactions);
                    assert_eq!(
                        bincode::serialize(&decoded.core_writer_actions).unwrap(),
                        bincode::serialize(&block.core_writer_actions).unwrap()
                    );
                    assert_eq!(
                        pending.encode(false),
                        bincode::serialize(&block).unwrap()
                    );
                }
            }
        }
    }

    #[test]
    fn pending_proposal_match_rejects_reordered_replaced_and_resigned_bodies() {
        let block = make_block(7, vec![sign_claim_rewards(1), sign_claim_rewards(2)]);
        let committed = CompactBlock::from_block(&block);
        let shorter = PendingProposal::new(make_block(7, vec![sign_claim_rewards(1)]));
        assert!(!cached_matches_compact(&shorter, &committed));
        assert!(shorter.native_action_hashes.get().is_none());
        let cold = PendingProposal::new(block.clone());
        assert!(cached_matches_compact(&cold, &committed));
        assert!(cold.native_action_hashes.get().is_none());
        cold.native_action_hashes();
        assert!(cached_matches_compact(&cold, &committed));
        let mut reordered_compact = committed.clone();
        reordered_compact.native_action_hashes.swap(0, 1);
        assert!(!cached_matches_compact(&cold, &reordered_compact));
        assert!(cached_matches_compact(
            &PendingProposal::new(block.clone()),
            &committed
        ));

        let mut reordered = block.clone();
        reordered.native_actions.swap(0, 1);
        assert!(!cached_matches_compact(
            &PendingProposal::new(reordered),
            &committed
        ));

        let mut replaced = block.clone();
        replaced.native_actions[0] = sign_claim_rewards(3);
        assert!(!cached_matches_compact(
            &PendingProposal::new(replaced),
            &committed
        ));

        let mut resigned = block;
        let torus_types::ActionSignature::Eip712(ref mut signature) =
            resigned.native_actions[0].signature
        else {
            panic!("fixture must have an EIP-712 signature");
        };
        signature.r[0] ^= 1;
        assert!(!cached_matches_compact(
            &PendingProposal::new(resigned),
            &committed
        ));
    }

    #[test]
    fn pending_proposal_warm_and_cold_match_reference_for_body_variants() {
        let actions = vec![sign_claim_rewards(1), big_order_batch_action(2, 400)];
        let mut resigned = actions.clone();
        let torus_types::ActionSignature::Eip712(ref mut signature) = resigned[0].signature
        else {
            panic!("fixture must have an EIP-712 signature");
        };
        signature.r[0] ^= 1;
        let bodies = vec![
            vec![],
            actions.clone(),
            vec![actions[0].clone()],
            vec![actions[1].clone(), actions[0].clone()],
            vec![actions[0].clone(), actions[0].clone()],
            vec![sign_claim_rewards(3), actions[1].clone()],
            resigned,
        ];
        for body in &bodies {
            let block = make_block(7, body.clone());
            let cold = PendingProposal::new(block.clone());
            let warm = PendingProposal::new(block.clone());
            let addresses = warm.native_action_hashes().as_ptr();
            for references in &bodies {
                let compact = CompactBlock::from_block(&make_block(7, references.clone()));
                // Original streaming predicate is the independent oracle; it
                // binds length, order, duplicates, content and signatures.
                let expected = block.native_actions.len() == compact.native_action_hashes.len()
                    && block
                        .native_actions
                        .iter()
                        .map(torus_types::compute_action_hash)
                        .eq(compact.native_action_hashes.iter().copied());
                assert_eq!(cached_matches_compact(&cold, &compact), expected);
                assert_eq!(cached_matches_compact(&warm, &compact), expected);
                assert!(cold.native_action_hashes.get().is_none());
                assert_eq!(warm.native_action_hashes().as_ptr(), addresses);
            }
        }
    }

    #[test]
    fn pending_proposal_replacement_discards_previous_hashes() {
        let mut app = TorusApp::stub();
        let original = make_block(5, vec![sign_claim_rewards(1)]);
        let replacement = make_block(5, vec![sign_claim_rewards(2)]);
        assert!(matches!(
            app.finish_validate_compact(original.clone()),
            ValidateBlockResponse::Valid { .. }
        ));
        let original_hashes = app.pending_proposals[&5].native_action_hashes().to_vec();
        assert!(matches!(
            app.finish_validate_compact(replacement.clone()),
            ValidateBlockResponse::Valid { .. }
        ));
        let pending = &app.pending_proposals[&5];
        assert!(pending.native_action_hashes.get().is_none());
        assert_ne!(pending.native_action_hashes(), original_hashes.as_slice());
        assert!(!cached_matches_compact(
            pending,
            &CompactBlock::from_block(&original)
        ));
        assert!(cached_matches_compact(
            pending,
            &CompactBlock::from_block(&replacement)
        ));
    }

    #[test]
    fn pending_proposal_warm_commit_uses_committed_header_and_inline_payload() {
        let (config, state_db) = make_test_config_and_db();
        let (mut app, rx, _mempool) = app_with_recording_exec(&config, &state_db);
        app.exec_next_height = Some(5);
        let mut cached = make_block(5, vec![sign_claim_rewards(1)]);
        cached.header.timestamp = 10;
        cached.header.evm_tx_count = 1;
        // Opaque EVM bytes are sufficient: this test records dispatch and does
        // not bypass or call the independent validation/execution stages.
        cached.evm_transactions = vec![vec![0xaa]];
        let mut committed = cached.clone();
        committed.header.timestamp = 20;
        committed.header.base_fee_per_gas += 1;
        committed.evm_transactions = vec![vec![0xbb, 0xcc]];
        committed.core_writer_actions = vec![torus_types::CoreWriterAction::PermanentStake {
            amount: U256::from(42),
        }];
        let pending = PendingProposal::new(cached);
        pending.native_action_hashes();
        app.pending_proposals.insert(5, pending);
        let consensus_block = committed_compact_block(&committed);
        app.on_committed_block(&consensus_block, consensus_block.hash);
        let msg = rx.try_recv().expect("matching warm cache must dispatch");
        assert_eq!(
            bincode::serialize(&msg.torus_block).unwrap(),
            bincode::serialize(&committed).unwrap()
        );
        assert_eq!(
            msg.settled_durable(),
            DurableRows { header: true, body: true }
        );
        let durable_body = load_replay_body(&state_db, 5).expect("body durable before dispatch");
        assert_eq!(
            bincode::serialize(&durable_body).unwrap(),
            bincode::serialize(&committed.body()).unwrap()
        );
        assert!(!app.pending_proposals.contains_key(&5));
    }

    #[test]
    fn pending_proposal_selection_excludes_validated_bodies_and_missing_body_ledger() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_millis() as u64;
        let actions: Vec<_> = (0..3).map(|i| sign_claim_rewards(now + i)).collect();
        for action in &actions {
            mempool
                .add_native_action_presigned(action.recover_sender().unwrap(), action.clone())
                .unwrap();
        }
        let mut app = TorusApp::new(state_db, &config, None, Some(mempool), None);
        // Full-block validation has no compact hash note. Its cached body alone
        // must still exclude the action from the next proposal.
        assert!(matches!(
            app.finish_validate_compact(make_block(5, vec![actions[0].clone()])),
            ValidateBlockResponse::Valid { .. }
        ));
        let missing_hash = torus_types::compute_action_hash(&actions[1]);
        app.in_flight_hashes.note(6, [missing_hash]);
        let parent_hdr = test_parent_at(&app, 0);
        let (selected, _) = app.select_block_payload(
            &parent_hdr,
            &NoAncestry,
            30_000_000,
            0,
            1_000_000_000,
            1_000_000_000,
        );
        assert_eq!(selected.len(), 1);
        assert_eq!(
            torus_types::compute_action_hash(&selected[0].1),
            torus_types::compute_action_hash(&actions[2])
        );

        // Cleanup releases the body and its cache together; the independent
        // missing-body ledger continues to exclude its action.
        app.pending_proposals.remove(&5);
        let parent_hdr = test_parent_at(&app, 0);
        let (selected, _) = app.select_block_payload(
            &parent_hdr,
            &NoAncestry,
            30_000_000,
            0,
            1_000_000_000,
            1_000_000_000,
        );
        assert_eq!(selected.len(), 2);
        assert!(selected
            .iter()
            .all(|(_, action)| torus_types::compute_action_hash(action) != missing_hash));
    }

    /// s68: `build_proposal` splits the leader's `block_build` into phases.
    /// Each phase observes exactly once per proposal, and the phases nest
    /// inside the whole-build timer.
    #[test]
    fn build_proposal_observes_every_phase_once() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_millis() as u64;
        let action = sign_claim_rewards(now);
        mempool
            .add_native_action_presigned(action.recover_sender().unwrap(), action)
            .unwrap();
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let mut app = TorusApp::new(
            state_db,
            &config,
            Some(metrics.clone()),
            Some(mempool),
            None,
        );

        let parent = app.last_header.clone();
        let resp = app.build_proposal(parent.clone());
        assert_eq!(resp.data.vec().len(), 1);
        let height = parent.height + 1;
        assert_eq!(
            app.pending_proposals[&height].block.native_actions.len(),
            1,
            "the pooled action must be proposed"
        );

        let text = metrics.encode();
        let phases = [
            "torus_block_build_select_seconds",
            "torus_block_build_mirror_seconds",
            "torus_block_build_attest_seconds",
            "torus_block_build_encode_seconds",
        ];
        for name in phases.iter().copied().chain(["torus_block_build_seconds"]) {
            assert_eq!(
                metric_count(&text, &format!("{name}_count")),
                1,
                "{name} must observe once per proposal"
            );
        }
        let sum = |name: &str| -> f64 {
            text.lines()
                .find_map(|l| l.strip_prefix(&format!("{name}_sum ")))
                .and_then(|v| v.trim().parse().ok())
                .unwrap()
        };
        let phase_total: f64 = phases.iter().map(|n| sum(n)).sum();
        assert!(
            phase_total <= sum("torus_block_build_seconds"),
            "phases ({phase_total}) must nest inside block_build"
        );
    }

    #[test]
    fn produce_block_datum_is_compact() {
        // Task 8: with compact proposals enabled (version-gated), the proposal datum
        // carries only action HASHES (CompactBlock), not inline bodies — bodies travel
        // out-of-band via the durable DA store (push T7 / pull T6). Required for 400k
        // orders/sec, where a full block of ~MB exceeds max_consensus_message_size.
        let actions: Vec<SignedNativeAction> = (0..100).map(sign_claim_rewards).collect();
        let block = make_block(7, actions);

        // Compact-mode datum: a CompactBlock referencing all 100 actions by hash.
        let compact_datum = encode_proposal_datum(&block, true);
        let decoded: CompactBlock = bincode::deserialize(&compact_datum)
            .expect("compact-mode datum must be a CompactBlock");
        assert_eq!(
            decoded.native_action_hashes.len(),
            100,
            "compact datum references every action by hash"
        );

        // The FULL encoding remains valid behind the flag (staged rollout / rollback),
        // and is strictly larger — proving the compact datum carries no inline bodies.
        let full_datum = encode_proposal_datum(&block, false);
        let full: TorusBlock = bincode::deserialize(&full_datum)
            .expect("full-mode datum must be a self-contained TorusBlock");
        assert_eq!(full.native_actions.len(), 100);
        assert!(
            compact_datum.len() < full_datum.len(),
            "compact datum must be smaller (bodies are out-of-band, not inline)"
        );
    }

    #[test]
    fn compact_proposal_disseminates() {
        // Task 8: a compact proposal carries only hashes, and a peer reconstructs the
        // full block from bodies delivered out-of-band into its durable DA store
        // (push T7 / pull T6) — so re-enabling compact does not strand any validator.
        let (config, state_db) = make_test_config_and_db();
        let actions: Vec<SignedNativeAction> = (0..10).map(sign_claim_rewards).collect();
        let block = make_block(5, actions.clone());

        // The proposer emits a CompactBlock datum (hashes only).
        let datum = encode_proposal_datum(&block, true);
        let compact: CompactBlock =
            bincode::deserialize(&datum).expect("compact-mode datum is a CompactBlock");
        assert_eq!(compact.native_action_hashes.len(), actions.len());

        // A peer holding the bodies in its DA store (delivered out-of-band) reconstructs
        // the full block — the bodies were NOT in the proposal itself.
        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let _ = mempool.mirror_native_to_da(&actions); // models push/pull delivery into the DA store
        let app = TorusApp::new(state_db.clone(), &config, None, Some(mempool), None);
        let reconstructed = app
            .reconstruct_compact_from_da(&compact)
            .expect("peer reconstructs the compact block from its durable DA store");
        assert_eq!(reconstructed.native_actions.len(), actions.len());
        for (got, want) in reconstructed.native_actions.iter().zip(actions.iter()) {
            assert_eq!(
                torus_types::compute_action_hash(got),
                torus_types::compute_action_hash(want),
                "reconstructed bodies match the referenced hashes"
            );
        }
    }

    /// Task 2 (S459 PRIMARY): a full-inline `TorusBlock` proposal carrying a native
    /// action whose body is NOT pre-loaded into the DA store must, after
    /// `validate_block`'s decode+durability step, have that body durably present —
    /// the legacy path now mirrors to `da_store` before it can vote `Valid`, meeting
    /// the same bar the compact path already guarantees. RED before Task 2: the
    /// legacy branch returned the block without mirroring, so `get_native_da` was
    /// `None` (a later restart/backfill could never reconstruct it → the wedge).
    #[test]
    fn validate_block_legacy_durable() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let action = sign_claim_rewards(1);
        let hash = torus_types::compute_action_hash(&action);

        // Precondition: the body has never been mirrored/put — absent from the store.
        assert!(
            mempool.get_native_da(&hash).is_none(),
            "precondition: body absent from the DA store before validation"
        );

        // A FULL inline TorusBlock datum (bodies inline, not out-of-band).
        let block = make_block(1, vec![action.clone()]);
        let datum = encode_proposal_datum(&block, false);

        let mut app = TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);
        let decoded = match app.decode_proposal_and_ensure_durable(&datum) {
            Ok(b) => b,
            Err(_) => panic!("legacy full TorusBlock must decode as Valid, not short-circuit"),
        };
        assert_eq!(decoded.native_actions.len(), 1);

        // The invariant: after the decode+durability step the body is durable.
        assert!(
            mempool.get_native_da(&hash).is_some(),
            "legacy TorusBlock path must mirror the body into the DA store before Valid"
        );
    }

    /// Consensus-thread attribution: the `validate_block` phase timers fire on the
    /// decode+durability step (full `TorusBlock` path: decode, DA mirror, custody).
    /// `validate_block` itself needs a crate-private `ValidateBlockRequest`, so the
    /// phases reachable from here are the ones asserted.
    #[test]
    fn validate_block_phase_timers_observe_on_decode() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let block = make_block(1, vec![sign_claim_rewards(1)]);
        let datum = encode_proposal_datum(&block, false);
        let mut app = TorusApp::new(
            state_db.clone(),
            &config,
            Some(metrics.clone()),
            Some(mempool),
            None,
        );
        app.decode_proposal_and_ensure_durable(&datum)
            .unwrap_or_else(|_| panic!("full TorusBlock must decode"));
        let text = metrics.encode();
        for name in [
            "torus_validate_block_decode_seconds_count 1",
            "torus_validate_block_da_reconstruct_seconds_count 1",
            "torus_validate_block_custody_seconds_count 1",
        ] {
            assert!(text.contains(name), "{name} missing:\n{text}");
        }
    }

    // ============== TORUS_ASYNC_VALIDATE (item 3, perf/matched-200k) ==============
    //
    // Speculative body validation OFF the hotstuff-algo thread: the heavy stage
    // (decode + DA durability + EVM decode + sig/attest verify) runs on the
    // `torus-async-validate` worker at body arrival; `validate_block` then finds a
    // consume-once verdict in a cache keyed by the sha256 of the EXACT datum bytes
    // (the same recompute the sync path does for `data_hash`). Flag OFF (default)
    // uses synchronous validation; cache misses/stale verdicts fall back to it.
    // Flag ON remains experimental pending the admission/write/metrics gates.

    /// Parse `name N` (histogram `_count` line) out of `Metrics::encode()` text.
    fn metric_count(text: &str, name: &str) -> u64 {
        text.lines()
            .find_map(|l| l.strip_prefix(name).and_then(|rest| rest.trim().parse().ok()))
            .unwrap_or(0)
    }

    fn make_async_validate_app() -> (TorusApp, Arc<Mempool>, Arc<torus_telemetry::Metrics>) {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let mut app = TorusApp::new(
            state_db,
            &config,
            Some(metrics.clone()),
            Some(mempool.clone()),
            None,
        );
        app.enable_async_validate();
        (app, mempool, metrics)
    }

    fn async_cache_len(app: &TorusApp) -> usize {
        app.async_validate
            .as_ref()
            .expect("async-validate worker running")
            .shared
            .cache
            .lock()
            .unwrap()
            .len()
    }

    /// Wait (bounded) until the worker has cached `n` verdicts.
    fn wait_for_cached(app: &TorusApp, n: usize) {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while async_cache_len(app) < n {
            assert!(
                std::time::Instant::now() < deadline,
                "async-validate worker did not cache the verdict in time"
            );
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
    }

    fn data_hash_of(datum: &[u8]) -> CryptoHash {
        CryptoHash::new(TorusApp::hash_datum(datum))
    }

    #[test]
    fn parse_async_validate_toggle_only_1_enables() {
        assert!(parse_async_validate_toggle(Some("1".to_string())));
        assert!(parse_async_validate_toggle(Some(" 1 ".to_string())));
        assert!(!parse_async_validate_toggle(None));
        for v in ["0", "true", "yes", "on", "", "11", "garbage"] {
            assert!(
                !parse_async_validate_toggle(Some(v.to_string())),
                "only \"1\" may enable; got enabled for {v:?}"
            );
        }
    }

    #[test]
    fn compact_decode_borrowed_notes_survive_missing_data() {
        let metrics = Some(Arc::new(torus_telemetry::Metrics::new()));
        let mut ledger = InFlightHashLedger::default();
        let mut calls = 0;
        // Same-height re-proposals must union notes even when neither body can
        // be reconstructed. No mempool means reconstruction fails immediately.
        for nonce in [1, 2] {
            let block = make_block(5, vec![sign_claim_rewards(nonce)]);
            let expected = torus_types::compute_action_hash(&block.native_actions[0]);
            let datum = encode_proposal_datum(&block, true);
            let response = TorusApp::decode_proposal_and_ensure_durable_core(
                None,
                None,
                None,
                &metrics,
                1,
                &datum,
                |height, hashes: &[B256]| {
                    assert_eq!(height, 5);
                    assert_eq!(hashes, &[expected]);
                    assert_eq!(
                        metric_count(
                            &metrics.as_ref().unwrap().encode(),
                            "torus_validate_block_da_reconstruct_seconds_count",
                        ),
                        calls,
                        "callback must precede this proposal's reconstruction"
                    );
                    ledger.note(height, hashes.iter().copied());
                    calls += 1;
                },
            );
            assert!(matches!(response, Err(ValidateBlockResponse::MissingData)));
            assert!(ledger.by_height[&5].contains(&expected));
        }
        assert_eq!(calls, 2);
        assert_eq!(ledger.by_height[&5].len(), 2);
    }

    #[test]
    fn compact_decode_note_callback_runs_before_body_lookup() {
        let (_config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db,
            torus_mempool::MempoolConfig::default(),
        ));
        let block = make_block(5, vec![sign_claim_rewards(3)]);
        let hash = torus_types::compute_action_hash(&block.native_actions[0]);
        let datum = encode_proposal_datum(&block, true);
        let mut calls = 0;
        let decoded = TorusApp::decode_proposal_and_ensure_durable_core(
            Some(&mempool),
            None,
            None,
            &None,
            1,
            &datum,
            |height, hashes| {
                assert_eq!(height, 5);
                assert_eq!(hashes, &[hash]);
                // The callback supplies the body: reconstruction succeeds only
                // if it runs AFTER this borrowed note is delivered.
                mempool.mirror_native_to_da(&block.native_actions).unwrap();
                calls += 1;
            },
        );
        assert_eq!(calls, 1);
        let decoded = match decoded {
            Ok(block) => block,
            Err(_) => panic!("callback must run before body lookup"),
        };
        assert_eq!(
            bincode::serialize(&decoded).unwrap(),
            bincode::serialize(&block).unwrap()
        );
    }

    #[test]
    fn async_validate_flag_off_parity() {
        // TORUS_ASYNC_VALIDATE unset (tests never set it): no worker, no cache,
        // and the validate path runs (and times) everything on the calling thread.
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let mut app = TorusApp::new(
            state_db,
            &config,
            Some(metrics.clone()),
            Some(mempool.clone()),
            None,
        );
        assert!(
            app.async_validate.is_none(),
            "flag off must spawn NO worker and populate NO cache"
        );
        assert!(
            app.async_validate_handle().is_none(),
            "OFF exposes no worker feed"
        );

        // Full inline TorusBlock datum: Valid, all phase timers observe HERE.
        let block = make_block(5, vec![sign_claim_rewards(1)]);
        let datum = encode_proposal_datum(&block, false);
        let resp = app.validate_datum(&datum, &data_hash_of(&datum));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));
        let text = metrics.encode();
        for name in [
            "torus_validate_block_decode_seconds_count",
            "torus_validate_block_da_reconstruct_seconds_count",
            "torus_validate_block_custody_seconds_count",
        ] {
            assert_eq!(
                metric_count(&text, name),
                1,
                "{name} must observe on the calling thread"
            );
        }

        // Compact datum whose bodies were delivered out-of-band: Valid too.
        let actions = vec![sign_claim_rewards(2)];
        mempool.mirror_native_to_da(&actions).unwrap();
        let block2 = make_block(5, actions);
        let datum2 = encode_proposal_datum(&block2, true);
        let resp2 = app.validate_datum(&datum2, &data_hash_of(&datum2));
        assert!(matches!(resp2, ValidateBlockResponse::Valid { .. }));

        // data_hash mismatch still rejects.
        let resp3 = app.validate_datum(&datum, &CryptoHash::new([7u8; 32]));
        assert!(matches!(resp3, ValidateBlockResponse::Invalid));

        // A reconstruction miss still updates the sync ledger immediately.
        let missing = make_block(6, vec![sign_claim_rewards(3)]);
        let missing_hash = torus_types::compute_action_hash(&missing.native_actions[0]);
        let missing_datum = encode_proposal_datum(&missing, true);
        assert!(matches!(
            app.validate_datum(&missing_datum, &data_hash_of(&missing_datum)),
            ValidateBlockResponse::MissingData
        ));
        assert!(app.in_flight_hashes.by_height[&6].contains(&missing_hash));
        assert!(!app.pending_proposals.contains_key(&6));
        assert!(
            app.async_validate.is_none(),
            "validation must not lazily spawn a worker"
        );
        assert!(app.async_validate_handle().is_none());

        // Direct test callers retain fail-stop, before any decode/body work.
        let decode_before = metric_count(
            &metrics.encode(),
            "torus_validate_block_decode_seconds_count",
        );
        app.exec_failed.store(true, Ordering::SeqCst);
        assert!(matches!(
            app.validate_datum(&datum, &data_hash_of(&datum)),
            ValidateBlockResponse::Invalid
        ));
        assert_eq!(
            metric_count(
                &metrics.encode(),
                "torus_validate_block_decode_seconds_count"
            ),
            decode_before
        );
    }

    /// s76 item 6: the compact reconstruct is split into the ingress-mirror
    /// flush, the RocksDB MultiGet, the body decode and the missing-body wait,
    /// each observed on the calling thread. The wait only observes when a body
    /// was missing on the first read.
    #[test]
    fn validate_da_subphase_timers_observe() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let mut app = TorusApp::new(
            state_db,
            &config,
            Some(metrics.clone()),
            Some(mempool.clone()),
            None,
        );

        let actions = vec![sign_claim_rewards(2)];
        mempool.mirror_native_to_da(&actions).unwrap();
        let block = make_block(5, actions);
        let datum = encode_proposal_datum(&block, true);
        assert!(matches!(
            app.validate_datum(&datum, &data_hash_of(&datum)),
            ValidateBlockResponse::Valid { .. }
        ));
        let text = metrics.encode();
        for name in [
            "torus_validate_block_da_multiget_seconds_count",
            "torus_validate_block_da_decode_seconds_count",
        ] {
            assert_eq!(metric_count(&text, name), 1, "{name}");
        }
        assert_eq!(
            metric_count(&text, "torus_validate_block_da_flush_seconds_count"),
            0,
            "s76 step 2: bodies already durable, no ingress flush"
        );
        assert_eq!(
            metric_count(&text, "torus_validate_block_da_wait_seconds_count"),
            0,
            "all bodies present: no wait"
        );

        let missing = make_block(6, vec![sign_claim_rewards(3)]);
        let missing_datum = encode_proposal_datum(&missing, true);
        assert!(matches!(
            app.validate_datum(&missing_datum, &data_hash_of(&missing_datum)),
            ValidateBlockResponse::MissingData
        ));
        let text = metrics.encode();
        assert_eq!(metric_count(&text, "torus_validate_block_da_multiget_seconds_count"), 2);
        assert_eq!(
            metric_count(&text, "torus_validate_block_da_flush_seconds_count"),
            1,
            "a miss flushes before giving up"
        );
        assert_eq!(metric_count(&text, "torus_validate_block_da_wait_seconds_count"), 1);
    }

    #[test]
    fn async_validate_cache_hit_skips_heavy_path() {
        let (mut app, _mempool, metrics) = make_async_validate_app();
        let block = make_block(5, vec![sign_claim_rewards(1)]);
        let datum = encode_proposal_datum(&block, false);

        let handle = app
            .async_validate_handle()
            .expect("flag on: tee handle available");
        assert!(handle.submit(datum.clone()));
        wait_for_cached(&app, 1);

        // The worker recorded the heavy-stage timers while validating.
        let text = metrics.encode();
        assert_eq!(metric_count(&text, "torus_validate_block_decode_seconds_count"), 1);
        assert_eq!(
            metric_count(&text, "torus_validate_block_da_reconstruct_seconds_count"),
            1
        );

        let resp = app.validate_datum(&datum, &data_hash_of(&datum));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));

        // HIT: the heavy stage did NOT re-run on the calling thread.
        let text = metrics.encode();
        assert_eq!(metric_count(&text, "torus_validate_block_decode_seconds_count"), 1);
        assert_eq!(
            metric_count(&text, "torus_validate_block_da_reconstruct_seconds_count"),
            1
        );
        assert_eq!(async_cache_len(&app), 0, "verdicts are consume-once");
        assert!(
            app.pending_proposals.contains_key(&5),
            "hit path still records the pending proposal"
        );
    }

    #[test]
    fn async_validate_cache_miss_falls_back_sync() {
        let (mut app, _mempool, metrics) = make_async_validate_app();
        let block = make_block(5, vec![sign_claim_rewards(1)]);
        let datum = encode_proposal_datum(&block, false);

        // Nothing submitted: cache is EMPTY — full sync fallback on this thread.
        let resp = app.validate_datum(&datum, &data_hash_of(&datum));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));
        let text = metrics.encode();
        assert_eq!(
            metric_count(&text, "torus_validate_block_decode_seconds_count"),
            1,
            "miss must run the sync heavy path on the calling thread"
        );
    }

    #[test]
    fn async_validate_wrong_body_poisoned_cache_rejected() {
        let (mut app, _mempool, _metrics) = make_async_validate_app();
        let block = make_block(5, vec![sign_claim_rewards(1)]);
        let datum = encode_proposal_datum(&block, false);
        assert!(app.async_validate_handle().unwrap().submit(datum.clone()));
        wait_for_cached(&app, 1);

        // Attacker hands us DIFFERENT bytes (the same block as a compact datum
        // whose body this node does not hold) with a self-consistent data_hash.
        // The recomputed key must MISS the cached Valid verdict and the sync
        // path must decide on its own (here: MissingData).
        let mut tampered_block = block.clone();
        tampered_block.native_actions = vec![sign_claim_rewards(2)];
        let tampered = encode_proposal_datum(&tampered_block, true);
        assert_ne!(tampered, datum);
        let resp = app.validate_datum(&tampered, &data_hash_of(&tampered));
        assert!(
            matches!(resp, ValidateBlockResponse::MissingData),
            "Valid must never be served for bytes that were not themselves validated"
        );
        assert_eq!(
            async_cache_len(&app),
            1,
            "the good entry must not be consumed by the tampered bytes"
        );
    }

    #[test]
    fn async_validate_cross_fork_no_reuse() {
        let (mut app, _mempool, metrics) = make_async_validate_app();
        // Two blocks at the SAME height with different bodies (different forks).
        let block_a = make_block(5, vec![sign_claim_rewards(1)]);
        let block_b = make_block(5, vec![sign_claim_rewards(2)]);
        let datum_a = encode_proposal_datum(&block_a, false);
        let datum_b = encode_proposal_datum(&block_b, false);
        let handle = app.async_validate_handle().unwrap();
        assert!(handle.submit(datum_a.clone()));
        assert!(handle.submit(datum_b.clone()));
        wait_for_cached(&app, 2);

        // Fork A's verdict serves ONLY fork A, and only once.
        let resp = app.validate_datum(&datum_a, &data_hash_of(&datum_a));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));
        assert_eq!(async_cache_len(&app), 1, "A consumed; B untouched");

        // Re-validating the SAME bytes after consumption falls back sync and agrees.
        let decode_before = metric_count(
            &metrics.encode(),
            "torus_validate_block_decode_seconds_count",
        );
        let resp = app.validate_datum(&datum_a, &data_hash_of(&datum_a));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));
        assert_eq!(
            metric_count(
                &metrics.encode(),
                "torus_validate_block_decode_seconds_count"
            ),
            decode_before + 1,
            "consumed entry must NOT be re-served — sync fallback re-decodes"
        );

        // Fork B is served from ITS OWN entry (no cross-fork reuse, no sync re-run).
        let decode_before = metric_count(
            &metrics.encode(),
            "torus_validate_block_decode_seconds_count",
        );
        let resp = app.validate_datum(&datum_b, &data_hash_of(&datum_b));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));
        assert_eq!(
            metric_count(
                &metrics.encode(),
                "torus_validate_block_decode_seconds_count"
            ),
            decode_before,
            "fork B hits its own cached verdict"
        );
        assert_eq!(async_cache_len(&app), 0);
    }

    #[test]
    fn async_validate_sync_checks_survive_cache_hit() {
        use std::sync::atomic::Ordering;
        // (a) the exec fail-stop latch beats a cached Valid verdict.
        let (mut app, _mempool, _metrics) = make_async_validate_app();
        let block = make_block(5, vec![sign_claim_rewards(1)]);
        let datum = encode_proposal_datum(&block, false);
        assert!(app.async_validate_handle().unwrap().submit(datum.clone()));
        wait_for_cached(&app, 1);
        app.exec_failed.store(true, Ordering::SeqCst);
        let resp = app.validate_datum(&datum, &data_hash_of(&datum));
        assert!(
            matches!(resp, ValidateBlockResponse::Invalid),
            "fail-stop must never be bypassed by the async path"
        );

        // (b) the ancestry check runs in `validate_block` against the parent
        // block in the tree, before any cached verdict is consulted (s84
        // decision 2, `vote_requires_the_header_to_link_to_its_parent`).
    }

    /// A commit landing WITHOUT exec catching up changes nothing the heavy
    /// stage reads (ancestry and fail-stop re-run live at hit time), so the hit
    /// path must survive — the deep-exec-queue regime this branch targets is
    /// exactly where commits outrun exec.
    #[test]
    fn async_validate_commit_without_exec_still_hits() {
        let (mut app, _mempool, metrics) = make_async_validate_app();
        let block = make_block(5, vec![sign_claim_rewards(1)]);
        let datum = encode_proposal_datum(&block, false);
        assert!(app.async_validate_handle().unwrap().submit(datum.clone()));
        wait_for_cached(&app, 1);

        // A commit applies but the exec thread has NOT caught up: the applied
        // marker is unmoved, only the committed frontier advances.
        app.last_header.height += 1;

        let decode_before = metric_count(
            &metrics.encode(),
            "torus_validate_block_decode_seconds_count",
        );
        let resp = app.validate_datum(&datum, &data_hash_of(&datum));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));
        assert_eq!(
            metric_count(
                &metrics.encode(),
                "torus_validate_block_decode_seconds_count"
            ),
            decode_before,
            "applied frontier unchanged — the cached verdict must be served (hit)"
        );
    }

    #[test]
    fn async_validate_compact_hit_notes_in_flight() {
        let (mut app, mempool, metrics) = make_async_validate_app();
        let actions = vec![sign_claim_rewards(4)];
        mempool.mirror_native_to_da(&actions).unwrap();
        let action_hash = torus_types::compute_action_hash(&actions[0]);
        let block = make_block(5, actions);
        let datum = encode_proposal_datum(&block, true);
        assert!(app.async_validate_handle().unwrap().submit(datum.clone()));
        wait_for_cached(&app, 1);

        let da_before = metric_count(
            &metrics.encode(),
            "torus_validate_block_da_reconstruct_seconds_count",
        );
        let resp = app.validate_datum(&datum, &data_hash_of(&datum));
        assert!(matches!(resp, ValidateBlockResponse::Valid { .. }));
        assert_eq!(
            metric_count(
                &metrics.encode(),
                "torus_validate_block_da_reconstruct_seconds_count"
            ),
            da_before,
            "compact hit skips the DA reconstruct on the calling thread"
        );
        assert!(
            app.in_flight_hashes
                .by_height
                .get(&5)
                .is_some_and(|s| s.contains(&action_hash)),
            "compact hit must still note in-flight hashes (s355 duplicate-inclusion guard)"
        );
    }

    #[test]
    fn async_validate_resolution_is_logged_at_startup() {
        // TORUS_MATCH_WORKERS lesson: an unlogged knob makes bench results
        // un-analyzable. The resolution line must fire in BOTH states.
        let out = capture_logs(|| {
            // The callsite's first hit is on another thread (as TorusApp::new
            // in a parallel test would): the capture must still see ours.
            std::thread::spawn(|| log_async_validate_resolution(true))
                .join()
                .unwrap();
            log_async_validate_resolution(true);
            log_async_validate_resolution(false);
        });
        assert!(
            out.contains("TORUS_ASYNC_VALIDATE"),
            "startup log missing:\n{out}"
        );
        assert!(
            out.contains("enabled=true"),
            "enabled state not logged:\n{out}"
        );
        assert!(
            out.contains("enabled=false"),
            "disabled state not logged:\n{out}"
        );
    }

    /// Run `f` with this thread's tracing events captured (fmt, no ANSI) and
    /// return the text. One process-wide default subscriber backs every
    /// capture, so tests sharing a process (`cargo test`) can all use it.
    fn capture_logs(f: impl FnOnce()) -> String {
        use std::io::Write;
        #[derive(Clone, Default)]
        struct Buf(Arc<std::sync::Mutex<Vec<u8>>>);
        impl Write for Buf {
            fn write(&mut self, b: &[u8]) -> std::io::Result<usize> {
                self.0.lock().unwrap().extend_from_slice(b);
                Ok(b.len())
            }
            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        impl<'a> tracing_subscriber::fmt::MakeWriter<'a> for Buf {
            type Writer = Buf;
            fn make_writer(&'a self) -> Buf {
                self.clone()
            }
        }
        /// The global default for threads without a capture: records nothing,
        /// but its interest in every callsite is "sometimes". tracing caches
        /// each callsite's interest for the whole process, and while the
        /// capture is the only live subscriber that interest comes from the
        /// default of whichever thread hits the callsite first, so a first
        /// hit elsewhere (no subscriber) was cached as never (650a9fa5).
        struct Sometimes;
        impl tracing::Subscriber for Sometimes {
            fn register_callsite(&self, _: &'static tracing::Metadata<'static>) -> tracing::subscriber::Interest {
                tracing::subscriber::Interest::sometimes()
            }
            fn enabled(&self, _: &tracing::Metadata<'_>) -> bool {
                false
            }
            fn new_span(&self, _: &tracing::span::Attributes<'_>) -> tracing::span::Id {
                tracing::span::Id::from_u64(1)
            }
            fn record(&self, _: &tracing::span::Id, _: &tracing::span::Record<'_>) {}
            fn record_follows_from(&self, _: &tracing::span::Id, _: &tracing::span::Id) {}
            fn event(&self, _: &tracing::Event<'_>) {}
            fn enter(&self, _: &tracing::span::Id) {}
            fn exit(&self, _: &tracing::span::Id) {}
        }
        static GLOBAL: std::sync::Once = std::sync::Once::new();
        GLOBAL.call_once(|| tracing::subscriber::set_global_default(Sometimes).expect("no other global subscriber"));
        let buf = Buf::default();
        let subscriber = tracing_subscriber::fmt()
            .with_writer(buf.clone())
            .with_ansi(false)
            .finish();
        tracing::subscriber::with_default(subscriber, f);
        let out = String::from_utf8(buf.0.lock().unwrap().clone()).unwrap();
        out
    }

    fn signed_order_batch_action(nonce: u64, n_orders: usize) -> SignedNativeAction {
        let key = k256::ecdsa::SigningKey::from_slice(&[42u8; 32]).unwrap();
        torus_types::eip712::sign_native_action(
            big_order_batch_action(nonce, n_orders).action,
            nonce,
            &key,
        )
    }

    /// Task 3 (S459) happy-path invariant: `mirror_or_drop_native` durably stores
    /// every selected body and returns the selection UNCHANGED on a healthy store.
    /// Guards against regressing the proposer-side mirror out of the hot path (a
    /// silent regression would re-open the leader half of the wedge).
    #[test]
    fn produce_block_bodies_durable() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let actions = vec![sign_claim_rewards(1), signed_order_batch_action(2, 400)];
        let with_senders: Vec<(torus_types::Address, SignedNativeAction)> = actions
            .iter()
            .map(|a| (a.recover_sender().unwrap(), a.clone()))
            .collect();

        let app = TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);
        let expected_selection = bincode::serialize(&with_senders).unwrap();
        let original_allocation = with_senders.as_ptr();
        let (kept, bodies, hashes) = app.mirror_or_drop_native(with_senders);
        assert_eq!(
            hashes,
            actions.iter().map(torus_types::compute_action_hash).collect::<Vec<_>>()
        );
        assert_eq!(kept.as_ptr(), original_allocation);
        assert_eq!(
            bincode::serialize(&kept).unwrap(),
            expected_selection,
            "a healthy durable mirror keeps every selected action"
        );
        assert_eq!(
            bincode::serialize(&bodies).unwrap(),
            bincode::serialize(&actions).unwrap()
        );
        for a in &actions {
            let hash = torus_types::compute_action_hash(a);
            assert!(
                mempool.get_native_da(&hash).is_some(),
                "every proposed body must be durable in the DA store after mirror_or_drop_native"
            );
        }
    }

    #[test]
    fn produce_block_mirror_failure_drops_both_vectors_and_requeues() {
        let (config, state_db) = make_test_config_and_db();
        let dir = tempfile::tempdir().unwrap();
        drop(StateDb::open(dir.path()).unwrap());
        let readonly = StateDb::open_read_only(dir.path()).unwrap();
        let mempool = Arc::new(Mempool::new(
            readonly,
            torus_mempool::MempoolConfig::default(),
        ));
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let app = TorusApp::new(
            state_db,
            &config,
            Some(metrics.clone()),
            Some(mempool.clone()),
            None,
        );
        let (tagged, bodies, hashes) = app.mirror_or_drop_native(Vec::new());
        assert!(tagged.is_empty() && bodies.is_empty() && hashes.is_empty());
        assert_eq!(mempool.da_flush_failures(), 0);
        let action = signed_order_batch_action(1, 400);
        let (tagged, bodies, hashes) =
            app.mirror_or_drop_native(vec![(action.recover_sender().unwrap(), action)]);
        assert!(
            tagged.is_empty() && bodies.is_empty() && hashes.is_empty(),
            "failed mirror must propose and push no bodies"
        );
        assert_eq!(mempool.da_flush_failures(), 1);
        assert_eq!(metrics.proposer_body_mirror_failures.get(), 1);
        // A second failed write proves that the existing mempool retry queue
        // retained the batch even though neither proposal vector escaped.
        mempool.flush_da_mirrors();
        assert_eq!(mempool.da_flush_failures(), 2);
    }

    /// s68: bodies ingest already stored are not rewritten by the proposer. On
    /// a read-only DA store any write fails, so a proposal that keeps its
    /// already-stored body proves the write was skipped. The returned hashes
    /// are the bodies' action hashes, in order.
    #[test]
    fn produce_block_mirror_skips_bodies_already_durable() {
        let (config, state_db) = make_test_config_and_db();
        let action = signed_order_batch_action(1, 400);
        let dir = tempfile::tempdir().unwrap();
        {
            let rw = StateDb::open(dir.path()).unwrap();
            torus_state::NativeDaStore::new(rw).put(&action).unwrap();
        }
        let readonly = StateDb::open_read_only(dir.path()).unwrap();
        let mempool = Arc::new(Mempool::new(
            readonly,
            torus_mempool::MempoolConfig::default(),
        ));
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let app = TorusApp::new(
            state_db,
            &config,
            Some(metrics.clone()),
            Some(mempool.clone()),
            None,
        );
        let (kept, bodies, hashes) =
            app.mirror_or_drop_native(vec![(action.recover_sender().unwrap(), action.clone())]);
        assert_eq!(kept.len(), 1, "an already-stored body stays in the proposal");
        assert_eq!(bodies.len(), 1);
        assert_eq!(hashes, vec![torus_types::compute_action_hash(&action)]);
        assert_eq!(mempool.da_flush_failures(), 0, "no write was attempted");
        assert_eq!(metrics.proposer_body_mirror_failures.get(), 0);
        assert_eq!(metrics.proposer_body_mirror_written.get(), 0);
    }

    #[test]
    fn produce_block_without_mempool_keeps_matching_body_vectors() {
        let app = TorusApp::stub();
        let action = signed_order_batch_action(1, 400);
        let selected = vec![(action.recover_sender().unwrap(), action.clone())];
        let (tagged, bodies, hashes) = app.mirror_or_drop_native(selected.clone());
        assert_eq!(
            bincode::serialize(&tagged).unwrap(),
            bincode::serialize(&selected).unwrap()
        );
        assert_eq!(hashes, vec![torus_types::compute_action_hash(&action)]);
        assert_eq!(
            bincode::serialize(&bodies).unwrap(),
            bincode::serialize(&vec![action]).unwrap()
        );
    }

    /// T8-integration piece 4 (RED-first): a VALIDATING peer that decodes a full
    /// inline `TorusBlock` proposal must ALSO custody the body's erasure shards — not
    /// just the proposer. Only then are there `k` distinct shard sources; with
    /// proposer-only custody there is a single source and every lagging peer falls
    /// back to whole-body pull (the s338 hotspot). n=4 live set ⇒ params (k=2, n=4),
    /// so all 4 shards must be custodied after `decode_proposal_and_ensure_durable`.
    /// RED on HEAD: the validate path mirrored the whole body but never custodied
    /// shards ⇒ `get_shard` returned `None`.
    #[test]
    fn validate_block_custodies_shards_torusblock() {
        // Custody is OFF by default (s128); this test covers the custody-ON path.
        let _custody = super::shard_custody_test_override::force(true);
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let action = sign_claim_rewards(1);
        let hash = torus_types::compute_action_hash(&action);

        // Sanity: derived params for the n=4 live set are exactly (k=2, n=4).
        let params = torus_state::ErasureParams::for_validator_set(4);
        assert_eq!((params.k, params.n), (2, 4));

        // Precondition: no shards custodied yet (validate has not run).
        assert!(
            mempool.get_shard(&hash, 0).is_none(),
            "precondition: no shard 0 custodied before validation"
        );

        // A FULL inline TorusBlock datum (bodies inline).
        let block = make_block(1, vec![action.clone()]);
        let datum = encode_proposal_datum(&block, false);

        let mut app =
            TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);
        app.last_validator_set = make_validator_set(4);

        match app.decode_proposal_and_ensure_durable(&datum) {
            Ok(b) => assert_eq!(b.native_actions.len(), 1),
            Err(_) => panic!("legacy full TorusBlock must decode as Valid, not short-circuit"),
        }

        // The invariant: the validating peer custodied all n=4 shards, so it is now a
        // distinct shard source (kills the single-source hotspot).
        for i in 0..params.n as u16 {
            assert!(
                mempool.get_shard(&hash, i).is_some(),
                "validator must custody shard {i} after validate (k distinct sources)"
            );
        }
    }

    /// T8-integration piece 4 (RED-first), compact path: same custody invariant when
    /// the proposal is a `CompactBlock` (bodies out-of-band). The body is pre-loaded
    /// into the DA store (models push/pull delivery) so the hot reconstruct succeeds;
    /// after decode the validating peer must have custodied the body's shards.
    /// RED on HEAD: the compact branch reconstructed the body but never custodied
    /// shards ⇒ `get_shard` returned `None`.
    #[test]
    fn validate_block_custodies_shards_compactblock() {
        // Custody is OFF by default (s128); this test covers the custody-ON path.
        let _custody = super::shard_custody_test_override::force(true);
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let action = sign_claim_rewards(2);
        let hash = torus_types::compute_action_hash(&action);

        // Pre-load the body so the compact hot-reconstruct finds it in the DA store
        // (models the out-of-band push/pull delivery a validating peer sees).
        mempool
            .mirror_native_to_da(&[action.clone()])
            .expect("mirror body into DA store");

        // Precondition: body durable, but shards NOT yet custodied.
        assert!(
            mempool.get_native_da(&hash).is_some(),
            "precondition: body durable before validation"
        );
        assert!(
            mempool.get_shard(&hash, 0).is_none(),
            "precondition: no shard 0 custodied before validation"
        );

        // A COMPACT datum (native_action_hashes only; bodies out-of-band).
        let block = make_block(1, vec![action.clone()]);
        let datum = encode_proposal_datum(&block, true);

        let mut app =
            TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);
        app.last_validator_set = make_validator_set(4);

        match app.decode_proposal_and_ensure_durable(&datum) {
            Ok(b) => assert_eq!(b.native_actions.len(), 1),
            Err(_) => panic!("compact block with a pre-loaded body must decode as Valid"),
        }

        let params = torus_state::ErasureParams::for_validator_set(4);
        for i in 0..params.n as u16 {
            assert!(
                mempool.get_shard(&hash, i).is_some(),
                "validator (compact path) must custody shard {i} after validate"
            );
        }
    }

    /// s128 owner decision: shard custody is OFF by default until T3.1. With no
    /// override and `TORUS_SHARD_CUSTODY` unset, a validating peer mirrors the
    /// whole body (durability) but custodies NO shards, on both the full
    /// `TorusBlock` and the `CompactBlock` decode paths.
    #[test]
    fn validate_block_custodies_no_shards_by_default() {
        assert!(
            !matches!(
                std::env::var("TORUS_SHARD_CUSTODY").ok().as_deref().map(str::trim),
                Some("1")
            ),
            "run this test without TORUS_SHARD_CUSTODY=1 in the environment"
        );
        assert!(
            super::shard_custody_test_override::get().is_none(),
            "no override on this thread"
        );
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let full = sign_claim_rewards(1);
        let compact = sign_claim_rewards(2);
        let full_hash = torus_types::compute_action_hash(&full);
        let compact_hash = torus_types::compute_action_hash(&compact);
        mempool
            .mirror_native_to_da(std::slice::from_ref(&compact))
            .expect("mirror compact body into DA store");

        let mut app =
            TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);
        app.last_validator_set = make_validator_set(4);

        let full_datum = encode_proposal_datum(&make_block(1, vec![full.clone()]), false);
        match app.decode_proposal_and_ensure_durable(&full_datum) {
            Ok(b) => assert_eq!(b.native_actions.len(), 1),
            Err(_) => panic!("full TorusBlock must decode as Valid"),
        }
        let compact_datum = encode_proposal_datum(&make_block(2, vec![compact.clone()]), true);
        match app.decode_proposal_and_ensure_durable(&compact_datum) {
            Ok(b) => assert_eq!(b.native_actions.len(), 1),
            Err(_) => panic!("compact block with a pre-loaded body must decode as Valid"),
        }

        // Durability is unchanged: the full-block body was mirrored.
        assert!(mempool.get_native_da(&full_hash).is_some(), "full body durable");
        let params = torus_state::ErasureParams::for_validator_set(4);
        for hash in [&full_hash, &compact_hash] {
            for i in 0..params.n as u16 {
                assert!(
                    mempool.get_shard(hash, i).is_none(),
                    "default (custody off): validator must custody no shard {i}"
                );
            }
        }
    }

    /// s84 (vote after body): the pre-vote data check. A replica votes only on
    /// `Held`: the datum matches `data_hash`, decodes, its header's action count
    /// matches the body, and every referenced native body is in the DA store.
    #[test]
    fn check_block_data_holds_only_a_complete_well_formed_body() {
        use hotstuff_rs::hotstuff::types::PhaseCertificate;
        use hotstuff_rs::types::data_types::BlockHeight;
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let mut app = TorusApp::new(state_db.clone(), &config, None, Some(mempool.clone()), None);
        let hs_block = |datums: Vec<Vec<u8>>, data_hash: [u8; 32]| {
            Block::new(
                BlockHeight::new(1),
                PhaseCertificate::genesis_pc(),
                CryptoHash::new(data_hash),
                Data::new(datums.into_iter().map(Datum::new).collect()),
            )
        };
        let bound = |datum: Vec<u8>| {
            let hash = TorusApp::hash_datum(&datum);
            hs_block(vec![datum], hash)
        };
        // Every block here sits on the genesis justify: no parent lookup.
        let genesis_only = |_: &CryptoHash| -> ParentHeader { unreachable!() };
        let action = sign_claim_rewards(2);
        let torus_block = make_block(1, vec![action.clone()]);
        let compact = bound(encode_proposal_datum(&torus_block, true));

        // Body referenced out of band and not local yet: not held.
        assert_eq!(
            app.check_proposal_data(&compact, genesis_only),
            BlockDataCheck::Missing
        );
        mempool
            .mirror_native_to_da(&[action])
            .expect("mirror body into DA store");
        assert_eq!(
            app.check_proposal_data(&compact, genesis_only),
            BlockDataCheck::Held
        );
        // A full block carries its bodies; an empty one references none.
        assert_eq!(
            app.check_proposal_data(
                &bound(encode_proposal_datum(&torus_block, false)),
                genesis_only
            ),
            BlockDataCheck::Held
        );
        assert_eq!(
            app.check_proposal_data(
                &bound(encode_proposal_datum(&make_block(1, vec![]), true)),
                genesis_only
            ),
            BlockDataCheck::Held
        );

        // Structural failures: never held, whatever is in the DA store.
        let datum = encode_proposal_datum(&torus_block, true);
        assert_eq!(
            app.check_proposal_data(&hs_block(vec![datum], [7; 32]), genesis_only),
            BlockDataCheck::Invalid,
            "data does not match data_hash"
        );
        assert_eq!(
            app.check_proposal_data(&hs_block(vec![], TorusApp::hash_datum(&[])), genesis_only),
            BlockDataCheck::Invalid,
            "no datum"
        );
        assert_eq!(
            app.check_proposal_data(&bound(vec![0xff; 3]), genesis_only),
            BlockDataCheck::Invalid,
            "undecodable datum"
        );
        let mut miscounted = torus_block.clone();
        miscounted.header.native_action_count = 2;
        for compact in [true, false] {
            assert_eq!(
                app.check_proposal_data(
                    &bound(encode_proposal_datum(&miscounted, compact)),
                    genesis_only
                ),
                BlockDataCheck::Invalid,
                "header action count != body (compact={compact}): execution would fail-stop"
            );
        }

        // T1.5 fail-stop: never vote for blocks this node will not execute.
        app.exec_failed.store(true, Ordering::SeqCst);
        assert_eq!(
            app.check_proposal_data(&compact, genesis_only),
            BlockDataCheck::Invalid
        );
    }

    /// FIX 1 (S443): the catch-up gate. A leader whose local committed frontier
    /// (`last_header.height == 0` here, a fresh/rejoined node) lags the parent height
    /// by more than the threshold MUST propose an EMPTY payload even with a full
    /// mempool — re-proposing stale session-signed actions from an un-caught-up view
    /// is what detonated the t15 suicide chain. Once the parent is within the
    /// threshold (node caught up) the same call selects the full mempool.
    /// RED at aff21fe: selection ignored the lag and returned all 100 actions.
    #[test]
    fn catch_up_gate_proposes_empty_while_lagging() {
        let (config, state_db) = make_test_config_and_db();
        let mempool = Arc::new(Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        let base = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_millis() as u64;
        for i in 0..100u64 {
            let mut seed = [0u8; 32];
            seed[..8].copy_from_slice(&(i + 1).to_le_bytes());
            let key = k256::ecdsa::SigningKey::from_slice(&seed).unwrap();
            let a = torus_types::eip712::sign_native_action(
                NativeAction::ClaimRewards,
                base + i,
                &key,
            );
            let s = a.recover_sender().unwrap();
            mempool.add_native_action_presigned(s, a).unwrap();
        }

        let app = TorusApp::new(state_db.clone(), &config, None, Some(mempool), None);
        assert_eq!(app.last_header.height, 0, "precondition: fresh/stale local frontier");

        // Parent height far ahead of our applied frontier → EMPTY payload.
        let parent_hdr = test_parent_at(&app, 918);
        let (native_lag, _evm) = app.select_block_payload(
            &parent_hdr,
            &NoAncestry,
            30_000_000,
            0,
            1_000_000_000,
            1_000_000_000,
        );
        assert!(
            native_lag.is_empty(),
            "lagging leader must propose an EMPTY payload, got {}",
            native_lag.len()
        );

        // Parent within the catch-up threshold → normal full selection resumes.
        let parent_hdr = test_parent_at(&app, 1);
        let (native_ok, _) = app.select_block_payload(
            &parent_hdr,
            &NoAncestry,
            30_000_000,
            0,
            1_000_000_000,
            1_000_000_000,
        );
        assert!(
            !native_ok.is_empty(),
            "a caught-up leader must select from its mempool"
        );
    }

    /// One PlaceOrderBatch action carrying `n_orders` orders (dummy signature — the
    /// proposal-size test below only measures encoded bytes, so the signature value
    /// is irrelevant here). Mirrors the bench's bs=N order shape.
    fn big_order_batch_action(nonce: u64, n_orders: usize) -> SignedNativeAction {
        use torus_types::{ActionSignature, OrderType, PlaceOrderParams, Signature, TimeInForce};
        let order = PlaceOrderParams {
            market_id: 1,
            is_buy: true,
            price: FixedPoint::from_raw(6_000_000_000_000),
            quantity: FixedPoint::from_raw(FixedPoint::SCALE),
            order_type: OrderType::Limit,
            time_in_force: TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        SignedNativeAction {
            action: NativeAction::PlaceOrderBatch(vec![order; n_orders]),
            nonce,
            signature: ActionSignature::Eip712(Signature {
                v: 27,
                r: [0u8; 32],
                s: [0u8; 32],
            }),
        }
    }

    /// Task 9 (scale milestone, deterministic proof): the bs=500 flood collapsed
    /// because a block of ~50k orders serializes to ~2.5 MB as a FULL TorusBlock —
    /// far over the then-256 KB `max_consensus_message_size` — so the proposal could
    /// not disseminate and the chain stalled (mem 41ca452). The COMPACT encoding
    /// carries only action hashes, so the SAME block fits comfortably: this is the
    /// encoding change that lets the bs=500 flood hold and unblocks the path to 400k
    /// orders/sec. The collapse reproduces against today's raised gate too: the full
    /// block is ~2.5 MB, over the 1 MB accept limit.
    #[test]
    fn compact_proposal_holds_where_full_block_collapsed_at_bs500() {
        // Mirrors torus-network `NetworkConfig::default().max_consensus_message_size`
        // (torus-consensus has no torus-network dep). O5 raised it 256 KB -> 1 MB;
        // keep in sync with config.rs.
        const MAX_CONSENSUS_MESSAGE_SIZE: usize = 1024 * 1024;

        // The bs=500 block shape: 100 actions x 500-order batches = 50k orders.
        let actions: Vec<SignedNativeAction> = (0..100)
            .map(|i| big_order_batch_action(i as u64, 500))
            .collect();
        let block = make_block(9, actions);

        let full = encode_proposal_datum(&block, false);
        let compact = encode_proposal_datum(&block, true);

        assert!(
            full.len() > MAX_CONSENSUS_MESSAGE_SIZE,
            "full block ({} bytes) exceeds the 256KB consensus limit — reproduces the bs=500 collapse",
            full.len()
        );
        assert!(
            compact.len() < MAX_CONSENSUS_MESSAGE_SIZE,
            "compact block ({} bytes) fits the 256KB consensus limit — the fix",
            compact.len()
        );
        // Bodies are entirely out-of-band: compact is orders-of-magnitude smaller.
        assert!(
            compact.len() * 50 < full.len(),
            "compact ({} bytes) must be >50x smaller than full ({} bytes)",
            compact.len(),
            full.len()
        );
    }

    #[test]
    fn compactblock_reconstructs_from_da_store() {
        // Reproduction of the livelock fix: a CompactBlock referencing a native body
        // that lives ONLY in the durable DA store -- never admitted to the ephemeral
        // nonce-gated mempool -- must reconstruct. Previously reconstruction read the
        // mempool, missed, and the block was rejected (+ peer blacklisted on the sync
        // path), wedging the chain (root cause, mem 28e1a821).
        let (config, state_db) = make_test_config_and_db();

        let body = sign_claim_rewards(123);
        let body_hash = torus_types::compute_action_hash(&body);

        let mempool = Arc::new(torus_mempool::Mempool::new(
            state_db.clone(),
            torus_mempool::MempoolConfig::default(),
        ));
        // Mirror to the DA store WITHOUT mempool admission (mirror_native_to_da does
        // not touch the in-memory pool) -- exactly the "in DA, not in mempool" state.
        let _ = mempool.mirror_native_to_da(std::slice::from_ref(&body));
        assert!(
            mempool.get_native_by_hash(&body_hash).is_none(),
            "precondition: body is NOT in the ephemeral mempool pool"
        );
        assert!(
            mempool.get_native_da(&body_hash).is_some(),
            "precondition: body IS in the durable DA store"
        );

        let app = TorusApp::new(state_db.clone(), &config, None, Some(mempool), None);

        // A CompactBlock referencing the body by hash reconstructs from the DA store.
        let full = make_block(1, vec![body.clone()]);
        let compact = CompactBlock::from_block(&full);
        let reconstructed = app
            .reconstruct_compact_from_da(&compact)
            .expect("CompactBlock must reconstruct from the DA store");
        assert_eq!(reconstructed.native_actions.len(), 1);
        assert_eq!(
            torus_types::compute_action_hash(&reconstructed.native_actions[0]),
            body_hash,
            "reconstructed body must match the referenced hash"
        );

        // A body present in NEITHER store -> typed miss (Err of the missing hashes),
        // the signal the rare pull-fallback consumes (Task 6) -- not a hard reject
        // that blacklists a peer.
        let unknown = make_block(2, vec![sign_claim_rewards(999)]);
        let unknown_compact = CompactBlock::from_block(&unknown);
        let missing = app
            .reconstruct_compact_from_da(&unknown_compact)
            .expect_err("an absent body must report a typed miss");
        assert_eq!(missing.len(), 1);
    }

    #[test]
    fn no_replay_when_already_applied() {
        let (config, state_db) = make_test_config_and_db();
        let block = make_block(5, vec![sign_claim_rewards(200)]);

        persist_block_for_test(&state_db, &block);

        state_db
            .put_cf_raw(
                CF_CONSENSUS_META,
                META_NATIVE_APPLIED_HEIGHT,
                &5u64.to_be_bytes(),
            )
            .unwrap();

        let app = TorusApp::new(state_db.clone(), &config, None, None, None);
        assert_eq!(read_native_applied_height(&state_db), Some(5));
        assert_eq!(app.last_header.height, 0);
    }

    /// FIX 6 / F-1 (S443): crash-in-hole recovery. A node killed while a live body
    /// hole was open can have heights committed (manifest written) whose HEADERS
    /// never persisted. On reboot `find_last_committed_height` (header frontier) sees
    /// no gap, so `replay_committed` parks nothing — yet the manifest holds a
    /// committed height ABOVE the applied frontier. Boot must reconcile the manifest
    /// and PARK that height for heal, not silently stall execution forever.
    /// RED at aff21fe: boot ignored the manifest → `exec_next_height == None`,
    /// `deferred_exec` empty → execution would wait forever on the next live commit.
    #[test]
    fn boot_reconciles_committed_manifest_above_header_frontier() {
        let (config, state_db) = make_test_config_and_db();

        // Headers + applied marker end at height 4 (a clean, gap-free frontier).
        for h in 1..=4u64 {
            persist_block_for_test(&state_db, &make_block(h, vec![]));
        }
        state_db
            .put_cf_raw(
                CF_CONSENSUS_META,
                META_NATIVE_APPLIED_HEIGHT,
                &4u64.to_be_bytes(),
            )
            .unwrap();

        // But height 5 was committed pre-crash: its datum lives ONLY in the durable
        // commit manifest (headers/bodies never persisted — the crash-in-hole window).
        // T5.3: the manifest lives in the consensus DB.
        let datum = bincode::serialize(&make_block(5, vec![])).unwrap();
        let cdb = make_test_consensus_db();
        cdb.put_cf_raw(
            torus_state::cf::CF_COMMIT_MANIFEST,
            &5u64.to_be_bytes(),
            &datum,
        )
        .unwrap();

        // Sanity: replay itself sees no gap (frontier == applied == 4).
        assert_eq!(find_last_committed_height(&state_db), Some(4));

        let app =
            TorusApp::try_new_with_manifest_db(state_db.clone(), cdb, &config, None, None, None)
                .unwrap();

        assert_eq!(
            app.exec_next_height,
            Some(5),
            "boot must park execution at the manifest-only committed height 5"
        );
        assert!(
            app.deferred_exec.contains_key(&5),
            "boot must seed the manifest-only committed height into the exec queue for heal"
        );
    }

    /// Codex r2 finding 1, boot: a manifest-backed height parked at boot (the
    /// F-1 reconcile here; the FIX 1b hole loop makes the same
    /// `park_deferred(recovery_exec_source(..))` call) as a Compact reference
    /// counts every action hash before the metrics attach; attaching
    /// publishes it, and its first materialization lowers it once to the
    /// normal count.
    #[test]
    fn exec_aware_boot_compact_park_counts_all_hashes() {
        let (config, state_db) = make_test_config_and_db();
        for h in 1..=4u64 {
            persist_block_for_test(&state_db, &make_block(h, vec![]));
        }
        state_db
            .put_cf_raw(
                CF_CONSENSUS_META,
                META_NATIVE_APPLIED_HEIGHT,
                &4u64.to_be_bytes(),
            )
            .unwrap();
        let key = k256::ecdsa::SigningKey::from_slice(&[171u8; 32]).unwrap();
        let cancel = |nonce: u64| {
            torus_types::eip712::sign_native_action(
                NativeAction::CancelOrder { order_id: 1 },
                nonce,
                &key,
            )
        };
        let actions = vec![sign_claim_rewards(5), cancel(6), cancel(7)];
        let b5 = make_block(5, actions.clone());
        let cdb = make_test_consensus_db();
        persist_commit_manifest(&cdb, 5, &encode_proposal_datum(&b5, true));

        let mempool = exec_aware_mempool(&state_db);
        let app = TorusApp::try_new_with_manifest_db(
            state_db.clone(),
            cdb,
            &config,
            None,
            Some(mempool.clone()),
            None,
        )
        .unwrap();
        assert!(matches!(
            app.deferred_exec.get(&5).map(|e| &e.source),
            Some(ExecSource::Compact(_))
        ));
        assert_eq!(
            mempool.committed_unexecuted_normal(),
            3,
            "boot Compact park counts every action hash"
        );
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        mempool.set_metrics(metrics.clone());
        assert_eq!(metrics.mempool_native_committed_unexecuted.get(), 3);
        assert_eq!(mempool.note_exec_committed(5, &actions), 1, "lowered");
        assert_eq!(mempool.committed_unexecuted_normal(), 1);
        assert_eq!(metrics.mempool_native_committed_unexecuted.get(), 1);
        drop(app);
    }

    #[test]
    fn replay_empty_block_marks_applied() {
        let (config, state_db) = make_test_config_and_db();
        let block = make_block(3, vec![]);

        let block_hash = alloy_primitives::keccak256(&block.header.canonical_header_bytes());
        let header_json = serde_json::to_vec(&block.header).unwrap();
        let mut data = Vec::with_capacity(32 + header_json.len());
        data.extend_from_slice(block_hash.as_slice());
        data.extend_from_slice(&header_json);
        state_db
            .put_cf_raw(CF_BLOCK_HEADERS, &block.header.height.to_be_bytes(), &data)
            .unwrap();
        // D12: the applied parent's header (the nonce-window cursor; a
        // non-genesis block without it fail-stops, Codex r1).
        persist_block_header(&state_db, &make_block(2, vec![]));

        // ADAPTED for T156-F2 whole-gap replay: replay now walks the ENTIRE
        // [applied+1, committed] gap, not just the single top committed height.
        // This test only persists height 3's header, so seed applied=2 to make
        // the gap exactly {3}; otherwise heights 1..2 would be missing headers
        // and replay would (correctly) fail-stop on the hole at height 1. The
        // intent is unchanged: an empty committed block in the gap is executed
        // (empty body) and marked applied.
        state_db
            .put_cf_raw(CF_CONSENSUS_META, META_NATIVE_APPLIED_HEIGHT, &2u64.to_be_bytes())
            .unwrap();

        let _app = TorusApp::new(state_db.clone(), &config, None, None, None);
        assert_eq!(
            read_native_applied_height(&state_db),
            Some(3),
            "empty block should be marked as applied"
        );
    }

