    /// R02 branch 3: an oracle aggregate row that does not decode on this
    /// node (a delisted market's: only the block mark table reads it) is a
    /// local fault: the block fail-stops (exec_failed, marker unchanged,
    /// nothing flushed). Once the row is repaired, the restart's replay
    /// matches a run that never had it. RED before: the row read as "no
    /// mark" and the block flushed.
    #[test]
    fn r02_undecodable_oracle_aggregate_fail_stops_block() {
        use torus_state::cf::CF_NATIVE_ORACLE;
        let garbage_key = [b"agg".as_slice(), &7u64.to_be_bytes()].concat();
        let ms = block_time_ms(1);
        let (a, b) = (r02_claim(ms), r02_claim(ms + 1));
        let mut blocks = vec![make_block(1, vec![a]), make_block(2, vec![b])];
        link_blocks(&mut blocks);
        for on in [false, true] {
            let (_c, db_ref) = make_test_config_and_db();
            let ctx = pipeline_ctx(&db_ref, on, None);
            for blk in &blocks {
                dispatch_and_execute(&ctx, &db_ref, blk);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: control");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db_ref), Some(2), "on={on}");

            let (dir, db) = r02_reopenable_db();
            let ctx = pipeline_ctx(&db, on, None);
            dispatch_and_execute(&ctx, &db, &blocks[0]);
            assert!(ctx.pipeline_barrier(), "on={on}");
            drop(ctx);
            // The row goes bad on disk; a fresh context (as after a
            // restart) reads it (the resident rows are built from the DB).
            db.put_cf_raw(CF_NATIVE_ORACLE, &garbage_key, b"garbage").unwrap();
            let ctx = pipeline_ctx(&db, on, None);
            let durable = persist_committed_block_durably(&db, &blocks[1]);
            let before = dump_all_cfs(&db);
            ctx.execute_committed_block_with(&blocks[1], vec![], durable);
            ctx.pipeline_barrier();
            assert!(ctx.exec_failed.load(Ordering::SeqCst), "on={on}: must fail-stop");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(1), "on={on}: block 2 not applied");
            assert_dumps_equal(&before, &dump_all_cfs(&db), "R02: nothing of block 2 flushed");

            // Repair the row, restart, replay block 2.
            db.delete_cf_raw(CF_NATIVE_ORACLE, &garbage_key).unwrap();
            drop(db);
            let db = StateDb::open(&dir).expect("reopen");
            let ctx = pipeline_ctx(&db, false, None);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: replay");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(2), "on={on}");
            assert_dumps_equal(&dump_all_cfs(&db_ref), &dump_all_cfs(&db), "R02: replay vs no fault");
        }
    }
    /// R02 branch 5 fixture: block 1 a native claim; block 2 a native claim
    /// plus one EVM tx of a funded key (`input` to `to`). `setup` funds it.
    fn r02_evm_blocks(
        key: &k256::ecdsa::SigningKey,
        to: alloy_primitives::TxKind,
        input: Vec<u8>,
    ) -> (Vec<TorusBlock>, SignedNativeAction) {
        let ms = block_time_ms(1);
        let (a, b) = (r02_claim(ms), r02_claim(ms + 1));
        let mut b2 = make_block(2, vec![b.clone()]);
        b2.evm_transactions = vec![signed_eip1559(key, 0, to, input)];
        b2.header.evm_tx_count = 1;
        let mut blocks = vec![make_block(1, vec![a]), b2];
        link_blocks(&mut blocks);
        (blocks, b)
    }

    fn r02_fund(db: &StateDb, key: &k256::ecdsa::SigningKey) {
        let funded = revm::state::AccountInfo {
            balance: U256::from(10u128.pow(18)),
            nonce: 0,
            code_hash: KECCAK_EMPTY_CODE,
            code: None,
            account_id: None,
        };
        db.put_account(&k256_address(key), &funded).unwrap();
    }

    fn r02_evm_nonce(db: &StateDb, key: &k256::ecdsa::SigningKey) -> u64 {
        db.get_account(&k256_address(key)).unwrap().map_or(0, |a| a.nonce)
    }

    /// The OrderBookReader precompile (0x0800).
    fn r02_reader_precompile() -> alloy_primitives::TxKind {
        use torus_core::precompiles::{precompile_address, ADDR_ORDER_BOOK_READER};
        alloy_primitives::TxKind::Call(precompile_address(ADDR_ORDER_BOOK_READER))
    }

    /// The status of block `height`'s EVM tx 0 receipt (`None`: no receipt).
    fn r02_receipt_status(db: &StateDb, height: u64) -> Option<bool> {
        let key = [height.to_be_bytes().as_slice(), &0u32.to_be_bytes()].concat();
        db.get_cf_raw(torus_state::cf::CF_RECEIPTS, &key)
            .unwrap()
            .map(|r| serde_json::from_slice::<torus_types::Receipt>(&r).unwrap().status)
    }

    /// R02 branch 5 (owner option A): the block's EVM execution reports a
    /// LOCAL storage fault (`EvmError::LocalFault`: a precompile's read failed
    /// on this node and the provider aborted instead of answering; torus-evm
    /// `r02_precompile_fault_tests` drives a real read there). The block
    /// fail-stops: exec_failed, applied marker unchanged, nothing flushed
    /// (neither the EVM bundle nor the native part); the restart's replay
    /// matches a run without the fault. Serial and pipelined. RED before:
    /// the failed EVM section was logged and skipped and the block flushed.
    #[test]
    fn r02_evm_local_fault_fail_stops_block() {
        let key = k256::ecdsa::SigningKey::from_slice(&[0x55; 32]).unwrap();
        let (blocks, b) = r02_evm_blocks(&key, alloy_primitives::TxKind::Create, vec![0x60, 0x01, 0x60, 0x00, 0x55]);
        r02_assert_fault_fail_stops_then_replays(&blocks, &|db| r02_fund(db, &key), ReplayFault::EvmLocalFault, &|db| {
            assert!(r02_nonce_consumed(db, &b));
            assert_eq!(r02_evm_nonce(db, &key), 1, "the EVM tx ran");
            assert_eq!(r02_receipt_status(db, 2), Some(true));
        });
        // Item 7 option 0 (task 3.7): the same on the EVM fast path.
        r02_assert_fault_fail_stops_then_replays_fast(
            &blocks,
            &|db| r02_fund(db, &key),
            ReplayFault::EvmLocalFault,
            &|db| {
                assert!(r02_nonce_consumed(db, &b));
                assert_eq!(r02_evm_nonce(db, &key), 1, "the EVM tx ran");
                assert_eq!(r02_receipt_status(db, 2), Some(true));
            },
        );
    }

    /// T5.3 x item 7 option 0 (merge of main into T5.3): a fast-path EVM
    /// block's header + body go through the commit-persist writer like any
    /// other block. The exec thread's rows come from the writer's ticket (both
    /// durable), so the EVM block still takes the pipelined path (not
    /// `evm.serial_flag_on.nondurable`); its rows are in the state DB before
    /// it executes; the writer hands each height to the manifest pruner; and
    /// the state DB ends identical to the dispatch-time write.
    #[test]
    fn t53_evm_fast_path_block_rows_come_from_the_commit_persist_writer() {
        let key = k256::ecdsa::SigningKey::from_slice(&[0x58; 32]).unwrap();
        let (blocks, _b) = r02_evm_blocks(
            &key,
            alloy_primitives::TxKind::Create,
            vec![0x60, 0x01, 0x60, 0x00, 0x55],
        );
        // Reference: the dispatch-time write (manifest in the state DB).
        let (_c, db_ref) = make_test_config_and_db();
        r02_fund(&db_ref, &key);
        let mut ctx = pipeline_ctx(&db_ref, true, None);
        ctx.evm_fast_path = true;
        for b in &blocks {
            dispatch_and_execute(&ctx, &db_ref, b);
        }
        assert!(ctx.pipeline_barrier());
        drop(ctx);

        let (_c, db) = make_test_config_and_db();
        r02_fund(&db, &key);
        let mut ctx = pipeline_ctx(&db, true, None);
        ctx.evm_fast_path = true;
        let (pruned_tx, pruned_rx) = std::sync::mpsc::channel();
        let writer = CommitPersistWriter::spawn(
            db.clone(),
            ManifestPruner::detached(pruned_tx),
            None,
            HeaderHookSlot::default(),
        );
        for b in &blocks {
            let h = b.header.height;
            let rows = writer.submit(b.clone()).wait();
            assert_eq!(
                rows,
                DurableRows {
                    header: true,
                    body: true
                },
                "the writer landed {h}"
            );
            assert!(
                db.get_cf_raw(CF_BLOCK_HEADERS, &h.to_be_bytes())
                    .unwrap()
                    .is_some(),
                "header of {h} before it executes"
            );
            assert!(
                load_replay_body(&db, h).is_some(),
                "body of {h} before it executes"
            );
            assert_eq!(
                pruned_rx.recv_timeout(std::time::Duration::from_secs(10)),
                Ok(h),
                "{h} handed to the manifest pruner"
            );
            ctx.execute_committed_block_with(b, vec![], rows);
        }
        drop(writer);
        assert!(ctx.pipeline_barrier());
        assert!(!ctx.exec_failed.load(Ordering::SeqCst));
        {
            let paths = ctx.test_paths.lock().unwrap();
            assert_eq!(paths.get("block.pipelined.evm"), Some(&1), "{paths:?}");
            assert_eq!(
                paths.get("evm.serial_flag_on.nondurable"),
                None,
                "{paths:?}"
            );
        }
        drop(ctx);
        assert_eq!(r02_receipt_status(&db, 2), Some(true));
        assert_dumps_equal(
            &dump_all_cfs(&db_ref),
            &dump_all_cfs(&db),
            "writer path vs dispatch-time write",
        );
    }

    /// Item 7 option 0 (task 2.3): the serial EVM section's read of the EVM
    /// trie stale marker failing is a local fault: the block fail-stops
    /// (exec_failed, marker unchanged, nothing flushed) and the restart's
    /// replay matches the no-fault run, serial and pipelined.
    #[test]
    fn o0_evm_trie_stale_marker_read_fault_fail_stops_block() {
        let key = k256::ecdsa::SigningKey::from_slice(&[0x57; 32]).unwrap();
        let (blocks, b) = r02_evm_blocks(
            &key,
            alloy_primitives::TxKind::Create,
            vec![0x60, 0x01, 0x60, 0x00, 0x55],
        );
        r02_assert_fault_fail_stops_then_replays(
            &blocks,
            &|db| r02_fund(db, &key),
            ReplayFault::EvmTrieStaleRead,
            &|db| {
                assert!(r02_nonce_consumed(db, &b));
                assert_eq!(r02_evm_nonce(db, &key), 1, "the EVM tx ran");
                assert!(!torus_state::incremental::is_evm_trie_stale(db).unwrap());
            },
        );
    }

    /// R02 branch 5: every other EVM outcome keeps today's handling, no
    /// fail-stop. (a) An ordinary EVM execution error (`EvmError::Internal`):
    /// logged, the EVM section skipped, the native part applied. (b) A real
    /// precompile revert (unknown selector to 0x0800): a reverted receipt,
    /// the block applied.
    #[test]
    fn r02_ordinary_evm_errors_do_not_fail_stop() {
        let key = k256::ecdsa::SigningKey::from_slice(&[0x56; 32]).unwrap();
        let cases = [
            ("(a) section error", alloy_primitives::TxKind::Create, vec![0x60, 0x01, 0x60, 0x00, 0x55], Some(ReplayFault::EvmSectionError), 0, None),
            ("(b) precompile revert", r02_reader_precompile(), vec![0xDE, 0xAD, 0xBE, 0xEF], None, 1, Some(false)),
        ];
        for (what, to, input, fault, evm_nonce, receipt) in cases {
            let (blocks, b) = r02_evm_blocks(&key, to, input);
            for on in [false, true] {
                let (_c, db) = make_test_config_and_db();
                r02_fund(&db, &key);
                let mut ctx = pipeline_ctx(&db, on, None);
                dispatch_and_execute(&ctx, &db, &blocks[0]);
                ctx.test_replay_fault = fault;
                dispatch_and_execute(&ctx, &db, &blocks[1]);
                assert!(ctx.pipeline_barrier(), "{what} on={on}");
                assert!(!ctx.exec_failed.load(Ordering::SeqCst), "{what} on={on}: no fail-stop");
                drop(ctx);
                assert_eq!(read_native_applied_height(&db), Some(2), "{what} on={on}");
                assert!(r02_nonce_consumed(&db, &b), "{what} on={on}: native part applied");
                assert_eq!(r02_evm_nonce(&db, &key), evm_nonce, "{what} on={on}");
                assert_eq!(r02_receipt_status(&db, 2), receipt, "{what} on={on}");
            }
        }
    }

    /// A contract that reads its storage slot 0 (`PUSH1 0 SLOAD STOP`).
    const EVM_DB_FAULT_READER: alloy_primitives::Address =
        alloy_primitives::Address::new([0xC0; 20]);

    /// Fund `key` and deploy [`EVM_DB_FAULT_READER`] (code in CF_CODE; no
    /// storage rows).
    fn evm_db_fault_setup(db: &StateDb, key: &k256::ecdsa::SigningKey) {
        r02_fund(db, key);
        let code = [0x60, 0x00, 0x54, 0x00];
        let code_hash = alloy_primitives::keccak256(code);
        db.put_code(&code_hash, &code).unwrap();
        let contract = revm::state::AccountInfo {
            balance: U256::ZERO,
            nonce: 1,
            code_hash,
            code: None,
            account_id: None,
        };
        db.put_account(&EVM_DB_FAULT_READER, &contract).unwrap();
    }

    /// [`dump_all_cfs`] without the CF `skip` (absent from the DB).
    fn dump_cfs_except(state_db: &StateDb, skip: &str) -> Vec<CfDump> {
        torus_state::cf::ALL_CF_NAMES
            .iter()
            .filter(|cf| **cf != skip)
            .map(|cf| (*cf, StateBackend::iterate_cf(state_db, cf, None).unwrap()))
            .collect()
    }

    /// A read of this node's DB that fails INSIDE revm (here: the SLOAD of
    /// the block's EVM tx, on a DB opened without CF_STORAGE, so
    /// `StateError::MissingColumnFamily`; no test seam) is a local fault:
    /// revm's `EVMError::Database` becomes `EvmError::LocalFault` (torus-evm
    /// `evm_db_fault_tests`) and the block fail-stops: exec_failed, applied
    /// marker unchanged, nothing of the block flushed (neither the EVM nor
    /// the native part). Restart (reopen with every CF) replays the block and
    /// lands exactly the state of a run without the fault. Serial and
    /// pipelined. RED before: the error was `EvmError::Internal`, the block
    /// ran without its EVM writes on this node only (the native part applied,
    /// the EVM nonce not consumed): a divergence.
    #[test]
    fn evm_db_read_fault_fail_stops_block() {
        assert_storage_cf_fault_fail_stops_then_replays_runs(
            0x57,
            alloy_primitives::TxKind::Call(EVM_DB_FAULT_READER),
            vec![],
            torus_state::cf::CF_STORAGE,
            "a revm DB read fault",
            // Item 7 option 0 (task 3.7): and on the EVM fast path.
            &[(false, false), (true, false), (true, true)],
        );
    }

    /// The same local fault one step later: the block's EVM tx is a plain
    /// value transfer (revm never reads CF_STORAGE), so execution succeeds
    /// and the post-bundle state-root compute of `validate_block_for_catchup`
    /// is the first read of the missing CF (`account_storage`, full scan:
    /// `StateError::MissingColumnFamily`, `BridgeError::State`; no test
    /// seam). A local fault: the block fail-stops exactly as above (marker,
    /// every CF unchanged; the restart replay equals a run without the fault).
    /// Serial and pipelined. RED before: `BridgeError::State` took the app's
    /// generic EVM arm (logged), so the block ran without its EVM writes on
    /// this node only (native part applied, EVM nonce not consumed).
    /// Item 7 option 0 (task 3.7): no EVM-fast-path run: on the fast path E
    /// computes no EVM root (`RootMode::Skip`), so this read does not exist;
    /// W's EVM trie step reads the hashed mirror and trie CFs, and its own
    /// failure marks the trie stale (task 2.3, F4).
    #[test]
    fn evm_state_root_compute_fault_fail_stops_block() {
        assert_storage_cf_fault_fail_stops_then_replays(
            0x58,
            alloy_primitives::TxKind::Call(alloy_primitives::Address::new([0xD0; 20])),
            vec![],
            torus_state::cf::CF_STORAGE,
            "a state-root compute read fault",
        );
    }

    /// F1 (s128): a read of this node's DB that fails INSIDE a Torus
    /// precompile (here: 0x0801 getBalances on a DB opened without
    /// CF_NATIVE_BALANCES, so the balance point read returns
    /// `CoreError::State(MissingColumnFamily)`; no test seam) is a local
    /// fault: the provider records it and aborts the execution, the executor
    /// returns `EvmError::LocalFault` (torus-evm `r02_precompile_fault_tests`
    /// `f1_*`), and the block fail-stops exactly as for a revm DB read fault
    /// (marker and every CF unchanged; the restart replay equals a run
    /// without the fault). Serial and pipelined. RED before: the read error
    /// was a precompile revert, so block 2 applied with a reverted receipt on
    /// this node only (a divergence).
    #[test]
    fn precompile_read_fault_fail_stops_block() {
        use torus_core::precompiles::{precompile_address, ADDR_BALANCE_READER};
        let key = k256::ecdsa::SigningKey::from_slice(&[0x59; 32]).unwrap();
        let mut input = alloy_primitives::keccak256(b"getBalances(address)")[..4].to_vec();
        input.extend_from_slice(&[0u8; 12]);
        input.extend_from_slice(k256_address(&key).as_slice());
        assert_storage_cf_fault_fail_stops_then_replays_runs(
            0x59,
            alloy_primitives::TxKind::Call(precompile_address(ADDR_BALANCE_READER)),
            input,
            torus_state::cf::CF_NATIVE_BALANCES,
            "a precompile read fault",
            // Item 7 option 0 (task 3.7): and on the EVM fast path.
            &[(false, false), (true, false), (true, true)],
        );
    }

    /// F1 Codex review P1: a precompile SCAN of a CF this node lacks (0x0803
    /// getStakingInfo's delegation scan on a DB opened without
    /// CF_STAKING_DELEGATIONS) fail-stops the block like a point read. RED
    /// before: `scan_prefix_metered` read the missing CF as empty, so block 2
    /// applied with a SUCCESS receipt and a gas charge only this node
    /// computes. (CF_STAKING_DELEGATIONS, not getMarkets' CF_NATIVE_MARKETS:
    /// block 1 already reads the markets CF outside the EVM.)
    #[test]
    fn precompile_scan_fault_fail_stops_block() {
        use torus_core::precompiles::{precompile_address, ADDR_STAKING_READER};
        let key = k256::ecdsa::SigningKey::from_slice(&[0x5A; 32]).unwrap();
        let mut input = alloy_primitives::keccak256(b"getStakingInfo(address)")[..4].to_vec();
        input.extend_from_slice(&[0u8; 12]);
        input.extend_from_slice(k256_address(&key).as_slice());
        assert_storage_cf_fault_fail_stops_then_replays_runs(
            0x5A,
            alloy_primitives::TxKind::Call(precompile_address(ADDR_STAKING_READER)),
            input,
            torus_state::cf::CF_STAKING_DELEGATIONS,
            "a precompile scan fault",
            // Item 7 option 0 (task 3.7): and on the EVM fast path.
            &[(false, false), (true, false), (true, true)],
        );
    }

    /// Body of [`evm_db_read_fault_fail_stops_block`] /
    /// [`evm_state_root_compute_fault_fail_stops_block`] /
    /// [`precompile_read_fault_fail_stops_block`]: block 2's one EVM tx (key
    /// `seed`, to `to`, calldata `input`) runs on a DB opened without the
    /// column family `missing` (CF_STORAGE for the first two).
    fn assert_storage_cf_fault_fail_stops_then_replays(
        seed: u8,
        to: alloy_primitives::TxKind,
        input: Vec<u8>,
        missing: &'static str,
        what: &str,
    ) {
        assert_storage_cf_fault_fail_stops_then_replays_runs(
            seed,
            to,
            input,
            missing,
            what,
            &[(false, false), (true, false)],
        );
    }

    /// [`assert_storage_cf_fault_fail_stops_then_replays`] for the runs
    /// `(exec pipeline on, EVM fast path on)`. Item 7 option 0 (task 3.7):
    /// a fast-path run adds task 3.5's step 4 (no status / side row of the
    /// faulted height) and the replay re-hashing exactly it.
    fn assert_storage_cf_fault_fail_stops_then_replays_runs(
        seed: u8,
        to: alloy_primitives::TxKind,
        input: Vec<u8>,
        missing: &'static str,
        what: &str,
        runs: &[(bool, bool)],
    ) {
        let key = k256::ecdsa::SigningKey::from_slice(&[seed; 32]).unwrap();
        let (blocks, b) = r02_evm_blocks(&key, to, input);
        let (last, prefix) = blocks.split_last().unwrap();
        for &(on, fast) in runs {
            // Control: a healthy DB.
            let (_c, db_ref) = make_test_config_and_db();
            evm_db_fault_setup(&db_ref, &key);
            let mut ctx = pipeline_ctx(&db_ref, on, None);
            ctx.evm_fast_path = fast;
            for blk in &blocks {
                dispatch_and_execute(&ctx, &db_ref, blk);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: control");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db_ref), Some(2), "on={on}");
            assert!(r02_nonce_consumed(&db_ref, &b), "on={on}");
            assert_eq!(r02_evm_nonce(&db_ref, &key), 1, "on={on}: the EVM tx ran");
            assert_eq!(r02_receipt_status(&db_ref, 2), Some(true), "on={on}");

            // Fault: this node's DB has no `missing` CF.
            torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
            let dir = scratch_db_dir("torus-evm-db-fault");
            let mut opts = rocksdb::Options::default();
            opts.create_if_missing(true);
            opts.create_missing_column_families(true);
            let cfs = torus_state::cf::ALL_CF_NAMES
                .iter()
                .copied()
                .filter(|cf| *cf != missing);
            let db = StateDb::from_existing_db(rocksdb::DB::open_cf(&opts, &dir, cfs).unwrap());
            list_test_markets(&db);
            torus_state::running_hash::configure_activation(&db, Some(1))
                .expect("configure running hash activation");
            evm_db_fault_setup(&db, &key);
            let mut ctx = pipeline_ctx(&db, on, None);
            ctx.evm_fast_path = fast;
            for blk in prefix {
                dispatch_and_execute(&ctx, &db, blk);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            assert!(
                !ctx.exec_failed.load(Ordering::SeqCst),
                "on={on}: prefix never reads storage"
            );
            let durable = persist_committed_block_durably(&db, last);
            let before = dump_cfs_except(&db, missing);
            ctx.execute_committed_block_with(last, vec![], durable);
            if fast {
                assert_eq!(
                    ctx.test_paths.lock().unwrap().get("block.pipelined.evm"),
                    Some(&1),
                    "fast: {what}: the faulted EVM block took the fast path"
                );
            }
            ctx.pipeline_barrier();
            assert!(
                ctx.exec_failed.load(Ordering::SeqCst),
                "on={on} fast={fast}: {what} must fail-stop"
            );
            drop(ctx);
            if fast {
                r02_assert_no_side_rows(&db, 2, &format!("fast: {what}"));
            }
            assert_eq!(
                read_native_applied_height(&db),
                Some(1),
                "on={on}: block 2 not applied"
            );
            assert!(
                !r02_nonce_consumed(&db, &b),
                "on={on}: native part not applied"
            );
            assert_dumps_equal(
                &before,
                &dump_cfs_except(&db, missing),
                "nothing of the block flushed",
            );

            // Restart: reopen with every CF, replay the faulted height.
            drop(db);
            let db = StateDb::open(&dir).expect("reopen");
            torus_state::running_hash::capture_begin(&db);
            let ctx = pipeline_ctx(&db, false, None);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: replay");
            drop(ctx);
            let rehashed: Vec<u64> = torus_state::running_hash::capture_take(&db)
                .iter()
                .map(|(h, _)| *h)
                .collect();
            assert_eq!(
                rehashed,
                vec![2],
                "on={on} fast={fast}: the replay re-hashes the faulted height"
            );
            assert_eq!(read_native_applied_height(&db), Some(2), "on={on}");
            assert_dumps_equal(
                &dump_all_cfs(&db_ref),
                &dump_all_cfs(&db),
                "restart replay vs no fault",
            );
        }
    }

    /// A contract that emits one log (`PUSH1 0x2a PUSH1 0 PUSH1 0 LOG1 STOP`).
    const RECEIPTS_FAULT_LOGGER: alloy_primitives::Address =
        alloy_primitives::Address::new([0xC1; 20]);

    /// Fund `key` and deploy [`RECEIPTS_FAULT_LOGGER`].
    fn receipts_fault_setup(db: &StateDb, key: &k256::ecdsa::SigningKey) {
        r02_fund(db, key);
        let code = [0x60, 0x2a, 0x60, 0x00, 0x60, 0x00, 0xa1, 0x00];
        let code_hash = alloy_primitives::keccak256(code);
        db.put_code(&code_hash, &code).unwrap();
        let contract = revm::state::AccountInfo {
            balance: U256::ZERO,
            nonce: 1,
            code_hash,
            code: None,
            account_id: None,
        };
        db.put_account(&RECEIPTS_FAULT_LOGGER, &contract).unwrap();
    }

    /// The block-metadata write of an EVM block (`commit_block_metadata`:
    /// header, body, receipts with their logs, tx indices; its own batch,
    /// written before the block's flush) fails on this node — here a real
    /// fault: the DB has no CF_TX_HASH_TO_LOCATION, so the batch is never
    /// written (`StateError::MissingColumnFamily`; no test seam). A local
    /// write fault: the block fail-stops (exec_failed, applied marker
    /// unchanged, nothing of the block flushed). Restart (reopen with every
    /// CF) replays the block, which writes the receipts again: every CF
    /// (receipts, logs, tx indices included) equals a run without the fault.
    /// Serial and pipelined (an EVM block is always a barrier). RED before:
    /// the error was only logged, the block was applied without receipts,
    /// and the replay skipped the applied block: a permanent hole on this
    /// node only (RPC served no receipt / logs for the tx).
    #[test]
    fn evm_block_metadata_write_fault_fail_stops_block() {
        use torus_state::cf::{CF_RECEIPTS, CF_TX_HASH_TO_LOCATION};
        let key = k256::ecdsa::SigningKey::from_slice(&[0x58; 32]).unwrap();
        let (blocks, b) = r02_evm_blocks(
            &key,
            alloy_primitives::TxKind::Call(RECEIPTS_FAULT_LOGGER),
            vec![],
        );
        let (last, prefix) = blocks.split_last().unwrap();
        for on in [false, true] {
            // Control: a healthy DB.
            let (_c, db_ref) = make_test_config_and_db();
            receipts_fault_setup(&db_ref, &key);
            let ctx = pipeline_ctx(&db_ref, on, None);
            for blk in &blocks {
                dispatch_and_execute(&ctx, &db_ref, blk);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: control");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db_ref), Some(2), "on={on}");
            assert_eq!(r02_evm_nonce(&db_ref, &key), 1, "on={on}: the EVM tx ran");
            assert_eq!(r02_receipt_status(&db_ref, 2), Some(true), "on={on}");
            let receipt_key = [2u64.to_be_bytes().as_slice(), &0u32.to_be_bytes()].concat();
            let receipt: torus_types::Receipt = serde_json::from_slice(
                &db_ref
                    .get_cf_raw(CF_RECEIPTS, &receipt_key)
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
            assert_eq!(receipt.logs.len(), 1, "on={on}: the tx's log");
            assert!(
                db_ref
                    .get_cf_raw(CF_TX_HASH_TO_LOCATION, receipt.tx_hash.as_slice())
                    .unwrap()
                    .is_some(),
                "on={on}: tx index"
            );

            // Fault: this node's DB has no CF_TX_HASH_TO_LOCATION.
            torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
            let dir = scratch_db_dir("torus-receipts-write-fault");
            let mut opts = rocksdb::Options::default();
            opts.create_if_missing(true);
            opts.create_missing_column_families(true);
            let cfs = torus_state::cf::ALL_CF_NAMES
                .iter()
                .copied()
                .filter(|cf| *cf != CF_TX_HASH_TO_LOCATION);
            let db = StateDb::from_existing_db(rocksdb::DB::open_cf(&opts, &dir, cfs).unwrap());
            list_test_markets(&db);
            torus_state::running_hash::configure_activation(&db, Some(1))
                .expect("configure running hash activation");
            receipts_fault_setup(&db, &key);
            let ctx = pipeline_ctx(&db, on, None);
            for blk in prefix {
                dispatch_and_execute(&ctx, &db, blk);
            }
            assert!(ctx.pipeline_barrier(), "on={on}");
            assert!(
                !ctx.exec_failed.load(Ordering::SeqCst),
                "on={on}: the prefix writes no block metadata"
            );
            let durable = persist_committed_block_durably(&db, last);
            let before = dump_cfs_except(&db, CF_TX_HASH_TO_LOCATION);
            ctx.execute_committed_block_with(last, vec![], durable);
            ctx.pipeline_barrier();
            assert!(
                ctx.exec_failed.load(Ordering::SeqCst),
                "on={on}: a block-metadata write fault must fail-stop"
            );
            drop(ctx);
            assert_eq!(
                read_native_applied_height(&db),
                Some(1),
                "on={on}: block 2 not applied"
            );
            assert!(
                !r02_nonce_consumed(&db, &b),
                "on={on}: native part not applied"
            );
            assert_eq!(r02_evm_nonce(&db, &key), 0, "on={on}: EVM part not applied");
            assert_dumps_equal(
                &before,
                &dump_cfs_except(&db, CF_TX_HASH_TO_LOCATION),
                "nothing of the block flushed",
            );

            // Restart: reopen with every CF, replay the faulted height.
            drop(db);
            let db = StateDb::open(&dir).expect("reopen");
            let ctx = pipeline_ctx(&db, false, None);
            let (_last, parked) = TorusApp::replay_committed(&db, &ctx);
            assert_eq!(parked, None);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "on={on}: replay");
            drop(ctx);
            assert_eq!(read_native_applied_height(&db), Some(2), "on={on}");
            assert_eq!(
                r02_receipt_status(&db, 2),
                Some(true),
                "on={on}: receipt rewritten"
            );
            assert_dumps_equal(
                &dump_all_cfs(&db_ref),
                &dump_all_cfs(&db),
                "restart replay vs no fault",
            );
        }
    }

    /// Item 6 C1, P6: crash between E's hand-off and W's write with R on —
    /// block 3 ran on R carried from block 1 (advanced over the empty 2) on
    /// top of pending(2); W's write of 2 fails, nothing of 2/3 is durable,
    /// R is not stashed. A restarted node (fresh holder: R rebuilt cold)
    /// replays 2 and 3 and lands exactly the state of a run without R.
    #[test]
    fn resident_rows_crash_between_handoff_and_write_restart_identical() {
        let blocks = pipeline_fixture_blocks();
        let first3 = &blocks[..3];

        let (_c0, db_ref) = make_test_config_and_db();
        fund_pipeline_fixture(&db_ref);
        let mut ctx_ref = pipeline_ctx(&db_ref, false, None);
        ctx_ref.test_no_resident_rows = true;
        for b in first3 {
            dispatch_and_execute(&ctx_ref, &db_ref, b);
        }
        drop(ctx_ref);
        let dump_ref = dump_all_cfs(&db_ref);

        let (_c1, state_db) = make_test_config_and_db();
        fund_pipeline_fixture(&state_db);
        let gate = crate::exec_pipeline::WorkerGate::new();
        let ctx = pipeline_ctx(&state_db, true, Some(gate.clone()));
        dispatch_and_execute(&ctx, &state_db, &first3[0]);
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), Some(1));

        gate.hold();
        dispatch_and_execute(&ctx, &state_db, &first3[1]); // empty: Marker(2) parked, R advanced
        assert!(gate.wait_received(2));
        assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), Some(2));
        let db_t = state_db.clone();
        let b3 = first3[2].clone();
        let t = std::thread::spawn(move || {
            dispatch_and_execute(&ctx, &db_t, &b3); // engine(3) on R + pending(2); hand-off blocks
            ctx
        });
        std::thread::sleep(std::time::Duration::from_millis(200));
        assert!(!t.is_finished());
        gate.fail_next();
        gate.release();
        let ctx = t.join().unwrap();
        assert!(ctx.exec_failed.load(Ordering::SeqCst));
        {
            let mut holder = ctx.resident_books.lock().unwrap();
            assert_eq!(holder.rows_builds(), 1, "block 3 reused R (no rebuild)");
            assert_eq!(holder.rows_height(), None, "failed hand-off: R not stashed");
        }
        drop(ctx);
        assert_eq!(read_native_applied_height(&state_db), Some(1), "nothing of 2/3 durable");

        let ctx2 = pipeline_ctx(&state_db, false, None);
        let (_last, parked) = TorusApp::replay_committed(&state_db, &ctx2);
        assert_eq!(parked, None);
        assert!(!ctx2.exec_failed.load(Ordering::SeqCst));
        assert_resident_rows_track_db(&ctx2, &state_db, 3, "after the replay");
        assert_eq!(ctx2.resident_books.lock().unwrap().rows_builds(), 1, "restart: R built cold once");
        drop(ctx2);
        assert_dumps_equal(&dump_ref, &dump_all_cfs(&state_db), "crash + restart with R vs serial without R");
    }

    // ======================================================================
    // Item 6 Phase 1 C5 (plan Step 5, P5): warm == cold
    // ======================================================================

    /// Blocks fed, epoch length (boundaries at 50 / 100 / 150 / 200) and the
    /// restart period of the cold replica (7 does not divide 50).
    const C5_BLOCKS: u64 = 210;
    const C5_EPOCH: u64 = 50;
    const C5_RESTART_EVERY: u64 = 7;
    const C5_MARKETS: [u64; 3] = [1, 2, 3];
    /// Traders (signing-key seeds): 81 / 82 also move funds EVM <-> perp,
    /// 84 is thin (margin cuts). Makers quote every market.
    const C5_TRADERS: [u8; 6] = [81, 82, 83, 84, 85, 86];
    const C5_MAKERS: [u8; 2] = [89, 90];
    /// Seeded before block 1: V1 long 10 @100 in market 1 (collateral 40),
    /// V2 short 10 @100 in market 2 (collateral 60): backstop after the
    /// shocks; V3 long 1,100 @100 in market 3 (collateral 6,200; notional
    /// over the chunk threshold, MM 5,500 at 100): stage 1 on the walk, 20%
    /// chunks into bids far thinner than its size (cooldown and pending
    /// rows); S their counterparty.
    const C5_V1: u8 = 91;
    const C5_V2: u8 = 93;
    const C5_V3: u8 = 94;
    const C5_S: u8 = 92;
    const C5_EVM_FUNDING: u128 = 10_000;

    /// splitmix64: the generator's only source of variety (fixed seed, no clock).
    struct C5Rng(u64);

    impl C5Rng {
        fn next(&mut self) -> u64 {
            self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = self.0;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^ (z >> 31)
        }

        fn below(&mut self, n: u64) -> u64 {
            self.next() % n
        }
    }

    /// 3 Active oracle validators; market 1 a placeholder row (no margin
    /// config / shape: defaults), markets 2 and 3 governance-layout rows
    /// (lot 0.001, tick 0.01, initial margin 5% / 10%); traders, makers and
    /// the seeded thin positions funded; 81 / 82 hold EVM balance.
    fn c5_fixture() -> (ChainConfig, StateDb) {
        use torus_core::position::{MarginType, NativeBalance, PositionManager};
        let (mut config, db) = make_test_config_and_db();
        config.epoch_length = C5_EPOCH;
        for (seed, mult) in ORACLE_VALIDATORS {
            oracle_put_validator(&db, seed, mult, torus_economics::ValidatorStatus::Active);
        }
        db.put_cf_raw(torus_state::cf::CF_NATIVE_MARKETS, &1u64.to_be_bytes(), b"listed").unwrap();
        for (m, im) in [(2u64, 5i64), (3, 10)] {
            let row = (
                "BTC".to_string(),
                "USDC".to_string(),
                FixedPoint::SCALE / 1_000,
                FixedPoint::SCALE / 100,
                px(im).raw(),
            );
            db.put_cf_raw(torus_state::cf::CF_NATIVE_MARKETS, &m.to_be_bytes(), &borsh::to_vec(&row).unwrap())
                .unwrap();
        }
        let pm = PositionManager::new(db.clone());
        let fund = |seed: u8, amt: i64| {
            pm.put_native_balance(&oracle_addr(seed), &NativeBalance { available: px(amt), order_margin: FixedPoint::ZERO })
                .unwrap()
        };
        for (i, seed) in C5_TRADERS.into_iter().enumerate() {
            fund(seed, if seed == 84 { 150 } else { 3_000 + 1_000 * i as i64 });
        }
        for seed in C5_MAKERS.into_iter().chain([C5_S]) {
            fund(seed, 1_000_000);
        }
        fund(C5_V1, 40);
        fund(C5_V2, 60);
        fund(C5_V3, 6_200);
        let (v1, v2, s) = (oracle_addr(C5_V1), oracle_addr(C5_V2), oracle_addr(C5_S));
        pm.apply_fill(&v1, 1, true, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&s, 1, false, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&v2, 2, false, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&s, 2, true, px(10), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&oracle_addr(C5_V3), 3, true, px(1_100), px(100), MarginType::Cross).unwrap();
        pm.apply_fill(&s, 3, false, px(1_100), px(100), MarginType::Cross).unwrap();
        for seed in [81u8, 82] {
            fund_evm_balance(&db, oracle_addr(seed), U256::from(C5_EVM_FUNDING * FixedPoint::ONE.raw() as u128));
        }
        (config, db)
    }

    /// What the generator fed (non-vacuity of the input side).
    #[derive(Debug, Default)]
    struct C5Fed {
        empty: u64,
        mark_rounds: u64,
        non_pool_sell_batches: u64,
        cancels: u64,
        transfers: u64,
    }

    /// The P5 sequence: heights 1..=C5_BLOCKS (ts 1000 + h), linked. Oracle
    /// rounds (all 3 validators, all 3 markets) every 5th block plus at
    /// random, marks walking +-2 per round with two shocks (market 1 -15% at
    /// 60: V1 under water; market 2 +18% at 120: V2); a maker requoting
    /// every market each non-empty block (cancel-all every 6th); 1-3 trader
    /// actions: resting limits, crossing limits, two-market sell batches
    /// crossing the bid (the second is a non-pool sell: B-blind top-up),
    /// cancel-alls, EVM <-> perp transfers; ~1/5 of the other blocks empty.
    fn c5_blocks() -> (Vec<TorusBlock>, C5Fed) {
        let mut rng = C5Rng(0xC5_0005);
        let mut fed = C5Fed::default();
        let mut mark = [100i64; 3];
        let mut nonces: std::collections::HashMap<u8, u64> = Default::default();
        // The height being built: nonces sit at its block time (exec's window).
        let cur_h = std::cell::Cell::new(0u64);
        let mut sign = |seed: u8, action: NativeAction| {
            let n = nonces.entry(seed).or_insert(0);
            *n += 1;
            let nonce = NONCE_BASE + cur_h.get() * 1_000 + *n;
            torus_types::eip712::sign_native_action(action, nonce, &oracle_key(seed))
        };
        let order = |m: u64, is_buy: bool, price: i64, qty: i64| torus_types::PlaceOrderParams {
            market_id: m,
            is_buy,
            price: px(price),
            quantity: px(qty),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let units = |v: u128| U256::from(v * FixedPoint::ONE.raw() as u128);
        let mut blocks = Vec::new();
        for h in 1..=C5_BLOCKS {
            cur_h.set(h);
            let mut actions = Vec::new();
            let shock = h == 60 || h == 120;
            let mark_round = h == 1 || h % 5 == 1 || shock || rng.below(4) == 0;
            if mark_round {
                fed.mark_rounds += 1;
                match h {
                    1 => {}
                    60 => mark[0] = mark[0] * 85 / 100,
                    120 => mark[1] = mark[1] * 118 / 100,
                    _ => {
                        for p in &mut mark {
                            *p = (*p + rng.below(5) as i64 - 2).max(50);
                        }
                    }
                }
                for (seed, _) in ORACLE_VALIDATORS {
                    let prices = C5_MARKETS.iter().zip(mark).map(|(m, p)| (*m, px(p))).collect();
                    actions.push(torus_types::eip712::sign_native_action(
                        NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                            prices,
                            timestamp: (1_000 + h) * 1_000,
                        }),
                        NONCE_BASE + h * 1_000 + seed as u64,
                        &oracle_key(seed),
                    ));
                }
            }
            if !mark_round && rng.below(5) == 0 {
                fed.empty += 1;
                blocks.push(make_block(h, actions));
                continue;
            }
            let maker = C5_MAKERS[(h % 2) as usize];
            if h % 6 == 0 {
                actions.push(sign(maker, NativeAction::CancelAllOrders { market_id: None }));
                fed.cancels += 1;
            }
            let mut quotes = Vec::new();
            for (i, m) in C5_MARKETS.into_iter().enumerate() {
                let q = 2 + rng.below(4) as i64;
                quotes.push(order(m, true, mark[i] - 1 - rng.below(2) as i64, q));
                quotes.push(order(m, false, mark[i] + 1 + rng.below(2) as i64, q));
            }
            actions.push(sign(maker, NativeAction::PlaceOrderBatch(quotes)));
            for _ in 0..1 + rng.below(3) {
                let t = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                let mi = rng.below(3) as usize;
                let (m, p) = (C5_MARKETS[mi], mark[mi]);
                let qty = 1 + rng.below(4) as i64;
                let action = match rng.below(10) {
                    0..=3 => {
                        let is_buy = rng.below(2) == 0;
                        let off = 1 + rng.below(3) as i64;
                        NativeAction::PlaceOrder(order(m, is_buy, if is_buy { p - off } else { p + off }, qty))
                    }
                    4 | 5 => {
                        let is_buy = rng.below(2) == 0;
                        NativeAction::PlaceOrder(order(m, is_buy, if is_buy { p + 2 } else { p - 2 }, qty))
                    }
                    6 => {
                        let mj = (mi + 1 + rng.below(2) as usize) % 3;
                        fed.non_pool_sell_batches += 1;
                        NativeAction::PlaceOrderBatch(vec![
                            order(m, false, p - 2, qty),
                            order(C5_MARKETS[mj], false, mark[mj] - 2, qty),
                        ])
                    }
                    7 => {
                        fed.cancels += 1;
                        NativeAction::CancelAllOrders { market_id: (rng.below(2) == 0).then_some(m) }
                    }
                    8 if t == 81 || t == 82 => {
                        fed.transfers += 1;
                        if rng.below(2) == 0 {
                            NativeAction::TransferToPerp { amount: units(100) }
                        } else {
                            NativeAction::TransferToSpot { amount: units(50) }
                        }
                    }
                    _ => {
                        let mj = (mi + 1) % 3;
                        NativeAction::PlaceOrderBatch(vec![
                            order(m, true, p - 1 - rng.below(3) as i64, qty),
                            order(C5_MARKETS[mj], false, mark[mj] + 1 + rng.below(3) as i64, qty),
                        ])
                    }
                };
                actions.push(sign(t, action));
            }
            blocks.push(make_block(h, actions));
        }
        link_blocks(&mut blocks);
        (blocks, fed)
    }

    #[derive(Clone, Copy, Debug, PartialEq)]
    enum C5Replica {
        /// One context for every block.
        Warm,
        /// Context dropped and recreated after every `C5_RESTART_EVERY`th
        /// block: R, its decoded positions, the sums cache and the books
        /// rebuilt cold.
        Restarted,
        /// One context; the sums cache emptied before every block.
        SumsDropped,
    }

    struct C5Run {
        db: StateDb,
        dump: Vec<CfDump>,
        captured: CapturedWrites,
        hash: Option<(u64, [u8; 32])>,
        builds: u64,
        restarts: u64,
        sums_dropped: usize,
        r_rows: usize,
        /// Blocks after which an oracle mark price differed from the block before.
        mark_moves: u64,
        mark_moves_after_last_epoch: u64,
        /// Blocks after which `CF_NATIVE_LIQUIDATION` held cooldown / pending rows.
        liq_row_blocks: u64,
        metrics: Arc<torus_telemetry::Metrics>,
    }

    /// Feed `blocks` through the committed-block path on a fresh
    /// `c5_fixture` DB as `replica`. After every block: no fail-stop, R ==
    /// the DB scan of its CFs and decoded positions == a cold decode
    /// (`assert_resident_rows_track_db`; a restarted context has no R until
    /// its first native block), no shared fallback.
    fn c5_run(
        blocks: &[TorusBlock],
        replica: C5Replica,
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
    ) -> C5Run {
        use torus_state::cf::{CF_NATIVE_LIQUIDATION, CF_NATIVE_ORACLE};
        let (config, db) = c5_fixture();
        torus_state::running_hash::capture_begin(&db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let what = format!("{replica:?} pipelined={pipelined} {mode:?}");
        let new_ctx = || {
            let mut c = make_exec_ctx(&config, &db);
            c.test_book_mode = mode;
            c.metrics = Some(metrics.clone());
            if pipelined {
                c.attach_flush_worker(None);
            }
            c
        };
        let mark_prices = |db: &StateDb| -> Vec<(Vec<u8>, Vec<u8>)> {
            StateBackend::iterate_cf(db, CF_NATIVE_ORACLE, Some(b"agg"))
                .unwrap()
                .into_iter()
                .map(|(k, v)| (k, v[..16].to_vec()))
                .collect()
        };
        let mut ctx = new_ctx();
        let (mut builds, mut restarts, mut sums_dropped) = (0, 0, 0);
        let (mut mark_moves, mut mark_moves_after_last_epoch, mut liq_row_blocks) = (0, 0, 0);
        let mut prev_marks = Vec::new();
        let last = blocks.last().expect("blocks").header.height;
        for b in blocks {
            let h = b.header.height;
            if replica == C5Replica::SumsDropped {
                sums_dropped += ctx.resident_books.lock().unwrap().drop_sums_cache();
            }
            dispatch_and_execute(&ctx, &db, b);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "{what}: fail-stop at {h}");
            if ctx.resident_books.lock().unwrap().rows_builds() == 0 {
                assert_eq!(replica, C5Replica::Restarted, "{what}: R never built by {h}");
                if let Some(w) = ctx.flush_worker.as_ref() {
                    assert!(w.wait_idle(), "{what}: W failed");
                }
                assert_eq!(ctx.resident_books.lock().unwrap().rows_height(), None, "{what}: {h}");
            } else {
                assert_resident_rows_track_db(&ctx, &db, h, &what);
            }
            assert_eq!(ctx.resident_books.lock().unwrap().rows_shared_fallbacks(), 0, "{what}: {h}");
            let marks = mark_prices(&db);
            if marks != prev_marks {
                mark_moves += 1;
                mark_moves_after_last_epoch += u64::from(h > (last / C5_EPOCH) * C5_EPOCH);
                prev_marks = marks;
            }
            // Cooldown / pending rows: tag + trader (the 9-byte previous-mark rows persist).
            liq_row_blocks += u64::from(
                StateBackend::iterate_cf(&db, CF_NATIVE_LIQUIDATION, None).unwrap().iter().any(|(k, _)| k.len() == 21),
            );
            if replica == C5Replica::Restarted && h % C5_RESTART_EVERY == 0 && h < last {
                builds += ctx.resident_books.lock().unwrap().rows_builds();
                restarts += 1;
                drop(ctx);
                ctx = new_ctx();
            }
        }
        // Phase 4 step 2: every R CF (positions and balances through `Users`;
        // `len` counts R's raw rows only).
        let r_rows = ctx.resident_books.lock().unwrap().rows().map_or(0, |r| {
            torus_state::resident_rows::RESIDENT_CFS.iter().map(|cf| r.dump(cf).map_or(0, |d| d.len())).sum()
        });
        builds += ctx.resident_books.lock().unwrap().rows_builds();
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&db);
        let hash = torus_state::running_hash::read_running_hash(&db);
        let dump = dump_all_cfs(&db);
        C5Run {
            db,
            dump,
            captured,
            hash,
            builds,
            restarts,
            sums_dropped,
            r_rows,
            mark_moves,
            mark_moves_after_last_epoch,
            liq_row_blocks,
            metrics,
        }
    }

    /// Item 6 C5 (plan Step 5, P5): warm == cold in one configuration. The
    /// 210 blocks (4 epoch boundaries) through three replicas, each on its
    /// own DB: warm (one context), restarted every 7 blocks (R, decoded
    /// positions, sums cache, marks and books rebuilt cold) and sums-dropped
    /// (cache emptied before every block). R == DB after every block on
    /// each (`c5_run`); identical per-block consensus write sets (every
    /// `h_n`), running hash and full dump; the sequence is non-vacuous.
    /// Returns the warm run.
    fn c5_warm_equals_cold(pipelined: bool, mode: Option<torus_bridge::native_executor::BookMode>) -> C5Run {
        let started = std::time::Instant::now();
        let what = format!("pipelined={pipelined} {mode:?}");
        let (blocks, fed) = c5_blocks();
        assert_eq!(blocks.len() as u64, C5_BLOCKS);
        let warm = c5_run(&blocks, C5Replica::Warm, pipelined, mode);
        let restarted = c5_run(&blocks, C5Replica::Restarted, pipelined, mode);
        let dropped = c5_run(&blocks, C5Replica::SumsDropped, pipelined, mode);

        assert_eq!((warm.builds, dropped.builds), (1, 1), "{what}: R built once");
        assert_eq!(restarted.restarts, (C5_BLOCKS - 1) / C5_RESTART_EVERY, "{what}");
        assert_eq!(restarted.builds, restarted.restarts + 1, "{what}: one cold build per (re)start");
        assert_eq!(
            warm.captured.iter().map(|(h, _)| *h).collect::<Vec<_>>(),
            (1..=C5_BLOCKS).collect::<Vec<_>>(),
            "{what}: every height through the hashed flush"
        );
        assert!(warm.hash.is_some());
        assert_eq!(warm.hash, Some(fold_captured(&warm.captured)), "{what}");
        for (name, other) in [("restarted", &restarted), ("sums dropped", &dropped)] {
            assert_write_sets_equal(&warm.captured, &other.captured, &format!("{what}: warm vs {name}"));
            assert_eq!(warm.hash, other.hash, "{what}: running hash, warm vs {name}");
            assert_dumps_equal(&warm.dump, &other.dump, &format!("{what}: warm vs {name}"));
        }

        // Non-vacuous (the warm replica; the others equal it).
        let pm = torus_core::position::PositionManager::new(warm.db.clone());
        let fills = StateBackend::iterate_cf(&warm.db, torus_state::cf::CF_NATIVE_TRADES, None).unwrap().len();
        // Item 7 step 2 (B16): the dumps compared above cover the bbo rows.
        let bbo_rows = StateBackend::iterate_cf(&warm.db, torus_state::cf::CF_NATIVE_BBO, None).unwrap().len();
        assert!(bbo_rows >= 1, "{what}: bbo rows {bbo_rows}");
        let liquidations = warm.metrics.liquidations_triggered.get();
        let top_ups = warm.metrics.sell_top_ups_full.get() + warm.metrics.sell_top_ups_partial.get();
        let v1 = signed_pos_of(&warm.db, &oracle_addr(C5_V1));
        let v2 = pm.get_position(&oracle_addr(C5_V2), 2).unwrap().map(|p| p.size);
        let v3 = pm.get_position(&oracle_addr(C5_V3), 3).unwrap().map(|p| p.size);
        let funded = U256::from(C5_EVM_FUNDING * FixedPoint::ONE.raw() as u128);
        let evm_moved = [81u8, 82].iter().filter(|&&s| read_evm_balance(&warm.db, oracle_addr(s)) != funded).count();
        println!(
            "C5 {what}: fed {fed:?}; fills {fills}, liquidations {liquidations}, top-ups {top_ups}, \
             mark moves {} ({} after the last epoch boundary), blocks with cooldown / pending rows {}, \
             R rows {}, V1 {v1:?}, V2 {v2:?}, V3 {v3:?}, EVM balances moved {evm_moved}, sums entries dropped {}, \
             restarts {} / builds {}; {:.1} s",
            warm.mark_moves,
            warm.mark_moves_after_last_epoch,
            warm.liq_row_blocks,
            warm.r_rows,
            dropped.sums_dropped,
            restarted.restarts,
            restarted.builds,
            started.elapsed().as_secs_f64(),
        );
        assert!(fed.empty >= 10 && fed.cancels >= 20 && fed.transfers >= 2 && fed.non_pool_sell_batches >= 10, "{fed:?}");
        assert!(fills >= 200, "{what}: fills {fills}");
        assert!(liquidations >= 2, "{what}: liquidations {liquidations}");
        assert!(top_ups >= 20, "{what}: B-blind top-ups {top_ups}");
        assert!(warm.mark_moves >= 50 && warm.mark_moves_after_last_epoch >= 1, "{what}: mark moves");
        assert!(warm.liq_row_blocks >= 1, "{what}: cooldown / pending rows");
        assert!(warm.r_rows >= 30, "{what}: R rows {}", warm.r_rows);
        assert_eq!(v1, FixedPoint::ZERO, "{what}: V1 liquidated");
        assert_eq!(v2, None, "{what}: V2 liquidated");
        assert_ne!(v3, Some(px(1_100)), "{what}: V3 liquidated");
        assert_eq!(evm_moved, 2, "{what}: deposits / withdrawals moved EVM balances");
        assert!(dropped.sums_dropped >= 500, "{what}: the cache held entries ({})", dropped.sums_dropped);
        warm
    }

    #[test]
    fn warm_equals_cold_every_block_serial() {
        c5_warm_equals_cold(false, None);
    }

    /// Also serial == pipelined (one more warm run).
    #[test]
    fn warm_equals_cold_every_block_pipelined() {
        let piped = c5_warm_equals_cold(true, None);
        let serial = c5_run(&c5_blocks().0, C5Replica::Warm, false, None);
        assert_write_sets_equal(&serial.captured, &piped.captured, "serial vs pipelined");
        assert_eq!(serial.hash, piped.hash, "serial vs pipelined");
        assert_dumps_equal(&serial.dump, &piped.dump, "serial vs pipelined");
    }

    #[test]
    fn warm_equals_cold_every_block_pipelined_level_authority_chunked() {
        c5_warm_equals_cold(true, Some(torus_bridge::native_executor::BookMode::LevelAuthorityChunked));
    }

    // ======================================================================
    // Item 6 Phase 5 step 1 (`docs/plans/item6-phase5-impl.md` Task 1.2): the
    // long differential harness, reused by every later step. Two nodes, each
    // on its own DB, run the same random block stream in lockstep: one on the
    // reference path (today's overlay writes, the Phase 4 path), one on the
    // typed path. After every block: the consensus write set of every height
    // hashed since the last block (`h_n`), the durable markers, the action
    // status row of every height that became durable, and the full CF dump
    // once `dump_every` more heights are durable; at the end the running hash
    // and the final dump. Step 1 has no typed path yet: both nodes run the
    // reference path, so the harness passes trivially and must catch a
    // planted divergence (`harness_detects_one_flipped_row`).
    // ======================================================================

    /// Which path a node of the Phase 5 differential runs.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum P5Path {
        /// Today's overlay writes (the Phase 4 path).
        Reference,
        /// Phase 5's typed writes (from step 2 on).
        Typed,
    }

    /// The node's switch for `path`. Step 1 has no typed path: both paths
    /// run today's overlay writes (step 2 sets the typed path here).
    fn p5_configure(ctx: &mut ExecutionContext, path: P5Path) {
        let _ = (ctx, path);
    }

    /// The checkpoint interval of a pipelined node.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum P5Ckpt {
        /// Interval 0: every block flushed.
        PerBlock,
        /// A checkpoint every 5 blocks (the 15 s-like cell).
        Every5,
        /// Never by time: attest heights, barriers and shutdown only.
        Never,
    }

    #[derive(Clone, Copy, Debug)]
    struct P5Config {
        pipelined: bool,
        mode: torus_bridge::native_executor::BookMode,
        ckpt: P5Ckpt,
    }

    /// Every configuration: serial in every BookMode; pipelined per block in
    /// every mode, and with a checkpoint every 5 blocks and never by time in
    /// the non-deferred modes (Classic, OrderRows: modes 2/3 refuse an
    /// interval, `check_checkpoint_book_mode`).
    fn p5_configs() -> Vec<P5Config> {
        use torus_bridge::native_executor::BookMode;
        let modes = [
            BookMode::Classic,
            BookMode::OrderRows,
            BookMode::LevelAuthority,
            BookMode::LevelAuthorityChunked,
        ];
        let mut out: Vec<P5Config> = modes
            .iter()
            .map(|&mode| P5Config {
                pipelined: false,
                mode,
                ckpt: P5Ckpt::PerBlock,
            })
            .collect();
        for mode in modes {
            out.push(P5Config {
                pipelined: true,
                mode,
                ckpt: P5Ckpt::PerBlock,
            });
            if matches!(mode, BookMode::Classic | BookMode::OrderRows) {
                out.push(P5Config {
                    pipelined: true,
                    mode,
                    ckpt: P5Ckpt::Every5,
                });
                out.push(P5Config {
                    pipelined: true,
                    mode,
                    ckpt: P5Ckpt::Never,
                });
            }
        }
        out
    }

    /// The validator the stream's buffered slashes hit.
    fn p5_slashed() -> Address {
        Address::repeat_byte(0x77)
    }

    /// `p2_fixture` (C5's markets, oracle validators, traders, makers and
    /// the thin positions, V4), every trader and maker with a large EVM
    /// balance (EVM -> perp refunds keep long streams trading; EVM lockbox
    /// deposits), and a registered validator for the slashes; the EVM trie
    /// built over them. Epoch length 50 (C5's).
    fn p5_fixture() -> (ChainConfig, StateDb) {
        let (config, db) = p2_fixture();
        let evm = U256::from(1_000_000_000u128 * FixedPoint::ONE.raw() as u128);
        for seed in C5_TRADERS.into_iter().chain(C5_MAKERS) {
            fund_evm_balance(&db, oracle_addr(seed), evm);
        }
        register_proposer(&db, p5_slashed());
        // The EVM trie over the accounts written above, as the node builds it
        // at boot (otherwise the first EVM bundle starts a partial trie and
        // the next EVM block's incremental root fails its full-scan check).
        torus_state::incremental::ensure_trie_built(&db).unwrap();
        (config, db)
    }

    /// One block of the stream, with what the consensus side hands execution.
    struct P5Block {
        block: TorusBlock,
        slashes: Vec<PendingSlash>,
        /// The block fails with a local fault (a nonce write): fail-stop,
        /// then a restart replays the committed blocks above the marker.
        fatal: bool,
    }

    /// What the stream holds (non-vacuity of the input side).
    #[derive(Debug, Default)]
    struct P5Fed {
        native: u64,
        empty: u64,
        evm_blocks: u64,
        evm_deposits: u64,
        evm_creates: u64,
        slashes: u64,
        epoch_boundaries: u64,
        shocks: u64,
        refunds: u64,
        stops: u64,
        reduce_only: u64,
        fatal: u64,
    }

    /// The Phase 5 stream: heights 1..=n (ts 1000 + h), linked. C5 / P2's
    /// mark walk (oracle rounds every 5th block plus at random), pulled back
    /// towards 100 and shocked every 150 blocks (-15% / +18%, one market in
    /// turn): liquidations and ADL. Each non-empty block: a maker requotes
    /// every market (its cancel-all every 4th block), V4 rests early, 2-5
    /// trader actions from P2's mix (resting / crossing limits, stop-limits,
    /// stop-markets, cancel-alls, two-market batches; a third of the places
    /// reduce-only), now and then an EVM -> perp refund or a perp -> EVM
    /// transfer. EVM blocks at about one EVM height in four (h % 5 == 0):
    /// lockbox deposits (credited by the next block's CoreWriter drain) and
    /// contract creations, with the EVM nonces tracked. A buffered slash every
    /// 97 blocks; epoch boundaries every 50 (the fixture's epoch length); one
    /// fatal block at 2/5 of the stream; ~1/7 of the other blocks empty.
    fn p5_blocks(n: u64, seed: u64) -> (Vec<P5Block>, P5Fed) {
        let mut rng = C5Rng(seed);
        let mut fed = P5Fed::default();
        let mut mark = [100i64; 3];
        let mut evm_nonce: std::collections::HashMap<u8, u64> = Default::default();
        let lockbox =
            torus_core::precompiles::precompile_address(torus_core::precompiles::ADDR_LOCKBOX);
        let fatal_at = (n * 2 / 5).max(3);
        let units = |v: u128| U256::from(v * FixedPoint::ONE.raw() as u128);
        let order =
            |m: u64, is_buy: bool, price: i64, qty: i64, order_type: torus_types::OrderType| {
                torus_types::PlaceOrderParams {
                    market_id: m,
                    is_buy,
                    price: px(price),
                    quantity: px(qty),
                    order_type,
                    time_in_force: torus_types::TimeInForce::GTC,
                    reduce_only: false,
                    client_order_id: None,
                }
            };
        let limit = |m: u64, is_buy: bool, price: i64, qty: i64| {
            order(m, is_buy, price, qty, torus_types::OrderType::Limit)
        };
        let mut blocks = Vec::new();
        let mut extra: Vec<(Vec<PendingSlash>, bool)> = Vec::new();
        for h in 1..=n {
            // Per-sender nonces in this height's window (D12).
            let mut per_sender: std::collections::HashMap<u8, u64> = Default::default();
            let mut sign = |seed: u8, action: NativeAction| {
                let k = per_sender.entry(seed).or_insert(0);
                *k += 1;
                torus_types::eip712::sign_native_action(
                    action,
                    NONCE_BASE + h * 1_000 + 100 + *k,
                    &oracle_key(seed),
                )
            };
            let mut actions = Vec::new();
            let shock = h % 150 == 60;
            let mark_round = h == 1 || h % 5 == 1 || shock || rng.below(4) == 0;
            if mark_round {
                if shock {
                    fed.shocks += 1;
                    let i = (h / 150 % 3) as usize;
                    mark[i] = if (h / 150) % 2 == 0 {
                        mark[i] * 85 / 100
                    } else {
                        mark[i] * 118 / 100
                    };
                } else if h > 1 {
                    for p in &mut mark {
                        *p = (*p + rng.below(5) as i64 - 2 + (100 - *p).signum()).clamp(50, 200);
                    }
                }
                for (seed, _) in ORACLE_VALIDATORS {
                    let prices = C5_MARKETS
                        .iter()
                        .zip(mark)
                        .map(|(m, p)| (*m, px(p)))
                        .collect();
                    actions.push(torus_types::eip712::sign_native_action(
                        NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                            prices,
                            timestamp: (1_000 + h) * 1_000,
                        }),
                        NONCE_BASE + h * 1_000 + seed as u64,
                        &oracle_key(seed),
                    ));
                }
            }
            let evm = h % TEST_EVM_BLOCK_INTERVAL == 0 && rng.below(4) == 0;
            let slashes = if h % 97 == 0 {
                fed.slashes += 1;
                vec![PendingSlash {
                    validator: p5_slashed(),
                    fraction_bps: 10,
                    reason: SlashReason::DoubleSign,
                    tombstone: false,
                }]
            } else {
                vec![]
            };
            fed.epoch_boundaries += u64::from(h % C5_EPOCH == 0);
            let fatal = h == fatal_at;
            let mut evm_txs = Vec::new();
            if evm {
                fed.evm_blocks += 1;
                for _ in 0..1 + rng.below(2) {
                    let seed = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                    let nonce = evm_nonce.entry(seed).or_insert(0);
                    let key = oracle_key(seed);
                    if rng.below(3) == 0 {
                        fed.evm_creates += 1;
                        evm_txs.push(signed_sstore_create(&key, *nonce));
                    } else {
                        fed.evm_deposits += 1;
                        let wei: u128 = 300 * 10u128.pow(18);
                        let mut calldata =
                            alloy_primitives::keccak256("depositToNative(uint128)".as_bytes())[..4]
                                .to_vec();
                        calldata.extend_from_slice(&U256::from(wei).to_be_bytes::<32>());
                        evm_txs.push(signed_eip1559_with_value(
                            &key,
                            *nonce,
                            alloy_primitives::TxKind::Call(lockbox),
                            calldata,
                            U256::from(wei),
                        ));
                    }
                    *nonce += 1;
                }
            }
            let empty = !mark_round && !evm && slashes.is_empty() && !fatal && rng.below(7) == 0;
            if empty {
                fed.empty += 1;
            } else {
                fed.native += 1;
                let maker = C5_MAKERS[(h % 2) as usize];
                if h % 4 == 0 {
                    actions.push(sign(
                        maker,
                        NativeAction::CancelAllOrders { market_id: None },
                    ));
                }
                let quotes = C5_MARKETS
                    .into_iter()
                    .enumerate()
                    .flat_map(|(i, m)| {
                        let q = 2 + (h as i64 + i as i64) % 4;
                        [
                            limit(m, true, mark[i] - 1 - (h % 2) as i64, q),
                            limit(m, false, mark[i] + 1 + (h % 2) as i64, q),
                        ]
                    })
                    .collect();
                actions.push(sign(maker, NativeAction::PlaceOrderBatch(quotes)));
                if (2..=40).contains(&h) && h % 4 == 3 {
                    actions.push(sign(
                        P2_V4,
                        NativeAction::PlaceOrder(limit(2, true, mark[1] - 30, 1)),
                    ));
                }
                for _ in 0..2 + rng.below(4) {
                    let t = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                    let mi = rng.below(3) as usize;
                    let (m, p) = (C5_MARKETS[mi], mark[mi]);
                    let qty = 1 + rng.below(4) as i64;
                    let is_buy = rng.below(2) == 0;
                    let mut action = match rng.below(14) {
                        0..=2 => {
                            let off = 1 + rng.below(3) as i64;
                            NativeAction::PlaceOrder(limit(
                                m,
                                is_buy,
                                if is_buy { p - off } else { p + off },
                                qty,
                            ))
                        }
                        3..=5 => NativeAction::PlaceOrder(limit(
                            m,
                            is_buy,
                            if is_buy { p + 2 } else { p - 2 },
                            qty + 4,
                        )),
                        6 => {
                            fed.stops += 1;
                            let (trigger, lim) = if is_buy {
                                (p + 2, p + 1)
                            } else {
                                (p - 2, p - 1)
                            };
                            NativeAction::PlaceOrder(order(
                                m,
                                is_buy,
                                lim,
                                qty,
                                torus_types::OrderType::StopLimit {
                                    trigger: px(trigger),
                                    limit: px(lim),
                                },
                            ))
                        }
                        7 => {
                            fed.stops += 1;
                            let trigger = if is_buy { p + 3 } else { p - 3 };
                            let cap = if is_buy { trigger + 10 } else { trigger - 10 };
                            NativeAction::PlaceOrder(order(
                                m,
                                is_buy,
                                cap,
                                qty,
                                torus_types::OrderType::StopMarket {
                                    trigger: px(trigger),
                                },
                            ))
                        }
                        8 | 9 => NativeAction::CancelAllOrders {
                            market_id: (rng.below(2) == 0).then_some(m),
                        },
                        10 => {
                            fed.refunds += 1;
                            NativeAction::TransferToPerp {
                                amount: units(2_000),
                            }
                        }
                        11 if rng.below(3) == 0 => {
                            NativeAction::TransferToSpot { amount: units(50) }
                        }
                        _ => {
                            let mj = (mi + 1) % 3;
                            NativeAction::PlaceOrderBatch(vec![
                                limit(m, true, p - 1 - rng.below(3) as i64, qty),
                                limit(
                                    C5_MARKETS[mj],
                                    false,
                                    mark[mj] + 1 + rng.below(3) as i64,
                                    qty,
                                ),
                            ])
                        }
                    };
                    let legs = match &mut action {
                        NativeAction::PlaceOrder(p) => std::slice::from_mut(p),
                        NativeAction::PlaceOrderBatch(ps) => ps.as_mut_slice(),
                        _ => &mut [],
                    };
                    for p in legs {
                        if rng.below(3) == 0 {
                            p.reduce_only = true;
                            fed.reduce_only += 1;
                        }
                    }
                    actions.push(sign(t, action));
                }
            }
            fed.fatal += u64::from(fatal);
            // `make_block(h)` links to `make_block(h - 1)` recursively (depth
            // h, quadratic over the stream): height 1's block re-stamped to h,
            // its parent hash set by `link_blocks` below.
            let mut b = make_block(1, actions);
            b.header.height = h;
            b.header.timestamp = 1000 + h;
            b.header.evm_tx_count = evm_txs.len() as u32;
            b.evm_transactions = evm_txs;
            blocks.push(b);
            extra.push((slashes, fatal));
        }
        link_blocks(&mut blocks);
        let out = blocks
            .into_iter()
            .zip(extra)
            .map(|(block, (slashes, fatal))| P5Block {
                block,
                slashes,
                fatal,
            })
            .collect();
        (out, fed)
    }

    /// One node of the differential: its DB, its context (recreated after
    /// the fatal block) and what it saw.
    struct P5Node {
        cfg: P5Config,
        path: P5Path,
        config: ChainConfig,
        db: StateDb,
        ctx: Option<ExecutionContext>,
        metrics: Arc<torus_telemetry::Metrics>,
        probe: Option<BlockProbe>,
        /// Restarts after a fatal block; the most heights executed above the
        /// durable marker after any block.
        restarts: u64,
        max_lag: u64,
    }

    impl P5Node {
        fn new(cfg: P5Config, path: P5Path, probe: Option<BlockProbe>) -> Self {
            let (config, db) = p5_fixture();
            torus_state::running_hash::capture_begin(&db);
            let metrics = Arc::new(torus_telemetry::Metrics::new());
            let mut node = Self {
                cfg,
                path,
                config,
                db,
                ctx: None,
                metrics,
                probe,
                restarts: 0,
                max_lag: 0,
            };
            node.ctx = Some(node.new_ctx(true));
            node
        }

        fn new_ctx(&self, attach: bool) -> ExecutionContext {
            let mut ctx = make_exec_ctx(&self.config, &self.db);
            ctx.test_book_mode = Some(self.cfg.mode);
            ctx.metrics = Some(self.metrics.clone());
            ctx.checkpoint = match self.cfg.ckpt {
                P5Ckpt::PerBlock => None,
                P5Ckpt::Every5 => Some(ckpt_every(5)),
                P5Ckpt::Never => Some(ckpt_never()),
            };
            ctx.test_block_probe = self.probe.clone();
            p5_configure(&mut ctx, self.path);
            if self.cfg.pipelined && attach {
                ctx.attach_flush_worker(None);
            }
            ctx
        }

        /// Execute `b`; W drained after it. A fatal block fail-stops, nothing
        /// of it is durable, and a new context replays the committed blocks
        /// above the durable marker (the fatal one without its fault).
        fn execute(&mut self, b: &P5Block) {
            let h = b.block.header.height;
            let what = format!("{:?} {:?}", self.path, self.cfg);
            let durable = persist_committed_block_durably(&self.db, &b.block);
            let ctx = self.ctx.as_mut().expect("a context");
            if b.fatal {
                ctx.test_replay_fault = Some(ReplayFault::NoncePut);
            }
            ctx.execute_committed_block_with(&b.block, b.slashes.clone(), durable);
            if b.fatal {
                let failed = self.ctx.take().expect("a context");
                failed.pipeline_barrier();
                assert!(
                    failed.exec_failed.load(Ordering::SeqCst),
                    "{what}: the fatal block {h} fail-stops"
                );
                drop(failed);
                assert!(
                    read_native_applied_height(&self.db).unwrap_or(0) < h,
                    "{what}: nothing of {h} durable"
                );
                let mut replay = self.new_ctx(false);
                let (_last, parked) = TorusApp::replay_committed(&self.db, &replay);
                assert_eq!(parked, None, "{what}");
                assert!(
                    !replay.exec_failed.load(Ordering::SeqCst),
                    "{what}: replay after {h}"
                );
                assert_eq!(
                    read_native_applied_height(&self.db),
                    Some(h),
                    "{what}: replayed through {h}"
                );
                if self.cfg.pipelined {
                    replay.attach_flush_worker(None);
                }
                self.ctx = Some(replay);
                self.restarts += 1;
                return;
            }
            assert!(
                !ctx.exec_failed.load(Ordering::SeqCst),
                "{what}: fail-stop at {h}"
            );
            if let Some(w) = ctx.flush_worker.as_ref() {
                assert!(w.wait_idle(), "{what}: W failed at {h}");
            }
            self.max_lag = self
                .max_lag
                .max(h - read_native_applied_height(&self.db).unwrap_or(0));
        }
    }

    /// The first difference the harness found: at which block, and what.
    #[derive(Debug)]
    struct P5Divergence {
        height: u64,
        what: String,
    }

    /// What the harness compared (non-vacuity of the check side).
    #[derive(Debug, Default)]
    struct P5Compared {
        heights_hashed: u64,
        status_rows: u64,
        dumps: u64,
        durable_seen: u64,
        dumped_at: u64,
    }

    /// One run's outcome: what was compared and what the stream did.
    #[derive(Debug)]
    struct P5Summary {
        compared: P5Compared,
        restarts: u64,
        max_lag: u64,
        fills: usize,
        liquidations: u64,
        bbo_rows: usize,
    }

    /// After block `h` on both nodes (both idle): the write sets of the
    /// heights hashed since the last call (`h_n`, entry by entry), the
    /// durable markers, the action status row of every height that became
    /// durable, and the full CF dump once `dump_every` more heights are
    /// durable. The first difference names its height and where it is.
    fn p5_compare(
        a: &P5Node,
        b: &P5Node,
        h: u64,
        dump_every: u64,
        c: &mut P5Compared,
    ) -> Result<(), P5Divergence> {
        use alloy_primitives::hex;
        use torus_state::running_hash::{capture_begin, capture_take, HASHED_CFS};
        let div = |height: u64, what: String| Err(P5Divergence { height, what });
        let take = |db: &StateDb| {
            let w = capture_take(db);
            capture_begin(db);
            w
        };
        let (wa, wb) = (take(&a.db), take(&b.db));
        let heights = |w: &CapturedWrites| w.iter().map(|(x, _)| *x).collect::<Vec<_>>();
        if heights(&wa) != heights(&wb) {
            return div(
                h,
                format!(
                    "heights hashed after block {h}: {:?} vs {:?}",
                    heights(&wa),
                    heights(&wb)
                ),
            );
        }
        for ((hh, x), (_, y)) in wa.iter().zip(&wb) {
            if x != y {
                let i = x
                    .iter()
                    .zip(y)
                    .position(|(e, f)| e != f)
                    .unwrap_or(x.len().min(y.len()));
                let entry = x.get(i).or(y.get(i)).expect("a differing entry");
                let cf = HASHED_CFS
                    .iter()
                    .find(|(id, _)| *id == entry.0)
                    .map_or("?", |(_, name)| *name);
                return div(
                    *hh,
                    format!(
                        "h_n write set of height {hh} differs at entry {i} ({} vs {} entries): {cf} key {}",
                        x.len(),
                        y.len(),
                        hex::encode(&entry.1)
                    ),
                );
            }
        }
        c.heights_hashed += wa.len() as u64;
        let durable = |n: &P5Node| read_native_applied_height(&n.db).unwrap_or(0);
        let (da, db_) = (durable(a), durable(b));
        if da != db_ {
            return div(h, format!("durable marker after block {h}: {da} vs {db_}"));
        }
        for x in c.durable_seen + 1..=da {
            let row = |n: &P5Node| {
                n.db.get_cf_raw(torus_state::cf::CF_BLOCK_ACTION_STATUS, &x.to_be_bytes())
                    .unwrap()
            };
            let (ra, rb) = (row(a), row(b));
            if ra != rb {
                let len = |r: &Option<Vec<u8>>| r.as_ref().map(Vec::len);
                return div(
                    x,
                    format!(
                        "action status of height {x}: {:?} vs {:?} bytes",
                        len(&ra),
                        len(&rb)
                    ),
                );
            }
            c.status_rows += u64::from(ra.is_some());
        }
        c.durable_seen = c.durable_seen.max(da);
        if da > c.dumped_at && da - c.dumped_at >= dump_every {
            for ((cf, x), (_, y)) in dump_all_cfs(&a.db).iter().zip(&dump_all_cfs(&b.db)) {
                if x != y {
                    let i = x
                        .iter()
                        .zip(y)
                        .position(|(e, f)| e != f)
                        .unwrap_or(x.len().min(y.len()));
                    let key = x
                        .get(i)
                        .or(y.get(i))
                        .map_or(String::new(), |r| hex::encode(&r.0));
                    return div(
                        da,
                        format!("CF dump at durable height {da}: {cf} differs at row {i} ({} vs {} rows): key {key}", x.len(), y.len()),
                    );
                }
            }
            c.dumped_at = da;
            c.dumps += 1;
        }
        Ok(())
    }

    /// The differential: `blocks` through a reference node and a typed node
    /// (`probe` on the typed node's contexts, the planted divergence) in
    /// lockstep, compared after every block and at the end; the first
    /// difference is returned.
    fn p5_differential(
        blocks: &[P5Block],
        cfg: P5Config,
        probe: Option<BlockProbe>,
        dump_every: u64,
    ) -> Result<P5Summary, P5Divergence> {
        let mut a = P5Node::new(cfg, P5Path::Reference, None);
        let mut b = P5Node::new(cfg, P5Path::Typed, probe);
        let mut compared = P5Compared::default();
        for blk in blocks {
            a.execute(blk);
            b.execute(blk);
            p5_compare(&a, &b, blk.block.header.height, dump_every, &mut compared)?;
        }
        let last = blocks.last().map_or(0, |b| b.block.header.height);
        drop(a.ctx.take());
        drop(b.ctx.take());
        p5_compare(&a, &b, last, 1, &mut compared)?;
        let (ha, hb) = (
            torus_state::running_hash::read_running_hash(&a.db),
            torus_state::running_hash::read_running_hash(&b.db),
        );
        if ha != hb {
            return Err(P5Divergence {
                height: last,
                what: format!("running hash {ha:?} vs {hb:?}"),
            });
        }
        let rows = |cf| StateBackend::iterate_cf(&a.db, cf, None).unwrap().len();
        Ok(P5Summary {
            compared,
            restarts: a.restarts,
            max_lag: a.max_lag,
            fills: rows(torus_state::cf::CF_NATIVE_TRADES),
            liquidations: a.metrics.liquidations_triggered.get(),
            bbo_rows: rows(torus_state::cf::CF_NATIVE_BBO),
        })
    }

    /// The matrix: the `n`-block stream through `configs` (`threads` at a
    /// time, each configuration on its own two DBs); no divergence, and both
    /// sides non-vacuous.
    fn p5_differential_matrix(n: u64, dump_every: u64, configs: &[P5Config], threads: usize) {
        let started = std::time::Instant::now();
        let (blocks, fed) = p5_blocks(n, 0x5005_0001);
        assert_eq!(blocks.len() as u64, n);
        println!("P5 differential: {n} blocks, fed {fed:?}");
        assert!(
            fed.evm_blocks >= 3 && fed.evm_deposits >= 2 && fed.evm_creates >= 1,
            "{fed:?}"
        );
        assert!(
            fed.slashes >= 3 && fed.epoch_boundaries >= 5 && fed.shocks >= 2 && fed.fatal == 1,
            "{fed:?}"
        );
        assert!(
            fed.empty >= 10 && fed.refunds >= 10 && fed.stops >= 20 && fed.reduce_only >= 50,
            "{fed:?}"
        );
        let run = |cfg: P5Config| {
            let t = std::time::Instant::now();
            let s = p5_differential(&blocks, cfg, None, dump_every)
                .unwrap_or_else(|d| panic!("{cfg:?}: diverged at {}: {}", d.height, d.what));
            println!(
                "P5 differential {cfg:?}: {s:?}; {:.1} s",
                t.elapsed().as_secs_f64()
            );
            assert!(
                s.compared.heights_hashed >= n,
                "{cfg:?}: every height hashed: {s:?}"
            );
            assert_eq!(
                s.compared.durable_seen, n,
                "{cfg:?}: every height durable at the end"
            );
            assert!(
                s.compared.status_rows >= fed.native,
                "{cfg:?}: action status rows {s:?}"
            );
            let dumps = if cfg.ckpt == P5Ckpt::PerBlock {
                n / dump_every / 2
            } else {
                2
            };
            assert!(s.compared.dumps >= dumps, "{cfg:?}: dumps {s:?}");
            assert_eq!(s.restarts, 1, "{cfg:?}: one fatal block");
            assert!(
                s.fills >= n as usize && s.liquidations >= 3 && s.bbo_rows >= 1,
                "{cfg:?}: {s:?}"
            );
            if cfg.ckpt != P5Ckpt::PerBlock {
                assert!(
                    s.max_lag >= 4,
                    "{cfg:?}: blocks above the durable marker: {s:?}"
                );
            }
        };
        for chunk in configs.chunks(threads.max(1)) {
            std::thread::scope(|scope| {
                for &cfg in chunk {
                    scope.spawn(move || run(cfg));
                }
            });
        }
        println!(
            "P5 differential: {n} blocks x {} configurations in {:.1} s",
            configs.len(),
            started.elapsed().as_secs_f64()
        );
    }

    /// `p5_configs` filtered.
    fn p5_configs_where(f: impl Fn(&P5Config) -> bool) -> Vec<P5Config> {
        p5_configs().into_iter().filter(|c| f(c)).collect()
    }

