    // ---- Item 7 option 0 task 3.8: mixed replicas ----

    /// Plan task 3.8: three replicas of one stream, one per flag setting:
    /// flag off (Every5, the validators' checkpointing), flag on with Every5,
    /// flag on at interval 0 (`run` mode; in G mode the two flag-on nodes are
    /// gated on independent schedules). They agree on every height's `h_n`,
    /// status and side rows and every state-hash attestation row (the
    /// running-hash checkpoints at h % 100), by height (their checkpoint
    /// policies differ, so never by marker), and all equal the golden.
    fn o0_mixed_replicas(run: O0Run) {
        let (blocks, _) = o0_blocks(300, O0_SEED);
        let cfgs = [
            O0Cfg::piped(P5Ckpt::Every5, run),
            O0Cfg {
                ctl_seed: 1,
                ..O0Cfg::piped(P5Ckpt::Every5, run).fast()
            },
            O0Cfg {
                ctl_seed: 2,
                ..O0Cfg::piped(P5Ckpt::PerBlock, run).fast()
            },
        ];
        let (nodes, finals) = o0_run_agreeing(&blocks, &cfgs);
        for h in [100u64, 200, 300] {
            let cps: Vec<Option<[u8; 32]>> = nodes
                .iter()
                .map(|n| torus_state::running_hash::read_checkpoint(&n.db, h))
                .collect();
            assert!(cps[0].is_some(), "{run:?}: a state-hash checkpoint at {h}");
            assert!(
                cps.iter().all(|c| *c == cps[0]),
                "{run:?}: attestation rows at {h}: {cps:?}"
            );
        }
        for (i, a) in nodes.iter().enumerate() {
            for b in &nodes[i + 1..] {
                let c = o0_compare(&a.ledger(), &b.ledger()).unwrap_or_else(|d| {
                    panic!(
                        "{:?} vs {:?} diverged at {}: {}",
                        a.cfg, b.cfg, d.height, d.what
                    )
                });
                assert!(c.hn >= 300 && c.status >= 300 && c.side >= 300, "{c:?}");
            }
        }
        o0_assert_golden(&nodes, &finals);
    }

    /// Plan task 3.8, D mode.
    #[test]
    fn o0_mixed_replicas_agree() {
        o0_mixed_replicas(O0Run::D);
    }

    /// Plan task 3.8, G mode (the two flag-on nodes on independent gate
    /// schedules).
    #[test]
    fn o0_mixed_replicas_agree_g() {
        o0_mixed_replicas(O0Run::G);
    }

    // ---- Item 7 option 0 task 3.6: poison tests (plan 5.4, design 3b / 3c) ----

    /// Where a poison case puts its rows (plan 5.4: "a key held only in the
    /// parent, only in L (main and deferred) or only in C").
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum O0Poison {
        Parent,
        LMain,
        LDeferred,
        Checkpoint,
    }

    impl O0Poison {
        fn layer(self) -> torus_state::probes::Layer {
            use torus_state::probes::Layer;
            match self {
                O0Poison::Parent => Layer::Parent,
                O0Poison::LMain => Layer::LMain,
                O0Poison::LDeferred => Layer::LDeferred,
                O0Poison::Checkpoint => Layer::Checkpoint,
            }
        }
    }

    /// Rows of a poison case: `(cf, key, Some(value))` a put, `None` a
    /// tombstone.
    type O0Rows = Vec<(&'static str, Vec<u8>, Option<Vec<u8>>)>;

    /// An overlay over `db` whose only layer, at `at`, holds `rows` (`None`:
    /// no layer; the rows then go into the overlay's own pending set when
    /// `own`, else nowhere).
    fn o0_poison_overlay(db: &StateDb, rows: &O0Rows, at: Option<O0Poison>) -> NativeStateOverlay {
        let set = NativeStateOverlay::new(db.clone());
        for (cf, k, v) in rows {
            match v {
                Some(v) => set.put_cf_raw(cf, k, v).unwrap(),
                None => set.delete_cf_raw(cf, k).unwrap(),
            }
        }
        let Some(at) = at else {
            return set;
        };
        let frozen = set.freeze(7);
        let mut layer = torus_state::CheckpointLayer::new();
        layer.merge(&frozen);
        match at {
            O0Poison::Parent => {
                NativeStateOverlay::with_split_layers(db.clone(), Some(frozen), None, None, None)
            }
            O0Poison::LMain => NativeStateOverlay::with_split_layers(
                db.clone(),
                None,
                Some(Arc::new(layer)),
                None,
                None,
            ),
            O0Poison::LDeferred => {
                let part = layer.split_deferred();
                NativeStateOverlay::with_split_layers(
                    db.clone(),
                    None,
                    Some(Arc::new(layer)),
                    Some(Arc::new(torus_state::DeferredLayer::ready(part))),
                    None,
                )
            }
            O0Poison::Checkpoint => NativeStateOverlay::with_split_layers(
                db.clone(),
                None,
                None,
                None,
                Some(Arc::new(layer)),
            ),
        }
    }

    /// One poison case: `call` reads through reader class `reader` over an
    /// overlay; `rows` are what a not-yet-durable block wrote (the DB holds
    /// the stale state: without them). Checks, with the tripwire armed:
    /// - `want` (the answer once the rows are durable: written to the DB)
    ///   differs from `stale` (the DB without them);
    /// - with the rows only in each layer of `at`, the reader answers `want`,
    ///   and the probe counts an in-flight hit of that layer for one of
    ///   `cfs`;
    /// - with `plant` (the class's planted bypass) and the tripwire off, it
    ///   answers `stale`; with the tripwire on it trips iff `trips`.
    #[allow(clippy::too_many_arguments)]
    fn o0_poison_case(
        what: &str,
        db: &StateDb,
        reader: torus_state::probes::Reader,
        cfs: &[&str],
        rows: &O0Rows,
        at: &[O0Poison],
        plant: torus_state::probes::Plant,
        trips: bool,
        call: &dyn Fn(&NativeStateOverlay) -> String,
    ) {
        use torus_state::probes::{install, Plant, Probe};
        let run = |probe: &Arc<Probe>, ov: &NativeStateOverlay, armed: bool| {
            let _p = install(probe.clone());
            let _a = armed.then(torus_state::tripwire::arm);
            call(ov)
        };
        let quiet = Probe::new();
        let stale = run(&quiet, &o0_poison_overlay(db, &Vec::new(), None), true);
        // `want`: the rows durable (written to the DB, then restored).
        let before: Vec<Option<Vec<u8>>> = rows
            .iter()
            .map(|(cf, k, _)| db.get_cf_raw(cf, k).unwrap())
            .collect();
        let set = |vals: &mut dyn Iterator<Item = (&'static str, &Vec<u8>, Option<&Vec<u8>>)>| {
            for (cf, k, v) in vals {
                match v {
                    Some(v) => db.put_cf_raw(cf, k, v).unwrap(),
                    None => db.delete_cf_raw(cf, k).unwrap(),
                }
            }
        };
        set(&mut rows.iter().map(|(cf, k, v)| (*cf, k, v.as_ref())));
        let want = run(&quiet, &o0_poison_overlay(db, &Vec::new(), None), true);
        set(&mut rows
            .iter()
            .zip(&before)
            .map(|((cf, k, _), b)| (*cf, k, b.as_ref())));
        assert_ne!(want, stale, "{what}: the case is not vacuous");
        for &l in at {
            let probe = Probe::new();
            let got = run(&probe, &o0_poison_overlay(db, rows, Some(l)), true);
            assert_eq!(got, want, "{what}: rows only in {l:?}");
            let hit =
                probe.total(|r, layer, cf| r == reader && layer == l.layer() && cfs.contains(&cf));
            assert!(
                hit.inflight >= 1,
                "{what}: {reader:?} answered in flight by {l:?}: {hit:?}\n{}",
                probe.report()
            );
        }
        let planted = Probe::new();
        planted.plant(plant);
        planted.plant(Plant::NoTripwire);
        for &l in at {
            let got = run(&planted, &o0_poison_overlay(db, rows, Some(l)), true);
            assert_eq!(
                got, stale,
                "{what}: the planted {plant:?} answers stale ({l:?})"
            );
        }
        let planted = Probe::new();
        planted.plant(plant);
        let ov = o0_poison_overlay(db, rows, Some(at[0]));
        let tripped = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            run(&planted, &ov, true);
        }));
        match tripped {
            Err(e) => {
                let msg = e
                    .downcast_ref::<String>()
                    .cloned()
                    .or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string()))
                    .unwrap_or_default();
                assert!(
                    trips && msg.contains("raw-DB tripwire"),
                    "{what}: {plant:?} panicked: {msg}"
                );
            }
            Ok(()) => assert!(
                !trips,
                "{what}: the armed tripwire missed the planted {plant:?}"
            ),
        }
    }

    /// A precompile call through the block's journal (`EvmBlockState`, as
    /// the fast path builds it), labelled `Journal`: its output, and the
    /// queue / fee-config rows the journal then holds (a writer's effect).
    fn o0_poison_precompile(ov: &NativeStateOverlay, id: u16, input: &[u8], block: u64) -> String {
        use torus_state::cf::{CF_CORE_WRITER_QUEUE, CF_FEE_CONFIG};
        let state = torus_state::EvmBlockState::new(ov);
        let out = {
            let _s = torus_state::probes::scope(torus_state::probes::Reader::Journal);
            let mut meter = torus_core::precompiles::ReadMeter::unlimited();
            torus_core::precompiles::execute_precompile_metered(
                &torus_core::precompiles::precompile_address(id),
                input,
                &oracle_addr(O0_USERS[0]),
                U256::ZERO,
                &state.journal,
                block,
                1_000,
                false,
                &mut meter,
            )
        };
        let _s = torus_state::probes::scope(torus_state::probes::Reader::Test);
        let q = StateBackend::iterate_cf(&state.journal, CF_CORE_WRITER_QUEUE, None).unwrap();
        let f = StateBackend::iterate_cf(&state.journal, CF_FEE_CONFIG, None).unwrap();
        let keys: Vec<String> = q
            .iter()
            .map(|(k, _)| alloy_primitives::hex::encode(k))
            .collect();
        format!("{out:?} queue {keys:?} fee {f:?}")
    }

    /// Plan 5.4 (design tests 3b, 3c) and 5.2 C3-C6: every reader class of
    /// the fast-path EVM section, each CF it reads, with the rows only in the
    /// parent, L main, L deferred (positions, balances) or C over a stale
    /// DB: the reader answers from the layer (an in-flight hit of that
    /// layer), its planted raw-DB bypass answers stale (and trips the armed
    /// tripwire, but the layer-less journal, which reads through an
    /// overlay). The grid the 300-block stream cannot reach in full (C3
    /// code / storage at the parent and C, C4 markets / staking / queue,
    /// C5 at the parent, C6 false over a tombstone).
    #[test]
    fn o0_poison_readers_answer_from_every_layer() {
        use revm::DatabaseRef;
        use torus_core::precompiles::{
            ADDR_BALANCE_READER, ADDR_BBO_READER, ADDR_CORE_WRITER, ADDR_ORACLE_READER,
            ADDR_ORDER_BOOK_READER, ADDR_STAKING_READER,
        };
        use torus_state::cf::*;
        use torus_state::probes::{Plant, Reader};
        use O0Poison::*;
        let (config, db) = o0_fixture();
        let ctx = make_exec_ctx(&config, &db);
        // A row of the fixture, removed from the DB (the stale state).
        let take = |cf: &'static str, key: Vec<u8>| -> O0Rows {
            let v = db
                .get_cf_raw(cf, &key)
                .unwrap()
                .unwrap_or_else(|| panic!("{cf} row in the fixture"));
            db.delete_cf_raw(cf, &key).unwrap();
            vec![(cf, key, Some(v))]
        };
        let all = [Parent, LMain, Checkpoint];
        let deferred = [Parent, LDeferred, Checkpoint];
        // C3: the revm adapter.
        let user = oracle_addr(O0_USERS[1]);
        let rows = take(CF_ACCOUNTS, user.to_vec());
        o0_poison_case(
            "revm account",
            &db,
            Reader::Revm,
            &[CF_ACCOUNTS],
            &rows,
            &all,
            Plant::BypassRevm,
            true,
            &|ov| {
                format!(
                    "{:?}",
                    torus_state::EvmBlockState::new(ov)
                        .db
                        .basic_ref(user)
                        .unwrap()
                )
            },
        );
        let slots = o0_addr(O0_SLOTS);
        let rows = take(
            CF_STORAGE,
            torus_state::db::storage_key(&slots, &U256::from(2)).to_vec(),
        );
        o0_poison_case(
            "revm storage",
            &db,
            Reader::Revm,
            &[CF_STORAGE],
            &rows,
            &all,
            Plant::BypassRevm,
            true,
            &|ov| {
                format!(
                    "{:?}",
                    torus_state::EvmBlockState::new(ov)
                        .db
                        .storage_ref(slots, U256::from(2))
                        .unwrap()
                )
            },
        );
        let code = alloy_primitives::keccak256(&o0_contracts()[0].1);
        let rows = take(CF_CODE, code.to_vec());
        o0_poison_case(
            "revm code",
            &db,
            Reader::Revm,
            &[CF_CODE],
            &rows,
            &all,
            Plant::BypassRevm,
            true,
            &|ov| {
                format!(
                    "{:?}",
                    torus_state::EvmBlockState::new(ov)
                        .db
                        .code_by_hash_ref(code)
                        .unwrap()
                        .original_bytes()
                )
            },
        );
        // C4: the journal (reader and writer precompiles).
        let v4 = oracle_addr(P2_V4);
        let rows = take(
            CF_NATIVE_POSITIONS,
            torus_core::position::position_key(&v4, 1).to_vec(),
        );
        let input = o0_call(
            "getPosition(address,bytes32)",
            &[o0_word_addr(v4), o0_word(1)],
        );
        o0_poison_case(
            "journal positions",
            &db,
            Reader::Journal,
            &[CF_NATIVE_POSITIONS],
            &rows,
            &deferred,
            Plant::BypassJournal,
            false,
            &|ov| o0_poison_precompile(ov, ADDR_ORDER_BOOK_READER, &input, 50),
        );
        let trader = oracle_addr(C5_TRADERS[1]);
        let input = o0_call("getBalances(address)", &[o0_word_addr(trader)]);
        let rows = take(CF_NATIVE_BALANCES, trader.to_vec());
        o0_poison_case(
            "journal balances",
            &db,
            Reader::Journal,
            &[CF_NATIVE_BALANCES],
            &rows,
            &deferred,
            Plant::BypassJournal,
            false,
            &|ov| o0_poison_precompile(ov, ADDR_BALANCE_READER, &input, 50),
        );
        let rows = take(CF_ACCOUNTS, trader.to_vec());
        o0_poison_case(
            "journal accounts",
            &db,
            Reader::Journal,
            &[CF_ACCOUNTS],
            &rows,
            &all,
            Plant::BypassJournal,
            false,
            &|ov| o0_poison_precompile(ov, ADDR_BALANCE_READER, &input, 50),
        );
        // An aggregate price of market 9 (none in the fixture): price 16 BE,
        // block 8 BE, 4 bytes, timestamp 8 BE (`decode_agg`).
        let mut agg = b"agg".to_vec();
        agg.extend_from_slice(&9u64.to_be_bytes());
        let mut price = (7 * FixedPoint::ONE.raw()).to_be_bytes().to_vec();
        price.extend_from_slice(&40u64.to_be_bytes());
        price.extend_from_slice(&[0u8; 4]);
        price.extend_from_slice(&1_000u64.to_be_bytes());
        let rows: O0Rows = vec![(CF_NATIVE_ORACLE, agg, Some(price))];
        let input = o0_call("getPrice(bytes32)", &[o0_word(9)]);
        o0_poison_case(
            "journal oracle",
            &db,
            Reader::Journal,
            &[CF_NATIVE_ORACLE],
            &rows,
            &all,
            Plant::BypassJournal,
            false,
            &|ov| o0_poison_precompile(ov, ADDR_ORACLE_READER, &input, 50),
        );
        let rows = take(CF_NATIVE_MARKETS, 2u64.to_be_bytes().to_vec());
        let input = o0_call("getMarkets()", &[]);
        o0_poison_case(
            "journal markets",
            &db,
            Reader::Journal,
            &[CF_NATIVE_MARKETS],
            &rows,
            &all,
            Plant::BypassJournal,
            false,
            &|ov| o0_poison_precompile(ov, ADDR_BALANCE_READER, &input, 50),
        );
        let staker = oracle_addr(O0_USERS[2]);
        let mut perm = staker.to_vec();
        perm.extend_from_slice(&U256::from(77u64).to_be_bytes::<32>());
        perm.extend_from_slice(&[0u8; 8]);
        let rows: O0Rows = vec![(CF_STAKING_PERMANENT, staker.to_vec(), Some(perm))];
        let input = o0_call("getStakingInfo(address)", &[o0_word_addr(staker)]);
        o0_poison_case(
            "journal staking",
            &db,
            Reader::Journal,
            &[CF_STAKING_PERMANENT],
            &rows,
            &all,
            Plant::BypassJournal,
            false,
            &|ov| o0_poison_precompile(ov, ADDR_STAKING_READER, &input, 50),
        );
        let mut bbo = 5i128.to_be_bytes().to_vec();
        bbo.extend_from_slice(&9i128.to_be_bytes());
        let rows: O0Rows = vec![(CF_NATIVE_BBO, 3u64.to_be_bytes().to_vec(), Some(bbo))];
        let input = o0_call("bbo(bytes32)", &[o0_word(3)]);
        o0_poison_case(
            "journal bbo",
            &db,
            Reader::Journal,
            &[CF_NATIVE_BBO],
            &rows,
            &all,
            Plant::BypassJournal,
            false,
            &|ov| o0_poison_precompile(ov, ADDR_BBO_READER, &input, 50),
        );
        // The enqueue (CoreWriter placeOrder at block 95, K = 10): a block
        // in flight set the last order target to 110 and queued (110, 0), so
        // the order lands at (110, 1); stale: (105, 0).
        let place = o0_place_calldata(1, 50);
        let mut q110 = 110u64.to_be_bytes().to_vec();
        q110.extend_from_slice(&0u64.to_be_bytes());
        let cursor: O0Rows = vec![
            (
                CF_FEE_CONFIG,
                torus_core::precompiles::CORE_WRITER_LAST_ORDER_TARGET_KEY.to_vec(),
                Some(110u64.to_be_bytes().to_vec()),
            ),
            (CF_CORE_WRITER_QUEUE, q110.clone(), Some(vec![1, 2, 3])),
        ];
        for plant in [Plant::BypassEnqueue, Plant::BypassJournal] {
            o0_poison_case(
                "enqueue cursor + queue",
                &db,
                Reader::Journal,
                &[CF_FEE_CONFIG, CF_CORE_WRITER_QUEUE],
                &cursor,
                &all,
                plant,
                plant == Plant::BypassEnqueue,
                &|ov| o0_poison_precompile(ov, ADDR_CORE_WRITER, &place, 95),
            );
        }
        // A full target in flight (200 rows at 105): get_cf_len of its last
        // slot answers from the layer, the order moves to 106.
        let full: O0Rows = (0..torus_types::CORE_WRITER_DRAIN_CAP)
            .map(|seq| {
                let mut k = 105u64.to_be_bytes().to_vec();
                k.extend_from_slice(&seq.to_be_bytes());
                (CF_CORE_WRITER_QUEUE, k, Some(vec![seq as u8]))
            })
            .collect();
        o0_poison_case(
            "enqueue full target",
            &db,
            Reader::Journal,
            &[CF_CORE_WRITER_QUEUE],
            &full,
            &all,
            Plant::BypassEnqueue,
            true,
            &|ov| o0_poison_precompile(ov, ADDR_CORE_WRITER, &place, 95),
        );
        // C5: the lane read.
        let lane: O0Rows = vec![(
            CF_NATIVE_ORACLE,
            evm_lane_key(&user).to_vec(),
            Some(vec![1]),
        )];
        o0_poison_case(
            "lane",
            &db,
            Reader::Lane,
            &[CF_NATIVE_ORACLE],
            &lane,
            &all,
            Plant::BypassLane,
            true,
            &|ov| {
                format!(
                    "{:?}",
                    torus_state::EvmBlockState::new(ov)
                        .lane_read(CF_NATIVE_ORACLE, &evm_lane_key(&user))
                        .unwrap()
                )
            },
        );
        // C6: the CoreWriter due-check of height 120: true from a row only
        // in flight; false over an in-flight tombstone of a row still in the
        // DB.
        let due = |ov: &NativeStateOverlay| {
            let _s = torus_state::probes::scope(Reader::DueCheck);
            format!("{:?}", ctx.core_writer_due(ov, 120).unwrap())
        };
        let mut q120 = 120u64.to_be_bytes().to_vec();
        q120.extend_from_slice(&0u64.to_be_bytes());
        let row: O0Rows = vec![(CF_CORE_WRITER_QUEUE, q120.clone(), Some(vec![9]))];
        o0_poison_case(
            "due-check row",
            &db,
            Reader::DueCheck,
            &[CF_CORE_WRITER_QUEUE],
            &row,
            &all,
            Plant::BypassDueCheck,
            true,
            &due,
        );
        db.put_cf_raw(CF_CORE_WRITER_QUEUE, &q120, &[9]).unwrap();
        let tomb: O0Rows = vec![(CF_CORE_WRITER_QUEUE, q120, None)];
        o0_poison_case(
            "due-check tombstone",
            &db,
            Reader::DueCheck,
            &[CF_CORE_WRITER_QUEUE],
            &tomb,
            &all,
            Plant::BypassDueCheck,
            true,
            &due,
        );
    }

    // ---- Item 7 option 0 task 3.6: planted bypasses on the stream (plan 5.4) ----

    /// Run `blocks` on S and on each flag-on config of `cfgs` with `plants`
    /// (the tripwire kept from arming: the bypass must show as a
    /// divergence); each pipelined node's verdict against S (`Ok`: equal and
    /// no fail-stop).
    fn o0_planted_fast(
        blocks: &[O0Block],
        cfgs: &[O0Cfg],
        plants: &[torus_state::probes::Plant],
        fixture: fn() -> (ChainConfig, StateDb),
    ) -> Vec<(O0Cfg, Result<(), String>)> {
        let mut all = vec![O0Cfg::serial()];
        all.extend(cfgs.iter().copied());
        let mut list = Vec::new();
        for i in 1..all.len() {
            list.push((i, torus_state::probes::Plant::NoTripwire));
            for p in plants {
                list.push((i, *p));
            }
        }
        let nodes = o0_run_fixture(blocks, &all, &list, fixture);
        nodes[1..]
            .iter()
            .map(|node| {
                let v = match node.failed_at {
                    Some(h) => Err(format!("fail-stop at {h}")),
                    None => o0_compare(&nodes[0].ledger(), &node.ledger())
                        .map(|_| ())
                        .map_err(|d| format!("diverged at {}: {}", d.height, d.what)),
                };
                (node.cfg, v)
            })
            .collect()
    }

    /// The planted `plant` with the tripwire armed (a D node, Every5): the
    /// first fast-path EVM block trips it.
    fn o0_planted_trips(blocks: &[O0Block], plant: torus_state::probes::Plant) -> bool {
        let cfg = [O0Cfg::piped(P5Ckpt::Every5, O0Run::D).fast()];
        let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            o0_run(blocks, &cfg, &[(0, plant)]);
        }));
        match r {
            Ok(()) => false,
            Err(e) => {
                let msg = e
                    .downcast_ref::<String>()
                    .cloned()
                    .or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string()))
                    .unwrap_or_default();
                assert!(
                    msg.contains("raw-DB tripwire"),
                    "{plant:?}: another panic: {msg}"
                );
                true
            }
        }
    }

    /// The flag-on configs a planted bypass runs in: Every5 and Never
    /// (where the DB lags) and interval 0, in G mode.
    fn o0_bypass_cfgs() -> [O0Cfg; 3] {
        [
            O0Cfg::piped(P5Ckpt::Every5, O0Run::G).fast(),
            O0Cfg::piped(P5Ckpt::Never, O0Run::G).fast(),
            O0Cfg::piped(P5Ckpt::PerBlock, O0Run::G).fast(),
        ]
    }

    /// Plan 5.4: the planted bypass of one reader class on the 300-block
    /// stream: with the tripwire armed it trips (`trips`); with it off the
    /// harness reports a divergence (or a fail-stop) against S in each
    /// config of `caught` (indices into `o0_bypass_cfgs`), at least one of
    /// Every5 / Never. Prints every verdict.
    fn o0_assert_bypass_caught(plant: torus_state::probes::Plant, trips: bool, caught: &[usize]) {
        let (blocks, _) = o0_blocks(300, O0_SEED);
        assert_eq!(
            o0_planted_trips(&blocks, plant),
            trips,
            "{plant:?}: the tripwire"
        );
        let verdicts = o0_planted_fast(&blocks, &o0_bypass_cfgs(), &[plant], o0_fixture);
        for (cfg, v) in &verdicts {
            println!("{plant:?} {:?} {:?}: {v:?}", cfg.ckpt, cfg.run);
        }
        assert!(caught.iter().any(|&i| i < 2), "{plant:?}: Every5 or Never");
        for &i in caught {
            assert!(
                verdicts[i].1.is_err(),
                "{plant:?}: {:?} must catch it: {verdicts:?}",
                verdicts[i].0
            );
        }
    }

    /// Plan 5.4: the revm adapter reading the raw `StateDb`.
    #[test]
    fn o0_planted_bypass_revm_is_caught() {
        o0_assert_bypass_caught(torus_state::probes::Plant::BypassRevm, true, &[0, 1, 2]);
    }

    /// Plan 5.4, the enqueue hand stream (the 300-block stream's in-flight
    /// cursor reads never change a decision: the stale and the layer value
    /// pick the same target): `[native, 210 cancels (200 fill h+1, 10 spill
    /// to h+2), one cancel (target h+2: seq 10 after the spilled rows in
    /// the parent), native, native]` repeated. A journal that misses the
    /// parent / L / C puts the cancel at seq 0, over a spilled row.
    fn o0_enqueue_blocks() -> Vec<O0Block> {
        use O0Hand::*;
        let kinds: Vec<O0Hand> = (0..30)
            .map(|i| [Native, CancelLoop, Cancel, Native, Native][i % 5])
            .collect();
        o0_hand_blocks(&kinds)
    }

    /// Plan 5.4: a journal-side bypass on the enqueue hand stream: caught in
    /// every config of `o0_bypass_cfgs` (the spilled rows sit in the parent,
    /// in flight in G mode at interval 0 and within an Every5 / Never
    /// window); unplanted, they agree with S.
    fn o0_assert_enqueue_bypass_caught(plant: torus_state::probes::Plant) {
        let blocks = o0_enqueue_blocks();
        let ok = o0_planted_fast(&blocks, &o0_bypass_cfgs(), &[], o0_fixture);
        assert!(ok.iter().all(|(_, v)| v.is_ok()), "unplanted: {ok:?}");
        let v = o0_planted_fast(&blocks, &o0_bypass_cfgs(), &[plant], o0_fixture);
        println!("{plant:?} (enqueue stream): {v:?}");
        assert!(
            v.iter().all(|(_, v)| v.is_err()),
            "{plant:?} caught in every config: {v:?}"
        );
    }

    /// Plan 5.4: the journal without layers (`NativeStateOverlay::new(db)`):
    /// it reads through an overlay, so the tripwire cannot see it (asserted)
    /// and the divergence must.
    #[test]
    fn o0_planted_bypass_journal_is_caught() {
        use torus_state::probes::Plant::BypassJournal;
        let (blocks, _) = o0_blocks(300, O0_SEED);
        assert!(
            !o0_planted_trips(&blocks, BypassJournal),
            "an overlay read: no trip"
        );
        o0_assert_enqueue_bypass_caught(BypassJournal);
    }

    /// Plan 5.4: the CoreWriter due-check on the raw `StateDb`. On the
    /// 300-block stream it trips the tripwire, but no target of an in-flight
    /// queue row is a block that runs no native phase otherwise, so the
    /// divergence runs on a hand stream (C6, "a lockbox deposit then an
    /// empty block"): `[native, deposit, empty, native, native]` repeated.
    /// With the bypass the empty block reads the DB, misses the credit its
    /// parent queued for it (in flight) and skips its native phase: the
    /// credit is stranded.
    #[test]
    fn o0_planted_bypass_due_check_is_caught() {
        use torus_state::probes::Plant::BypassDueCheck;
        use O0Hand::*;
        let (blocks, _) = o0_blocks(300, O0_SEED);
        assert!(o0_planted_trips(&blocks, BypassDueCheck), "the tripwire");
        let kinds: Vec<O0Hand> = (0..30)
            .map(|i| [Native, Deposit, Empty, Native, Native][i % 5])
            .collect();
        let blocks = o0_hand_blocks(&kinds);
        let v = o0_planted_fast(&blocks, &o0_bypass_cfgs(), &[BypassDueCheck], o0_fixture);
        println!("BypassDueCheck (deposit, empty): {v:?}");
        assert!(
            v.iter().all(|(_, v)| v.is_err()),
            "caught in every config: {v:?}"
        );
        // Not vacuous: unplanted, the same configs agree with S.
        let ok = o0_planted_fast(&blocks, &o0_bypass_cfgs(), &[], o0_fixture);
        assert!(ok.iter().all(|(_, v)| v.is_ok()), "{ok:?}");
    }

    /// Plan 5.4: the lane read on the raw `StateDb`.
    #[test]
    fn o0_planted_bypass_lane_is_caught() {
        o0_assert_bypass_caught(torus_state::probes::Plant::BypassLane, true, &[0, 1]);
    }

    /// Plan 5.4: the enqueue's cursor and probe reads on the raw `StateDb`:
    /// the tripwire trips on the 300-block stream, the divergence shows on
    /// the enqueue hand stream.
    #[test]
    fn o0_planted_bypass_enqueue_is_caught() {
        use torus_state::probes::Plant::BypassEnqueue;
        let (blocks, _) = o0_blocks(300, O0_SEED);
        assert!(o0_planted_trips(&blocks, BypassEnqueue), "the tripwire");
        o0_assert_enqueue_bypass_caught(BypassEnqueue);
    }

    /// Plan 5.4 (in-flight-only, R2): the fast-path EVM section's reads skip
    /// the parent layer (the native phase keeps it). G mode at interval 0
    /// catches it; D mode at interval 0 does not (the drain makes the DB
    /// answer what the parent would: the reason G exists).
    #[test]
    fn o0_planted_skip_parent_layer() {
        let (blocks, _) = o0_blocks(300, O0_SEED);
        let v = o0_planted_fast(
            &blocks,
            &[
                O0Cfg::piped(P5Ckpt::PerBlock, O0Run::D).fast(),
                O0Cfg::piped(P5Ckpt::PerBlock, O0Run::G).fast(),
            ],
            &[torus_state::probes::Plant::SkipParentEvm],
            o0_fixture,
        );
        println!("skip parent (EVM section): {v:?}");
        assert_eq!(v[0].1, Ok(()), "D mode at interval 0 cannot see it");
        assert!(v[1].1.is_err(), "G mode catches it: {v:?}");
    }

    /// Plan 5.4 (in-flight-only, R2): the EVM section without the
    /// checkpoint in flight C, with the resident rows R ON (the EVM section
    /// reads no R; task 0.4 caught this on the native phase only with R
    /// off): G mode with held checkpoints catches it, D mode never reads C.
    #[test]
    fn o0_planted_skip_inflight_checkpoint_evm() {
        let (blocks, _) = o0_blocks(300, O0_SEED);
        let v = o0_planted_fast(
            &blocks,
            &[
                O0Cfg::piped(P5Ckpt::Every5, O0Run::D).fast(),
                O0Cfg::piped(P5Ckpt::Every5, O0Run::G).fast(),
            ],
            &[torus_state::probes::Plant::SkipCheckpointEvm],
            o0_fixture,
        );
        println!("skip C (EVM section, R on): {v:?}");
        assert_eq!(v[0].1, Ok(()), "D mode never reads C");
        assert!(v[1].1.is_err(), "G mode catches it: {v:?}");
    }

    /// Plan 5.4 (in-flight-only, R2): the EVM section without L's deferred
    /// part. The stream's readers do not store their answers, so this runs
    /// a recorder stream: `[TransferToPerp, empty, getBalances through the
    /// recorder]` repeated, Every5: the balance written two blocks before
    /// the read sits in the deferred part (a held merge in G mode). Caught.
    #[test]
    fn o0_planted_skip_deferred_part() {
        use O0Hand::*;
        let kinds: Vec<O0Hand> = (0..30)
            .map(|i| [Native, Empty, ReadBalances][i % 3])
            .collect();
        let blocks = o0_hand_blocks(&kinds);
        let cfgs = [
            O0Cfg::piped(P5Ckpt::Every5, O0Run::D).fast(),
            O0Cfg::piped(P5Ckpt::Every5, O0Run::G).fast(),
        ];
        // Not vacuous: unplanted, the reads come from the deferred part.
        let nodes = o0_run_fixture(&blocks, &cfgs, &[], o0_fixture_recorder);
        for node in &nodes {
            let d = node.probe.total(|r, l, cf| {
                r == torus_state::probes::Reader::Journal
                    && l == torus_state::probes::Layer::LDeferred
                    && cf == torus_state::cf::CF_NATIVE_BALANCES
            });
            assert!(
                d.inflight > 0,
                "{:?}: journal reads in flight from L's deferred part: {d:?}",
                node.cfg
            );
        }
        let v = o0_planted_fast(
            &blocks,
            &cfgs,
            &[torus_state::probes::Plant::SkipDeferredEvm],
            o0_fixture_recorder,
        );
        println!("skip deferred (EVM section): {v:?}");
        assert!(v.iter().all(|(_, v)| v.is_err()), "caught: {v:?}");
    }

    // ======================================================================
    // Item 6 Phase 2 (plan 9.8): app-level differential of torus-bridge's
    // reference paths (full-scan cancel-all, per-row position flush) against
    // the production paths, through the test-only `test-reference-paths`
    // feature. P2-1 (cancel-all index) and P2-2 (batch flush) keep it green.
    // ======================================================================

    const P2_BLOCKS: u64 = 130;
    /// Seeded long 30 @100 in market 1 (collateral 300): rests bids far
    /// below the mark and a buy stop far above it in markets 2 / 3, never
    /// cancels, and is liquidated later (the walk or the market-1 shock at
    /// 60), so the liquidation step's cancel takes its orders and stops.
    const P2_V4: u8 = 95;

    /// `c5_fixture` plus V4 (above).
    fn p2_fixture() -> (ChainConfig, StateDb) {
        use torus_core::position::{MarginType, NativeBalance, PositionManager};
        let (config, db) = c5_fixture();
        let pm = PositionManager::new(db.clone());
        pm.put_native_balance(
            &oracle_addr(P2_V4),
            &NativeBalance {
                available: px(300),
                order_margin: FixedPoint::ZERO,
            },
        )
        .unwrap();
        pm.apply_fill(
            &oracle_addr(P2_V4),
            1,
            true,
            px(30),
            px(100),
            MarginType::Cross,
        )
        .unwrap();
        pm.apply_fill(
            &oracle_addr(C5_S),
            1,
            false,
            px(30),
            px(100),
            MarginType::Cross,
        )
        .unwrap();
        (config, db)
    }

    /// What the generator fed (non-vacuity of the input side).
    #[derive(Debug, Default)]
    struct P2Fed {
        cancel_all_none: u64,
        cancel_all_some: u64,
        /// A sender's second cancel-all in the same block (same run).
        repeated: u64,
        stops: u64,
        crossing: u64,
        v4_actions: u64,
        cancel_only_blocks: u64,
        /// Reduce-only places (single or in a batch), `p2_blocks(true)` only.
        reduce_only: u64,
        /// s118, `p2_blocks_with(_, true)` only: places (single, batch leg,
        /// maker quote) with a cloid, and cancels by cloid.
        cloids: u64,
        cancels_by_cloid: u64,
    }

    /// The P2 sequence: heights 1..=P2_BLOCKS (ts 1000 + h), linked. C5's
    /// mark walk (oracle rounds every 5th block plus at random, shocks at 60
    /// and 120); every non-empty block a maker requotes every market (its
    /// cancel-all, `None` or `Some(m)`, every 4th block); 2-5 trader actions:
    /// resting and crossing limits (partial fills), stop-markets and
    /// stop-limits near the last trade (some trigger into resting orders),
    /// cancel-alls `None` / `Some(m)` (a block's cancel-alls form one run;
    /// some senders send two), two-market batches; V4 rests early and is
    /// liquidated later; ~1/6 of the other blocks empty, ~1/5 of the rest
    /// cancel-alls only. `ro` (review gap 2): a third of the trader places
    /// (resting, crossing, stops, batch legs) are reduce-only; the crossing
    /// places reduce, close and flip the positions they depend on, the
    /// liquidations close some. The extra draws happen only with `ro`, so
    /// `ro: false` is the original sequence.
    fn p2_blocks(ro: bool) -> (Vec<TorusBlock>, P2Fed) {
        let (blocks, fed, _) = p2_blocks_with(ro, false);
        (blocks, fed)
    }

    /// s118 (Phase 3 step 2 follow-up): one single `PlaceOrder` with a cloid
    /// in the P2 sequence: (height, body index, trader seed, cloid).
    type P2CloidPlace = (u64, usize, u8, u128);

    /// [`p2_blocks`], and with `cloid` (s118): every single trader place
    /// (and half the batch legs) carries a cloid from a small per-trader pool
    /// (singles 1..=2, batch legs 11..=13, so a single's duplicate is always
    /// against a single), a fifth of the trader actions are followed by a
    /// cancel by cloid of a single's cloid, and every maker's first quote
    /// carries cloid 100 (the maker of even heights cancels all its orders
    /// every 4th block and one market's in between, the other never
    /// cancels). So placements hit live cloids (duplicates, across
    /// blocks and within one), and cloids freed by fills and cancels are
    /// placed again. The extra draws happen only with `cloid`. Returns the
    /// single places with a cloid.
    fn p2_blocks_with(ro: bool, cloid: bool) -> (Vec<TorusBlock>, P2Fed, Vec<P2CloidPlace>) {
        p2_blocks_full(ro, cloid, false)
    }

    /// [`p2_blocks_with`], and with `deep` (b0): the deep-level traffic of
    /// [`p2_deep_actions`] in front of each block's other actions (no extra
    /// draws: the rest of the sequence is the original one). Needs
    /// [`p2_deep_seed`] on the fixture.
    fn p2_blocks_full(
        ro: bool,
        cloid: bool,
        deep: bool,
    ) -> (Vec<TorusBlock>, P2Fed, Vec<P2CloidPlace>) {
        p2_blocks_len(P2_BLOCKS, ro, cloid, deep)
    }

    /// 8k L3.1: [`p2_blocks_full`] over heights `1..=len`: the first
    /// `P2_BLOCKS` are that sequence; past them the same generator runs on
    /// (mark walk, maker requotes, trader actions; no more shocks or V4) and
    /// the deep traffic repeats with period `P2_BLOCKS`.
    fn p2_blocks_len(
        len: u64,
        ro: bool,
        cloid: bool,
        deep: bool,
    ) -> (Vec<TorusBlock>, P2Fed, Vec<P2CloidPlace>) {
        let mut rng = C5Rng(0x9e21_0008);
        let mut fed = P2Fed::default();
        let mut cloid_places: Vec<P2CloidPlace> = Vec::new();
        let mut mark = [100i64; 3];
        let mut nonces: std::collections::HashMap<u8, u64> = Default::default();
        let cur_h = std::cell::Cell::new(0u64);
        let mut sign = |seed: u8, action: NativeAction| {
            let n = nonces.entry(seed).or_insert(0);
            *n += 1;
            let nonce = NONCE_BASE + cur_h.get() * 1_000 + *n;
            torus_types::eip712::sign_native_action(action, nonce, &oracle_key(seed))
        };
        let order =
            |m: u64, is_buy: bool, price: i64, qty: i64, order_type: torus_types::OrderType| {
                torus_types::PlaceOrderParams {
                    market_id: m,
                    is_buy,
                    price: px(price),
                    quantity: px(qty),
                    order_type,
                    time_in_force: torus_types::TimeInForce::GTC,
                    reduce_only: false,
                    client_order_id: None,
                }
            };
        let limit = |m: u64, is_buy: bool, price: i64, qty: i64| {
            order(m, is_buy, price, qty, torus_types::OrderType::Limit)
        };
        let mut blocks = Vec::new();
        for h in 1..=len {
            cur_h.set(h);
            let mut actions = Vec::new();
            if deep {
                for (seed, action) in p2_deep_actions((h - 1) % P2_BLOCKS + 1) {
                    actions.push(sign(seed, action));
                }
            }
            let shock = h == 60 || h == 120;
            let mark_round = h == 1 || h % 5 == 1 || shock || rng.below(4) == 0;
            if mark_round {
                match h {
                    1 => {}
                    60 => mark[0] = mark[0] * 85 / 100,
                    120 => mark[1] = mark[1] * 118 / 100,
                    _ => {
                        for p in &mut mark {
                            *p = (*p + rng.below(5) as i64 - 2).max(50);
                        }
                    }
                }
                for (seed, _) in ORACLE_VALIDATORS {
                    let prices = C5_MARKETS
                        .iter()
                        .zip(mark)
                        .map(|(m, p)| (*m, px(p)))
                        .collect();
                    actions.push(torus_types::eip712::sign_native_action(
                        NativeAction::SubmitOraclePrices(torus_types::OracleSubmission {
                            prices,
                            timestamp: (1_000 + h) * 1_000,
                        }),
                        NONCE_BASE + h * 1_000 + seed as u64,
                        &oracle_key(seed),
                    ));
                }
            }
            if !mark_round && rng.below(6) == 0 {
                blocks.push(make_block(h, actions));
                continue;
            }
            if rng.below(5) == 0 {
                // Cancel-only block: the books these cancel-alls touch are
                // dirty only through them (a missed cancel or dirty mark
                // shows in the CF dump).
                fed.cancel_only_blocks += 1;
                for _ in 0..1 + rng.below(3) {
                    let t = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                    let target = (rng.below(3) == 0).then(|| C5_MARKETS[rng.below(3) as usize]);
                    if target.is_some() {
                        fed.cancel_all_some += 1;
                    } else {
                        fed.cancel_all_none += 1;
                    }
                    actions.push(sign(t, NativeAction::CancelAllOrders { market_id: target }));
                }
                blocks.push(make_block(h, actions));
                continue;
            }
            let maker = C5_MAKERS[(h % 2) as usize];
            match h % 4 {
                0 => {
                    actions.push(sign(
                        maker,
                        NativeAction::CancelAllOrders { market_id: None },
                    ));
                    fed.cancel_all_none += 1;
                }
                2 => {
                    let m = C5_MARKETS[(h / 4 % 3) as usize];
                    actions.push(sign(
                        maker,
                        NativeAction::CancelAllOrders { market_id: Some(m) },
                    ));
                    fed.cancel_all_some += 1;
                }
                _ => {}
            }
            let mut quotes = Vec::new();
            for (i, m) in C5_MARKETS.into_iter().enumerate() {
                let q = 2 + rng.below(4) as i64;
                quotes.push(limit(m, true, mark[i] - 1 - rng.below(2) as i64, q));
                quotes.push(limit(m, false, mark[i] + 1 + rng.below(2) as i64, q));
            }
            if cloid {
                quotes[0].client_order_id = Some(100);
                fed.cloids += 1;
            }
            actions.push(sign(maker, NativeAction::PlaceOrderBatch(quotes)));
            if (2..=40).contains(&h) && h % 4 == 3 {
                // V4: a bid far below the mark and a buy stop far above it.
                fed.v4_actions += 2;
                actions.push(sign(
                    P2_V4,
                    NativeAction::PlaceOrder(limit(2, true, mark[1] - 30, 1)),
                ));
                let trigger = mark[2] + 40;
                actions.push(sign(
                    P2_V4,
                    NativeAction::PlaceOrder(order(
                        3,
                        true,
                        trigger + 10,
                        1,
                        torus_types::OrderType::StopMarket {
                            trigger: px(trigger),
                        },
                    )),
                ));
            }
            for _ in 0..2 + rng.below(4) {
                let t = C5_TRADERS[rng.below(C5_TRADERS.len() as u64) as usize];
                let mi = rng.below(3) as usize;
                let (m, p) = (C5_MARKETS[mi], mark[mi]);
                let qty = 1 + rng.below(4) as i64;
                let is_buy = rng.below(2) == 0;
                let mut action = match rng.below(13) {
                    0..=2 => {
                        let off = 1 + rng.below(3) as i64;
                        NativeAction::PlaceOrder(limit(
                            m,
                            is_buy,
                            if is_buy { p - off } else { p + off },
                            qty,
                        ))
                    }
                    3..=5 => {
                        // Crossing, larger than one quote: partial fills, the rest rests.
                        fed.crossing += 1;
                        NativeAction::PlaceOrder(limit(
                            m,
                            is_buy,
                            if is_buy { p + 2 } else { p - 2 },
                            qty + 4,
                        ))
                    }
                    6 => {
                        // Stop-limit near the touch: crossing trades fire it, its limit
                        // then rests or fills.
                        fed.stops += 1;
                        let (trigger, lim) = if is_buy {
                            (p + 2, p + 1)
                        } else {
                            (p - 2, p - 1)
                        };
                        NativeAction::PlaceOrder(order(
                            m,
                            is_buy,
                            lim,
                            qty,
                            torus_types::OrderType::StopLimit {
                                trigger: px(trigger),
                                limit: px(lim),
                            },
                        ))
                    }
                    7 => {
                        fed.stops += 1;
                        let trigger = if is_buy { p + 3 } else { p - 3 };
                        let cap = if is_buy { trigger + 10 } else { trigger - 10 };
                        NativeAction::PlaceOrder(order(
                            m,
                            is_buy,
                            cap,
                            qty,
                            torus_types::OrderType::StopMarket {
                                trigger: px(trigger),
                            },
                        ))
                    }
                    8 | 9 => {
                        fed.cancel_all_none += 1;
                        if rng.below(3) == 0 {
                            // The same sender again in the same run.
                            fed.repeated += 1;
                            let again = if rng.below(2) == 0 { None } else { Some(m) };
                            actions
                                .push(sign(t, NativeAction::CancelAllOrders { market_id: again }));
                        }
                        NativeAction::CancelAllOrders { market_id: None }
                    }
                    10 => {
                        fed.cancel_all_some += 1;
                        NativeAction::CancelAllOrders { market_id: Some(m) }
                    }
                    _ => {
                        let mj = (mi + 1) % 3;
                        NativeAction::PlaceOrderBatch(vec![
                            limit(m, true, p - 1 - rng.below(3) as i64, qty),
                            limit(
                                C5_MARKETS[mj],
                                false,
                                mark[mj] + 1 + rng.below(3) as i64,
                                qty,
                            ),
                        ])
                    }
                };
                if ro {
                    let legs = match &mut action {
                        NativeAction::PlaceOrder(p) => std::slice::from_mut(p),
                        NativeAction::PlaceOrderBatch(ps) => ps.as_mut_slice(),
                        _ => &mut [],
                    };
                    for p in legs {
                        if rng.below(3) == 0 {
                            p.reduce_only = true;
                            fed.reduce_only += 1;
                        }
                    }
                }
                let mut cancel_by_cloid = None;
                if cloid {
                    match &mut action {
                        NativeAction::PlaceOrder(p) => {
                            let c = 1 + rng.below(2) as u128;
                            p.client_order_id = Some(c);
                            cloid_places.push((h, actions.len(), t, c));
                            fed.cloids += 1;
                        }
                        NativeAction::PlaceOrderBatch(ps) => {
                            for p in ps {
                                if rng.below(2) == 0 {
                                    p.client_order_id = Some(11 + rng.below(3) as u128);
                                    fed.cloids += 1;
                                }
                            }
                        }
                        _ => {}
                    }
                    if rng.below(5) == 0 {
                        fed.cancels_by_cloid += 1;
                        cancel_by_cloid = Some(NativeAction::CancelByCloid {
                            market_id: m,
                            cloid: 1 + rng.below(2) as u128,
                        });
                    }
                }
                actions.push(sign(t, action));
                if let Some(cancel) = cancel_by_cloid {
                    actions.push(sign(t, cancel));
                }
            }
            blocks.push(make_block(h, actions));
        }
        link_blocks(&mut blocks);
        (blocks, fed, cloid_places)
    }

    struct P2Run {
        db: StateDb,
        dump: Vec<CfDump>,
        captured: CapturedWrites,
        hash: Option<(u64, [u8; 32])>,
        metrics: Arc<torus_telemetry::Metrics>,
        /// Classic layout only (else 0): V4's resting orders + pending stops
        /// in markets 2 / 3, the most seen after any block and after the last.
        v4_max: usize,
        v4_last: usize,
        /// P2-1: blocks after which the resident holder carried a built
        /// cancel-all index (checked to cover the books), and restarts.
        index_checked: u64,
        restarts: u64,
        /// Review gap 1: crashes replayed / stale holders put back (`P2Fault`).
        faults: u64,
        /// Review gap 2, classic layout only (else 0): the most resting
        /// reduce-only orders after any block, and how often a position
        /// under resting reduce-only orders was reduced, closed or flipped
        /// by the next block.
        ro_resting_max: usize,
        ro_moved: u64,
        /// Item 6 Phase 3: the most heights executed above the durable
        /// applied marker after any block (0 with a per-block flush).
        max_lag: u64,
        /// Item 6 Phase 3: `(S, persisted native root)` each time the
        /// durable marker moved (after a block, crash blocks excepted).
        roots: Vec<(u64, torus_types::B256)>,
        /// s118 (`P2Fault::CkptCrash`): per crash, `(durable, last)`: the
        /// heights `durable + 1 ..= last` ran before the crash, were lost
        /// and replayed from the DB.
        crash_windows: Vec<(u64, u64)>,
        /// s118: blocks after which the resident holder carried a built
        /// cloid index (checked equal to a rebuild from its books).
        cloid_checked: u64,
        /// Item 6 Phase 4 step 2: blocks after which everything was durable
        /// (the DB at the block) and the holder's R (positions and balances
        /// read through `Users`) was checked equal to the DB scan of its CFs.
        r_db_checked: u64,
        /// b0: `(S, full CF dump)` each time the durable marker moved (as
        /// `roots`), recorded only while [`P2_DUMP_DURABLE`] is set.
        dumps: Vec<(u64, Vec<CfDump>)>,
    }

    thread_local! {
        /// b0: record a full CF dump in `P2Run::dumps` at every durable height.
        static P2_DUMP_DURABLE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
        /// 8k L3.1: every `p2_run_full` context requests `TORUS_BOOK_COALESCE`
        /// (through `configure_book_coalesce`, with the DB's configured hash
        /// activation), skips the coalesced encode at closes of this kind
        /// (mutation seam), and adds a seeded random checkpoint trigger.
        static P2_BOOK_COALESCE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
        static P2_COALESCE_SKIP: std::cell::Cell<Option<CloseKind>> = const { std::cell::Cell::new(None) };
        static P2_CKPT_RANDOM: std::cell::Cell<Option<u64>> = const { std::cell::Cell::new(None) };
    }

    /// P2-1 review (GPT-6.1-sol, gap 1): what `p2_run` does to the node
    /// besides feeding the blocks.
    #[derive(Clone, Debug)]
    enum P2Fault {
        None,
        /// Drop and recreate the context after every n-th block (books, R
        /// and the cancel-all index rebuilt from the DB).
        RestartEvery(u64),
        /// Pipelined only. For each k: W's write of k + 1 fails after E ran
        /// k + 2 on top of it (fail-stop; nothing of k + 1 / k + 2 durable,
        /// E's holder already carries their books and a warm cancel-all
        /// index). A new context that KEEPS that holder replays k + 1 and
        /// k + 2 from the DB (`replay_committed`): the staleness guard must
        /// drop the books and the index (holder ahead of the DB) and rebuild.
        CrashAfter(Vec<u64>),
        /// For each (a, b): after block a the holder (warm index) is taken
        /// out, blocks a + 1 ..= b run without it (the first rebuilds from
        /// the DB), then it is put back: block b + 1 meets a holder stamped a
        /// over the DB at b (holder behind the DB), the staleness guard trips
        /// (height and marker) and rebuilds.
        StaleHolder(Vec<(u64, u64)>),
        /// Item 6 Phase 3 (pipelined, checkpoint policy set). For each
        /// `(k, mid)`: a crash at block k. `mid = false`: W parks on its next
        /// job, E runs k and k + 1 on top, then that job fails. `mid = true`:
        /// W parks on the next checkpoint (batch in flight, not written), E
        /// runs blocks from k until a checkpoint was handed off plus one
        /// more, then the checkpoint fails. The fail-stop latches, nothing
        /// more lands; a new context keeping the holder replays (S, last]
        /// from the DB (`replay_committed`) and the run continues.
        CkptCrash(Vec<(u64, bool)>),
        /// p3 merge wait (pipelined, checkpoint policy set): every layer
        /// merge's deferred half waits on the gate until E's next upkeep or
        /// drain, or a read blocking on it, releases it.
        DeferredGate(Arc<DeferredGate>),
    }

    /// V4's resting orders + pending stops in the classic book blobs of
    /// markets 2 / 3 (0 in other layouts).
    fn p2_v4_resting(db: &StateDb) -> usize {
        use borsh::BorshDeserialize;
        let v4 = oracle_addr(P2_V4);
        [2u64, 3]
            .iter()
            .filter_map(|m| {
                db.get_cf_raw(torus_state::cf::CF_NATIVE_ORDER_BOOKS, &m.to_be_bytes())
                    .unwrap()
            })
            .filter_map(|bytes| torus_core::order_book::OrderBook::try_from_slice(&bytes).ok())
            .map(|mut book| book.open_order_count(&v4) + book.take_pending_stops(&v4).len())
            .sum()
    }

    /// Review gap 2: (trader, market) -> (signed position, resting
    /// reduce-only orders) from the classic book blobs (empty in other
    /// layouts).
    fn p2_ro_resting(
        db: &StateDb,
    ) -> std::collections::BTreeMap<(Address, u64), (FixedPoint, usize)> {
        use borsh::BorshDeserialize;
        let pm = torus_core::position::PositionManager::new(db.clone());
        let mut out = std::collections::BTreeMap::new();
        for m in C5_MARKETS {
            let Some(bytes) = db
                .get_cf_raw(torus_state::cf::CF_NATIVE_ORDER_BOOKS, &m.to_be_bytes())
                .unwrap()
            else {
                continue;
            };
            let book = torus_core::order_book::OrderBook::try_from_slice(&bytes).unwrap();
            for t in book.reduce_only_traders() {
                let n = book
                    .orders_for_trader(&t)
                    .iter()
                    .filter(|o| o.reduce_only)
                    .count();
                if n > 0 {
                    out.insert((t, m), (p2_signed_position(&pm, &t, m), n));
                }
            }
        }
        out
    }

    fn p2_signed_position(
        pm: &torus_core::position::PositionManager<StateDb>,
        trader: &Address,
        market: u64,
    ) -> FixedPoint {
        match pm.get_position(trader, market).unwrap() {
            Some(p) if p.is_long => p.size,
            Some(p) => -p.size,
            None => FixedPoint::ZERO,
        }
    }

    /// P2-1: the carried cancel-all index (once built) covers the books;
    /// returns whether `ctx`'s holder carried a built index. s104: with
    /// resident books, the index size gauges show the holder's index (0 / 0
    /// while not built).
    fn p2_index_covers_books(ctx: &ExecutionContext, what: &str) -> bool {
        let index = ctx.resident_books.lock().unwrap().trader_index();
        if let (Some((carried, _)), Some(m)) = (&index, ctx.metrics.as_ref()) {
            let (entries, traders) = carried.as_ref().map_or((0, 0), |c| {
                (
                    c.values().map(Vec::len).sum::<usize>() as i64,
                    c.len() as i64,
                )
            });
            assert_eq!(
                (
                    m.exec_cancel_all_index_entries.get(),
                    m.exec_cancel_all_index_traders.get()
                ),
                (entries, traders),
                "{what}: index size gauges"
            );
        }
        let Some((Some(carried), rebuilt)) = index else {
            return false;
        };
        for (trader, markets) in &rebuilt {
            let listed = carried.get(trader).map_or(&[][..], Vec::as_slice);
            for m in markets {
                assert!(
                    listed.binary_search(m).is_ok(),
                    "{what}: {trader} has orders or stops in market {m}, the index lists {listed:?}"
                );
            }
        }
        true
    }

    /// Feed `blocks` through the committed-block path on a fresh
    /// `p2_fixture` DB. `reference`: every block on the bridge's reference
    /// paths (`test_reference_paths`). `fault`: see [`P2Fault`]. After every
    /// block with resident books, the carried cancel-all index (once built)
    /// covers the books (P2-1).
    fn p2_run(
        blocks: &[TorusBlock],
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
        reference: bool,
        fault: &P2Fault,
    ) -> P2Run {
        p2_run_with(blocks, pipelined, mode, reference, fault, None)
    }

    /// [`p2_run`] with the item 6 Phase 3 checkpoint policy `ckpt` on the
    /// pipelined contexts (`None` = per-block flush).
    fn p2_run_with(
        blocks: &[TorusBlock],
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
        reference: bool,
        fault: &P2Fault,
        ckpt: Option<crate::exec_pipeline::CheckpointPolicy>,
    ) -> P2Run {
        p2_run_seeded(blocks, pipelined, mode, reference, fault, ckpt, &|_| {}, false, None)
    }

    /// [`p2_run_with`] on a `p2_fixture` DB that `seed` wrote to first, and
    /// with `no_r`: every context without R (`test_no_resident_rows`, the
    /// reads of R's CFs go to the layers and the DB). `probe`: run on every
    /// native block's context after the liquidation step
    /// (`test_block_probe`), with the liquidation value-sum walk on.
    #[allow(clippy::too_many_arguments)]
    fn p2_run_seeded(
        blocks: &[TorusBlock],
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
        reference: bool,
        fault: &P2Fault,
        ckpt: Option<crate::exec_pipeline::CheckpointPolicy>,
        seed: &dyn Fn(&StateDb),
        no_r: bool,
        probe: Option<&BlockProbe>,
    ) -> P2Run {
        p2_run_full(
            blocks, pipelined, mode, reference, fault, ckpt, seed, no_r, probe, None,
        )
    }

    /// s58 (ported from bb62bab1 onto main's s124 `TORUS_EPOCH_FAST_PATH`):
    /// [`p2_run_with`] (production paths) with the epoch-boundary fast path
    /// set to `fast` on every context (`None`: the env's).
    fn p2_run_fast(
        blocks: &[TorusBlock],
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
        fault: &P2Fault,
        ckpt: Option<crate::exec_pipeline::CheckpointPolicy>,
        fast: Option<bool>,
    ) -> P2Run {
        p2_run_full(
            blocks,
            pipelined,
            mode,
            false,
            fault,
            ckpt,
            &|_| {},
            false,
            None,
            fast,
        )
    }

    /// [`p2_run_seeded`] with `fast` (see [`p2_run_fast`]).
    #[allow(clippy::too_many_arguments)]
    fn p2_run_full(
        blocks: &[TorusBlock],
        pipelined: bool,
        mode: Option<torus_bridge::native_executor::BookMode>,
        reference: bool,
        fault: &P2Fault,
        ckpt: Option<crate::exec_pipeline::CheckpointPolicy>,
        seed: &dyn Fn(&StateDb),
        no_r: bool,
        probe: Option<&BlockProbe>,
        fast: Option<bool>,
    ) -> P2Run {
        let (config, db) = p2_fixture();
        seed(&db);
        torus_state::running_hash::capture_begin(&db);
        let metrics = Arc::new(torus_telemetry::Metrics::new());
        let what = format!("pipelined={pipelined} {mode:?} reference={reference} {fault:?}");
        let gate = crate::exec_pipeline::WorkerGate::new();
        let new_ctx = |attach: bool| {
            let mut ctx = make_exec_ctx(&config, &db);
            // `None`: Classic without the resident holder (the per-block
            // reload, `TORUS_RESIDENT_BOOKS=0`), pinned since the env default
            // attaches the resident holder (plan 9.13).
            ctx.test_book_mode =
                Some(mode.unwrap_or(torus_bridge::native_executor::BookMode::Classic));
            ctx.test_no_resident = mode.is_none();
            ctx.test_reference_paths = reference;
            ctx.test_no_resident_rows = no_r;
            // 8k L2.2: the engine pin of `with_p2_engine_threads` (`None`:
            // production `execute_batch`, as before).
            ctx.test_engine_threads = P2_ENGINE_THREADS.with(std::cell::Cell::get);
            if let Some(p) = probe {
                ctx.test_block_probe = Some(p.clone());
                ctx.liq_value_sum = true;
            }
            ctx.metrics = Some(metrics.clone());
            ctx.checkpoint = ckpt;
            if let Some(fast) = fast {
                ctx.epoch_fast_path = fast;
            }
            ctx.configure_book_coalesce(
                P2_BOOK_COALESCE.get(),
                torus_state::running_hash::read_configured_activation(&db),
            );
            ctx.test_coalesce_skip = P2_COALESCE_SKIP.get();
            if let Some(seed) = P2_CKPT_RANDOM.get() {
                ctx.test_ckpt_due = Some(Arc::new(move |h| {
                    C5Rng(seed ^ h.wrapping_mul(0x9e37_79b9_7f4a_7c15)).below(4) == 0
                }));
            }
            if pipelined && attach {
                ctx.attach_flush_worker(Some(gate.clone()));
                if let P2Fault::DeferredGate(g) = fault {
                    ctx.ckpt.lock().unwrap().test_gate = Some(g.clone());
                }
            }
            ctx
        };
        let mut max_lag = 0;
        let mut roots: Vec<(u64, torus_types::B256)> = Vec::new();
        let mut crash_windows: Vec<(u64, u64)> = Vec::new();
        let mut cloid_checked = 0;
        let mut r_db_checked = 0;
        let mut dumps: Vec<(u64, Vec<CfDump>)> = Vec::new();
        let mut ctx = new_ctx(true);
        let (mut v4_max, mut v4_last, mut index_checked, mut restarts, mut faults) =
            (0, 0, 0, 0, 0);
        let (mut ro_resting_max, mut ro_moved) = (0, 0);
        let mut ro_last = std::collections::BTreeMap::new();
        let mut withheld: Option<torus_bridge::native_executor::ResidentBooks> = None;
        let mut skip_to = 0;
        for b in blocks {
            let h = b.header.height;
            if h <= skip_to {
                continue;
            }
            let crash = match fault {
                P2Fault::CrashAfter(ks) => ks.contains(&(h - 1)),
                _ => false,
            };
            let ckpt_crash = match fault {
                P2Fault::CkptCrash(points) => points.iter().find(|p| p.0 == h).map(|p| p.1),
                _ => None,
            };
            if let Some(mid) = ckpt_crash {
                assert!(
                    pipelined && ckpt.is_some(),
                    "{what}: a checkpoint crash needs W and a policy"
                );
                if mid {
                    gate.hold_checkpoints();
                } else {
                    gate.hold();
                }
                let blocks_t = blocks.to_vec();
                let db_t = db.clone();
                let t = std::thread::spawn(move || {
                    let mut i = (h - 1) as usize;
                    let mut handed_off = false;
                    loop {
                        let base = ctx.ckpt.lock().unwrap().base;
                        dispatch_and_execute(&ctx, &db_t, &blocks_t[i]);
                        let last = blocks_t[i].header.height;
                        i += 1;
                        let done = if mid { handed_off } else { last > h };
                        if done || ctx.exec_failed.load(Ordering::SeqCst) {
                            return (ctx, last);
                        }
                        handed_off |= ctx.ckpt.lock().unwrap().base != base;
                    }
                });
                // E's blocks never wait here (digests queue; one checkpoint
                // in flight); bounded so a regression fails, never hangs.
                let deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
                while !t.is_finished() && std::time::Instant::now() < deadline {
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
                assert!(t.is_finished(), "{what}: crash at {h}: E blocked");
                if mid {
                    while gate.parked_checkpoint().is_none() && std::time::Instant::now() < deadline
                    {
                        std::thread::sleep(std::time::Duration::from_millis(10));
                    }
                    assert!(
                        gate.parked_checkpoint().is_some(),
                        "{what}: W holds a checkpoint at {h}"
                    );
                }
                gate.fail_next();
                gate.release();
                let (failed, last) = t.join().unwrap();
                assert!(
                    !failed.flush_worker.as_ref().unwrap().wait_idle(),
                    "{what}: crash at {h}: W failed"
                );
                assert!(
                    failed.exec_failed.load(Ordering::SeqCst),
                    "{what}: crash at {h} latched"
                );
                let holder = std::mem::take(&mut *failed.resident_books.lock().unwrap());
                drop(failed);
                let durable = read_native_applied_height(&db).unwrap_or(0);
                assert!(
                    durable < last,
                    "{what}: crash at {h}: {durable} < {last} (blocks lost)"
                );
                crash_windows.push((durable, last));
                let mut replay = new_ctx(false);
                *replay.resident_books.lock().unwrap() = holder;
                let (_last, parked) = TorusApp::replay_committed(&db, &replay);
                assert_eq!(parked, None, "{what}");
                assert!(
                    !replay.exec_failed.load(Ordering::SeqCst),
                    "{what}: replay after {h}"
                );
                assert_eq!(
                    read_native_applied_height(&db),
                    Some(last),
                    "{what}: replayed to {last}"
                );
                replay.attach_flush_worker(Some(gate.clone()));
                ctx = replay;
                faults += 1;
                skip_to = last;
            } else if crash {
                // Blocks k + 1 = h and k + 2 = h + 1: W parks on k + 1, E runs
                // k + 2 on top of it, then W's write fails.
                assert!(pipelined, "{what}: a crash needs the flush worker");
                let k = h - 1;
                let next = blocks[h as usize].clone();
                assert_eq!(next.header.height, k + 2);
                gate.hold();
                dispatch_and_execute(&ctx, &db, b);
                assert!(gate.wait_received(k + 1), "{what}: W took {}", k + 1);
                let db_t = db.clone();
                let t = std::thread::spawn(move || {
                    dispatch_and_execute(&ctx, &db_t, &next);
                    ctx
                });
                std::thread::sleep(std::time::Duration::from_millis(200));
                gate.fail_next();
                gate.release();
                let failed = t.join().unwrap();
                assert!(
                    failed.exec_failed.load(Ordering::SeqCst),
                    "{what}: crash after {k} latched"
                );
                let holder = std::mem::take(&mut *failed.resident_books.lock().unwrap());
                drop(failed);
                assert!(
                    holder.height().is_some_and(|hh| hh > k),
                    "{what}: the holder is past the DB ({:?} > {k})",
                    holder.height()
                );
                assert!(
                    matches!(holder.trader_index(), Some((Some(_), _))),
                    "{what}: crash after {k}: the holder carries a warm index"
                );
                assert_eq!(read_native_applied_height(&db), Some(k), "{what}");
                let mut replay = new_ctx(false);
                *replay.resident_books.lock().unwrap() = holder;
                let (_last, parked) = TorusApp::replay_committed(&db, &replay);
                assert_eq!(parked, None, "{what}");
                assert!(
                    !replay.exec_failed.load(Ordering::SeqCst),
                    "{what}: replay after {k}"
                );
                assert_eq!(read_native_applied_height(&db), Some(k + 2), "{what}");
                if pipelined {
                    replay.attach_flush_worker(Some(gate.clone()));
                }
                ctx = replay;
                faults += 1;
                skip_to = k + 2;
            } else {
                dispatch_and_execute(&ctx, &db, b);
                assert!(
                    !ctx.exec_failed.load(Ordering::SeqCst),
                    "{what}: fail-stop at {h}"
                );
                if let Some(w) = ctx.flush_worker.as_ref() {
                    assert!(w.wait_idle(), "{what}: W failed");
                }
                let durable = read_native_applied_height(&db).unwrap_or(0);
                max_lag = max_lag.max(h - durable);
                // Phase 4 step 2: everything durable -> R (positions and
                // balances through `Users`) == the DB scan.
                let r_at_h = ctx.resident_books.lock().unwrap().rows_height() == Some(h);
                if durable == h && r_at_h {
                    assert_resident_rows_track_db(&ctx, &db, h, &what);
                    r_db_checked += 1;
                }
                if durable > 0 && roots.last().is_none_or(|(s, _)| *s != durable) {
                    roots.push((
                        durable,
                        torus_state::native_trie::persisted_native_root(&db).unwrap(),
                    ));
                    // 8k L3.1: only a height made durable by its own block
                    // (after a crash replay the marker first moves at a later
                    // block, whose dispatched header is in the DB too).
                    if P2_DUMP_DURABLE.get() && durable == h {
                        dumps.push((durable, dump_all_cfs(&db)));
                    }
                }
            }
            let h = h.max(skip_to);
            v4_last = p2_v4_resting(&db);
            v4_max = v4_max.max(v4_last);
            let ro_now = p2_ro_resting(&db);
            let pm = torus_core::position::PositionManager::new(db.clone());
            for (&(t, m), &(pos, _)) in &ro_last {
                let new = p2_signed_position(&pm, &t, m);
                let flipped = new != FixedPoint::ZERO
                    && pos != FixedPoint::ZERO
                    && (new > FixedPoint::ZERO) != (pos > FixedPoint::ZERO);
                let abs = |p: FixedPoint| if p < FixedPoint::ZERO { -p } else { p };
                if flipped || abs(new) < abs(pos) {
                    ro_moved += 1;
                }
            }
            ro_resting_max = ro_resting_max.max(ro_now.values().map(|v| v.1).sum());
            ro_last = ro_now;
            if p2_index_covers_books(&ctx, &format!("{what}: after {h}")) {
                index_checked += 1;
            }
            // s118: a carried cloid index is exactly what a load would build
            // from the books (no live cloid missing, no dead one left).
            if let Some((Some(carried), rebuilt)) = ctx.resident_books.lock().unwrap().cloid_index()
            {
                assert_eq!(carried, rebuilt, "{what}: after {h}: carried cloid index");
                cloid_checked += 1;
            }
            if let P2Fault::StaleHolder(windows) = fault {
                if windows.iter().any(|w| w.0 == h) {
                    let holder = std::mem::take(&mut *ctx.resident_books.lock().unwrap());
                    assert!(
                        matches!(holder.trader_index(), Some((Some(_), _))),
                        "{what}: after {h}: the withheld holder carries a warm index"
                    );
                    assert_eq!(holder.height(), Some(h), "{what}");
                    withheld = Some(holder);
                }
                if windows.iter().any(|w| w.1 == h) {
                    let stale = withheld.take().expect("withheld earlier");
                    *ctx.resident_books.lock().unwrap() = stale;
                    faults += 1;
                }
            }
            if matches!(fault, P2Fault::RestartEvery(n) if h % n == 0) && h < P2_BLOCKS {
                restarts += 1;
                drop(ctx);
                ctx = new_ctx(true);
            }
        }
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&db);
        let hash = torus_state::running_hash::read_running_hash(&db);
        let dump = dump_all_cfs(&db);
        P2Run {
            db,
            dump,
            captured,
            hash,
            metrics,
            v4_max,
            v4_last,
            index_checked,
            restarts,
            faults,
            ro_resting_max,
            ro_moved,
            max_lag,
            roots,
            crash_windows,
            cloid_checked,
            r_db_checked,
            dumps,
        }
    }

    /// Plan 9.8: the reference paths and the production paths give
    /// identical per-block consensus write sets (every `h_n`), running hash
    /// and full CF dump (state, books, trades, action status), serial and
    /// pipelined, in `mode` (`None`: classic without the resident holder, the
    /// `TORUS_RESIDENT_BOOKS=0` reload path). The switch reaches the context (the reference
    /// cancel-all keeps no counters) and the sequence is non-vacuous. P2-1:
    /// production uses the cancel-all index, whose carried copy covers the
    /// books after every block (resident modes, `p2_run`); a replica
    /// restarted every 7 blocks (index rebuilt from the loaded books) gives
    /// the same write sets, hash and dump. `ro` (review gap 2): on
    /// `p2_blocks(true)` (reduce-only places).
    fn p2_reference_differential(mode: Option<torus_bridge::native_executor::BookMode>, ro: bool) {
        let (blocks, fed) = p2_blocks(ro);
        assert_eq!(blocks.len() as u64, P2_BLOCKS);
        assert!(
            fed.cancel_all_none >= 40
                && fed.cancel_all_some >= 20
                && fed.repeated >= 5
                && fed.stops >= 20
                && fed.cancel_only_blocks >= 10
                && (!ro || fed.reduce_only >= 40),
            "{fed:?}"
        );
        for pipelined in [false, true] {
            let what = format!("pipelined={pipelined} {mode:?} ro={ro}");
            let reference = p2_run(&blocks, pipelined, mode, true, &P2Fault::None);
            let current = p2_run(&blocks, pipelined, mode, false, &P2Fault::None);
            assert_write_sets_equal(
                &reference.captured,
                &current.captured,
                &format!("{what}: reference vs current"),
            );
            assert_eq!(
                reference
                    .captured
                    .iter()
                    .map(|(h, _)| *h)
                    .collect::<Vec<_>>(),
                (1..=P2_BLOCKS).collect::<Vec<_>>(),
                "{what}: every height through the hashed flush"
            );
            assert!(current.hash.is_some());
            assert_eq!(reference.hash, current.hash, "{what}: running hash");
            assert_dumps_equal(
                &reference.dump,
                &current.dump,
                &format!("{what}: reference vs current"),
            );
            // P2-1 restart: the cancel-all index rebuilt from the loaded books
            // every 7 blocks gives the same blocks as the carried one.
            let restarted = p2_run(&blocks, pipelined, mode, false, &P2Fault::RestartEvery(7));
            assert_eq!(restarted.restarts, (P2_BLOCKS - 1) / 7, "{what}");
            assert_write_sets_equal(
                &reference.captured,
                &restarted.captured,
                &format!("{what}: reference vs restarted"),
            );
            assert_eq!(
                reference.hash, restarted.hash,
                "{what}: running hash, restarted"
            );
            assert_dumps_equal(
                &reference.dump,
                &restarted.dump,
                &format!("{what}: reference vs restarted"),
            );
            if mode.is_some() {
                // Resident books: the carried index was built and checked.
                assert!(
                    current.index_checked >= P2_BLOCKS - 10,
                    "{what}: {}",
                    current.index_checked
                );
                assert!(
                    restarted.index_checked >= P2_BLOCKS / 2,
                    "{what}: {}",
                    restarted.index_checked
                );
            }
            // The switch took: only the production cancel-all counts.
            assert_eq!(reference.metrics.exec_cancel_all.get(), 0, "{what}");
            assert!(
                current.metrics.exec_cancel_all.get() >= 60,
                "{what}: {}",
                current.metrics.exec_cancel_all.get()
            );

            // Non-vacuous (the runs are equal, so one side is enough).
            let fills =
                StateBackend::iterate_cf(&current.db, torus_state::cf::CF_NATIVE_TRADES, None)
                    .unwrap()
                    .len();
            let liquidations = current.metrics.liquidations_triggered.get();
            println!(
                "P2 {what}: fed {fed:?}; fills {fills}, liquidations {liquidations}, cancel-alls {} (books hit {}), \
                 V4 resting max {} last {}",
                current.metrics.exec_cancel_all.get(),
                current.metrics.exec_cancel_all_books_hit.get(),
                current.v4_max,
                current.v4_last,
            );
            assert!(fills >= 80, "{what}: fills {fills}");
            assert!(liquidations >= 3, "{what}: liquidations {liquidations}");
            assert!(
                current.metrics.exec_cancel_all_books_hit.get() >= 40,
                "{what}"
            );
            if ro && mode.is_none_or(|m| m == torus_bridge::native_executor::BookMode::Classic) {
                // Reduce-only orders rested, and positions under them moved.
                println!(
                    "P2 {what}: reduce-only resting max {}, positions moved under them {}",
                    current.ro_resting_max, current.ro_moved
                );
                assert!(
                    current.ro_resting_max >= 3,
                    "{what}: {}",
                    current.ro_resting_max
                );
                assert!(current.ro_moved >= 3, "{what}: {}", current.ro_moved);
            }
            if mode.is_none_or(|m| m == torus_bridge::native_executor::BookMode::Classic) {
                // V4 never cancels: the liquidation step's cancel took what it rested.
                assert!(current.v4_max >= 4, "{what}: V4 rested {}", current.v4_max);
                assert_eq!(
                    current.v4_last, 0,
                    "{what}: V4's orders and stops left after its liquidation"
                );
                assert_eq!(
                    torus_core::position::PositionManager::new(current.db.clone())
                        .get_position(&oracle_addr(P2_V4), 1)
                        .unwrap()
                        .map(|p| p.size),
                    None,
                    "{what}: V4 liquidated"
                );
            }
        }
    }

    // ---- Item 6 Phase 3 task 1.6: the E side of the checkpoint interval ----

    fn ckpt_every(n: u64) -> crate::exec_pipeline::CheckpointPolicy {
        crate::exec_pipeline::CheckpointPolicy {
            every_blocks: Some(n),
            ..Default::default()
        }
    }

    /// Never by time: only attest heights, barriers and shutdown.
    fn ckpt_never() -> crate::exec_pipeline::CheckpointPolicy {
        crate::exec_pipeline::CheckpointPolicy::default()
    }

    /// The 130 P2 blocks in Classic with resident books: serial, pipelined
    /// per block, and pipelined with a checkpoint every 5 blocks and never by
    /// time (only the attest height 100, the epoch boundaries 50 / 100 and
    /// shutdown) give the same per-block consensus write sets (every `h_n`),
    /// running hash and full CF dump. The checkpoint runs really kept blocks
    /// above the durable marker.
    #[test]
    fn checkpoint_interval_matches_per_block_classic() {
        use torus_bridge::native_executor::BookMode;
        let (blocks, _fed) = p2_blocks(false);
        let mode = Some(BookMode::Classic);
        let serial = p2_run(&blocks, false, mode, false, &P2Fault::None);
        let per_block = p2_run(&blocks, true, mode, false, &P2Fault::None);
        assert_eq!(per_block.max_lag, 0, "per-block flush: every block durable");
        assert!(serial.hash.is_some());
        let all: Vec<u64> = (1..=P2_BLOCKS).collect();
        for (name, policy, min_lag) in [("every 5", ckpt_every(5), 4), ("never", ckpt_never(), 40)]
        {
            let run = p2_run_with(&blocks, true, mode, false, &P2Fault::None, Some(policy));
            assert!(
                run.max_lag >= min_lag,
                "{name}: max lag {} < {min_lag}",
                run.max_lag
            );
            for (what, base) in [("serial", &serial), ("per-block", &per_block)] {
                assert_write_sets_equal(
                    &base.captured,
                    &run.captured,
                    &format!("{name} vs {what}"),
                );
                assert_eq!(base.hash, run.hash, "{name} vs {what}: running hash");
                assert_dumps_equal(&base.dump, &run.dump, &format!("{name} vs {what}"));
            }
            assert_eq!(
                run.captured.iter().map(|(h, _)| *h).collect::<Vec<_>>(),
                all,
                "{name}: every height hashed once"
            );
        }
    }

    // ---- 8k L3.1 (`TORUS_BOOK_COALESCE`): checkpoint-coalesced Classic book
    // save (docs/plans/deep-book-save-options.md section 3). The deep-level
    // traffic below is b0's (perf/mode3-checkpoints-b0), unchanged. ----

    /// b0 deep-level traffic: a maker resting many orders on single price
    /// levels (150 bids at 80 per market: 3 chunks of `LEVEL_CHUNK_SEQS` =
    /// 64; asks at 125, more bids at 79), a stop far from the mark, takers
    /// sweeping across chunk boundaries, and cancel-alls deleting whole deep
    /// levels (market 2 at 96, re-placed after) and a stop (market 3 at 104).
    const P2_DEEP_MAKER: u8 = 96;
    const P2_DEEP_TAKER: u8 = 97;

    fn p2_deep_seed(db: &StateDb) {
        use torus_core::position::{NativeBalance, PositionManager};
        let pm = PositionManager::new(db.clone());
        for seed in [P2_DEEP_MAKER, P2_DEEP_TAKER] {
            pm.put_native_balance(
                &oracle_addr(seed),
                &NativeBalance {
                    available: px(10_000_000),
                    order_margin: FixedPoint::ZERO,
                },
            )
            .unwrap();
        }
    }

    /// The deep actions of height `h` (`(signer seed, action)`), a pure
    /// function of `h`.
    fn p2_deep_actions(h: u64) -> Vec<(u8, NativeAction)> {
        let limit = |m: u64, is_buy: bool, price: i64, qty: i64| torus_types::PlaceOrderParams {
            market_id: m,
            is_buy,
            price: px(price),
            quantity: px(qty),
            order_type: torus_types::OrderType::Limit,
            time_in_force: torus_types::TimeInForce::GTC,
            reduce_only: false,
            client_order_id: None,
        };
        let m = C5_MARKETS[(h % 3) as usize];
        let mut out = Vec::new();
        let mut maker = Vec::new();
        if (2..=19).contains(&h) {
            maker.extend((0..25).map(|_| limit(m, true, 80, 1)));
            maker.extend((0..10).map(|_| limit(m, false, 125, 1)));
            if h % 5 == 4 {
                maker.extend((0..20).map(|_| limit(m, true, 79, 1)));
            }
        }
        if h == 99 || h == 101 {
            maker.extend((0..25).map(|_| limit(2, true, 80, 1)));
        }
        if !maker.is_empty() {
            out.push((P2_DEEP_MAKER, NativeAction::PlaceOrderBatch(maker)));
        }
        match h {
            20 => out.push((
                P2_DEEP_MAKER,
                NativeAction::PlaceOrder(torus_types::PlaceOrderParams {
                    order_type: torus_types::OrderType::StopMarket { trigger: px(30) },
                    ..limit(3, false, 20, 1)
                }),
            )),
            60 => out.push((
                P2_DEEP_MAKER,
                NativeAction::PlaceOrder(torus_types::PlaceOrderParams {
                    order_type: torus_types::OrderType::StopLimit {
                        trigger: px(300),
                        limit: px(301),
                    },
                    ..limit(1, true, 301, 1)
                }),
            )),
            96 => out.push((
                P2_DEEP_MAKER,
                NativeAction::CancelAllOrders { market_id: Some(2) },
            )),
            104 => out.push((
                P2_DEEP_MAKER,
                NativeAction::CancelAllOrders { market_id: Some(3) },
            )),
            25 | 41 | 66 | 88 | 111 => out.push((
                P2_DEEP_TAKER,
                NativeAction::PlaceOrder(limit(m, false, 79, 70)),
            )),
            33 | 77 => out.push((
                P2_DEEP_TAKER,
                NativeAction::PlaceOrder(limit(m, true, 125, 15)),
            )),
            _ => {}
        }
        out
    }

    /// 8k L3.1 stream length: multi-hundred blocks, the last neither an
    /// attest height nor an epoch boundary (`C5_EPOCH` 50), so a window
    /// never closed by time is still open at shutdown.
    const L31_BLOCKS: u64 = 260;

    /// The deep P2 stream (reduce-only places on) over `L31_BLOCKS` heights.
    fn l31_blocks() -> Vec<TorusBlock> {
        p2_blocks_len(L31_BLOCKS, true, false, true).0
    }

    /// The deep traders, and the running state hash NOT configured (L3.1
    /// runs only with the hash off).
    fn l31_seed(db: &StateDb) {
        p2_deep_seed(db);
        torus_state::running_hash::configure_activation(db, None).unwrap();
    }

    /// One pipelined Classic resident run of `blocks` on the L3.1 seed, with
    /// a full CF dump at every durable height. `ckpt`: the checkpoint policy
    /// (`None`: the per-block flush, the golden); `coalesce`:
    /// `TORUS_BOOK_COALESCE` requested; `fast`: the epoch fast path (`None`:
    /// off, epoch boundaries are barriers); `random`: a seeded extra
    /// trigger; `skip`: the mutation seam.
    fn l31_run(
        blocks: &[TorusBlock],
        ckpt: Option<crate::exec_pipeline::CheckpointPolicy>,
        coalesce: bool,
        fast: Option<bool>,
        fault: &P2Fault,
        random: Option<u64>,
        skip: Option<CloseKind>,
    ) -> P2Run {
        struct Reset;
        impl Drop for Reset {
            fn drop(&mut self) {
                P2_DUMP_DURABLE.set(false);
                P2_BOOK_COALESCE.set(false);
                P2_COALESCE_SKIP.set(None);
                P2_CKPT_RANDOM.set(None);
            }
        }
        let _reset = Reset;
        P2_DUMP_DURABLE.set(true);
        P2_BOOK_COALESCE.set(coalesce);
        P2_COALESCE_SKIP.set(skip);
        P2_CKPT_RANDOM.set(random);
        p2_run_full(
            blocks,
            true,
            Some(torus_bridge::native_executor::BookMode::Classic),
            false,
            fault,
            ckpt,
            &l31_seed,
            false,
            None,
            fast,
        )
    }

    /// The first place `run` differs from the per-block `golden`: the full CF
    /// dump and the persisted native root at each height `run` made durable
    /// (the golden has both at every height), then the final dump.
    fn l31_divergence(golden: &P2Run, run: &P2Run) -> Option<String> {
        let differ = |a: &[CfDump], b: &[CfDump]| {
            a.iter()
                .zip(b)
                .find(|((_, x), (_, y))| x != y)
                .map(|((cf, _), _)| *cf)
        };
        for (s, dump) in &run.dumps {
            let Some((_, want)) = golden.dumps.iter().find(|(h, _)| h == s) else {
                return Some(format!("no golden dump at {s}"));
            };
            if let Some(cf) = differ(want, dump) {
                return Some(format!("CF {cf} at checkpoint {s}"));
            }
        }
        for (s, root) in &run.roots {
            let want = golden.roots.iter().find(|(h, _)| h == s).map(|(_, r)| *r);
            if want != Some(*root) {
                return Some(format!("native root at checkpoint {s}"));
            }
        }
        differ(&golden.dump, &run.dump).map(|cf| format!("CF {cf} in the final dump"))
    }

    /// `(closes with owed books, books they encoded)` from a run's metrics.
    fn l31_closes(run: &P2Run) -> (u64, u64) {
        let text = run.metrics.encode();
        (
            metric_value(&text, "torus_exec_book_coalesce_close_books_count") as u64,
            metric_value(&text, "torus_exec_book_coalesce_close_books_sum") as u64,
        )
    }

    /// 8k L3.1 golden (a): the deep stream with `TORUS_BOOK_COALESCE` on (no
    /// per-block whole-book encode; each window close encodes the window's
    /// dirty books once) under every close kind: a block count (every 1 / 5
    /// / 7), never by time (attest heights 100 / 200, the epoch boundaries
    /// 50 / 100 / ... as barriers, the shutdown drain), the same with the
    /// epoch fast path (epoch closes instead of barriers), a 1 ms interval
    /// and a seeded random trigger (a byte cap keeps L3.1 off, see (d)). At every height a run made
    /// durable, its full CF dump (every book blob included) and native root
    /// equal the per-block Classic run's at that height, and so do the final
    /// dumps. Non-vacuous: the runs skipped per-block encodes, closes encoded
    /// the owed books (every 1: exactly the skipped ones), windows spanned
    /// blocks.
    #[test]
    fn l31_coalesced_book_save_matches_per_block_at_every_checkpoint() {
        let blocks = l31_blocks();
        let golden = l31_run(&blocks, None, false, None, &P2Fault::None, None, None);
        assert_eq!(golden.max_lag, 0, "golden: per-block flush");
        assert_eq!(
            golden.dumps.len() as u64,
            L31_BLOCKS,
            "golden: a dump per height"
        );
        assert_eq!(
            golden.metrics.exec_book_coalesce_skipped.get(),
            0,
            "golden: L3.1 off"
        );
        let fills = golden.metrics.orders_matched.get();
        let resting: usize = golden
            .dumps
            .iter()
            .map(|(_, d)| {
                d.iter()
                    .find(|(cf, _)| *cf == torus_state::cf::CF_NATIVE_ORDER_BOOKS)
                    .map_or(0, |(_, rows)| rows.iter().map(|(_, v)| v.len()).sum())
            })
            .max()
            .unwrap_or(0);
        println!(
            "L3.1 golden: {L31_BLOCKS} blocks, fills {fills}, liquidations {}, largest book CF {resting} bytes",
            golden.metrics.liquidations_triggered.get()
        );
        assert!(fills >= 300, "fills {fills}");
        assert!(resting >= 50_000, "deep books: {resting} bytes");
        let interval = crate::exec_pipeline::CheckpointPolicy {
            interval: Some(std::time::Duration::from_millis(1)),
            ..Default::default()
        };
        for (name, policy, fast, random, min_lag) in [
            ("every 1", ckpt_every(1), None, None, 0),
            ("every 5", ckpt_every(5), None, None, 4),
            ("every 7", ckpt_every(7), None, None, 6),
            ("never, barriers", ckpt_never(), None, None, 40),
            ("never, epoch fast path", ckpt_never(), Some(true), None, 40),
            ("interval 1 ms", interval, None, None, 0),
            ("random", ckpt_never(), Some(true), Some(0x1a31), 2),
        ] {
            let what = format!("L3.1 {name}");
            let run = l31_run(
                &blocks,
                Some(policy),
                true,
                fast,
                &P2Fault::None,
                random,
                None,
            );
            assert_eq!(l31_divergence(&golden, &run), None, "{what}");
            let skipped = run.metrics.exec_book_coalesce_skipped.get();
            let (closes, encoded) = l31_closes(&run);
            println!(
                "{what}: max lag {}, checkpoints {}, skipped {skipped}, closes {closes} encoding {encoded}",
                run.max_lag,
                run.metrics.exec_checkpoints.get()
            );
            assert!(
                run.max_lag >= min_lag,
                "{what}: max lag {} < {min_lag}",
                run.max_lag
            );
            assert!(skipped >= 300, "{what}: skipped {skipped}");
            assert!(closes >= 3 && encoded > 0 && encoded <= skipped, "{what}");
            if name == "every 1" {
                assert_eq!(encoded, skipped, "{what}: each block's own books");
            } else {
                assert!(encoded < skipped, "{what}: windows coalesced");
            }
        }
    }

    /// 8k L3.1 (b): crash mid-window. A checkpoint every 5 blocks, L3.1 on,
    /// six crashes at non-checkpoint heights: three lose the open window
    /// before its close encoded anything (W fails its next job), three after
    /// the close encoded and handed off (W fails the checkpoint in flight).
    /// Each restart replays (S, last] from the DB with a fresh window: the
    /// holder carried over is ahead of the DB, the guard rebuilds the books,
    /// and nothing is owed, so no fail-stop. The run equals the uncrashed
    /// per-block golden at every checkpoint and at the end.
    #[test]
    fn l31_crash_mid_window_replays_from_s_to_the_golden() {
        let blocks = l31_blocks();
        let golden = l31_run(&blocks, None, false, None, &P2Fault::None, None, None);
        let crashes = [
            (12, false),
            (23, true),
            (58, false),
            (91, true),
            (144, false),
            (203, true),
        ];
        let fault = P2Fault::CkptCrash(crashes.to_vec());
        let run = l31_run(&blocks, Some(ckpt_every(5)), true, None, &fault, None, None);
        assert_eq!(run.faults, crashes.len() as u64);
        for (durable, last) in &run.crash_windows {
            assert!(durable < last, "crash window ({durable}, {last}]");
        }
        assert_eq!(l31_divergence(&golden, &run), None, "L3.1 crashes");
        assert!(run.metrics.exec_book_coalesce_skipped.get() >= 300);
        assert_eq!(
            run.metrics.exec_resident_rebuilds.get(),
            1 + crashes.len() as u64,
            "one guard rebuild per crash"
        );
    }

    /// 8k L3.1 (c): a resident-book rebuild while the window owes books
    /// fail-stops. Checkpoints never by time, L3.1 on: the holder drops its
    /// books mid-window (as a stale guard trip does); the next native block
    /// would rebuild them through L / C / the DB, which hold older blobs, so
    /// it fail-stops and nothing lands past S; a restart replays from S and
    /// reaches the per-block golden. Right after a close the window owes
    /// nothing: the same drop is a plain rebuild (C / DB hold every blob)
    /// and the run equals the golden.
    #[test]
    fn l31_stale_holder_rebuild_with_unsaved_books_fail_stops() {
        let blocks = l31_blocks();
        let n = 40usize;
        let golden = l31_run(&blocks[..n], None, false, None, &P2Fault::None, None, None);
        let ctx_for = |config: &ChainConfig, db: &StateDb, policy| {
            let mut ctx = make_exec_ctx(config, db);
            ctx.test_book_mode = Some(torus_bridge::native_executor::BookMode::Classic);
            ctx.checkpoint = Some(policy);
            ctx.configure_book_coalesce(
                true,
                torus_state::running_hash::read_configured_activation(db),
            );
            assert!(ctx.book_coalesce, "L3.1 on");
            ctx
        };
        let run = |ctx: &ExecutionContext, db: &StateDb, range: std::ops::Range<usize>| {
            for b in &blocks[range] {
                dispatch_and_execute(ctx, db, b);
                assert!(
                    !ctx.exec_failed.load(Ordering::SeqCst),
                    "fail-stop at {}",
                    b.header.height
                );
            }
        };

        // Mid-window: the rebuild fail-stops.
        let (config, db) = p2_fixture();
        l31_seed(&db);
        let mut ctx = ctx_for(&config, &db, ckpt_never());
        ctx.attach_flush_worker(None);
        let k = 30usize;
        run(&ctx, &db, 0..k);
        assert!(
            !ctx.ckpt.lock().unwrap().unsaved.is_empty(),
            "the window owes books"
        );
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        let durable = read_native_applied_height(&db);
        assert!(durable.unwrap_or(0) < k as u64, "window open: {durable:?}");
        ctx.resident_books.lock().unwrap().invalidate();
        dispatch_and_execute(&ctx, &db, &blocks[k]);
        assert!(
            ctx.exec_failed.load(Ordering::SeqCst),
            "a rebuild with unsaved books must fail-stop"
        );
        drop(ctx);
        assert_eq!(
            read_native_applied_height(&db),
            durable,
            "nothing past S landed"
        );
        let replay = ctx_for(&config, &db, ckpt_never());
        let (_last, parked) = TorusApp::replay_committed(&db, &replay);
        assert_eq!(parked, None);
        assert!(!replay.exec_failed.load(Ordering::SeqCst), "replay");
        assert_eq!(
            read_native_applied_height(&db),
            Some(k as u64 + 1),
            "replayed to k + 1"
        );
        run(&replay, &db, k + 1..n);
        drop(replay);
        assert_dumps_equal(
            &golden.dump,
            &dump_all_cfs(&db),
            "restart after the fail-stop",
        );

        // Right after a close: nothing owed, a plain rebuild.
        let (config, db) = p2_fixture();
        l31_seed(&db);
        let mut ctx = ctx_for(&config, &db, ckpt_every(5));
        ctx.attach_flush_worker(None);
        run(&ctx, &db, 0..10);
        {
            let st = ctx.ckpt.lock().unwrap();
            assert_eq!(st.base, 10, "closed at 10");
            assert!(st.unsaved.is_empty(), "nothing owed after a close");
        }
        ctx.resident_books.lock().unwrap().invalidate();
        run(&ctx, &db, 10..n);
        drop(ctx);
        assert_dumps_equal(
            &golden.dump,
            &dump_all_cfs(&db),
            "rebuild right after a close",
        );
    }

    /// 8k L3.1 (d): with the running state hash configured L3.1 stays off.
    /// `configure_book_coalesce` refuses it (as without a checkpoint
    /// interval, or with a checkpoint byte cap: owner option C, as b1), and
    /// a run that requests it on the hash-on fixture encodes
    /// every book per block: per-block write sets (every `h_n`), running hash
    /// and full CF dump equal the run that does not request it.
    #[test]
    fn l31_hash_configured_keeps_the_per_block_encode() {
        let (config, db) = p2_fixture();
        let mut ctx = make_exec_ctx(&config, &db);
        ctx.checkpoint = Some(ckpt_every(5));
        for (requested, hash, on) in [
            (true, Some(1), false),
            (true, Some(500), false),
            (false, None, false),
            (true, None, true),
        ] {
            ctx.configure_book_coalesce(requested, hash);
            assert_eq!(
                ctx.book_coalesce, on,
                "requested {requested}, hash {hash:?}"
            );
        }
        ctx.checkpoint = None;
        ctx.configure_book_coalesce(true, None);
        assert!(!ctx.book_coalesce, "no checkpoint interval");
        // A byte cap cannot count the coalesced blobs: it keeps L3.1 off.
        for cap in [1, 256 << 20] {
            for base in [ckpt_every(5), ckpt_never()] {
                ctx.checkpoint = Some(crate::exec_pipeline::CheckpointPolicy {
                    max_bytes: Some(cap),
                    ..base
                });
                ctx.configure_book_coalesce(true, None);
                assert!(!ctx.book_coalesce, "byte cap {cap}");
            }
        }
        drop(ctx);

        let blocks = p2_blocks_full(false, false, true).0;
        let run = |coalesce: bool| {
            P2_BOOK_COALESCE.set(coalesce);
            let r = p2_run_full(
                &blocks,
                true,
                Some(torus_bridge::native_executor::BookMode::Classic),
                false,
                &P2Fault::None,
                Some(ckpt_every(5)),
                &p2_deep_seed,
                false,
                None,
                None,
            );
            P2_BOOK_COALESCE.set(false);
            r
        };
        let (off, on) = (run(false), run(true));
        assert!(on.hash.is_some(), "the hash is on");
        assert_eq!(
            on.metrics.exec_book_coalesce_skipped.get(),
            0,
            "per-block encode"
        );
        assert_write_sets_equal(&off.captured, &on.captured, "L3.1 requested, hash on");
        assert_eq!(off.hash, on.hash, "running hash");
        assert_dumps_equal(&off.dump, &on.dump, "L3.1 requested, hash on");
    }

    /// 8k L3.1 default ON (owner s131, perf doc section 110): with
    /// `TORUS_BOOK_COALESCE` unset the startup gate turns L3.1 on where every
    /// precondition holds (checkpoint interval, no byte cap, running hash not
    /// configured, Classic + resident books + the untouched-block advance),
    /// with no warning; when any one fails it stays off with exactly ONE
    /// warning naming the reason. `0` is off without a log line.
    #[test]
    fn l31_on_by_default_where_preconditions_hold() {
        use torus_bridge::native_executor::{book_coalesce_blocker_for, BookMode};
        let default = crate::exec_pipeline::parse_book_coalesce(None);
        assert!(default, "TORUS_BOOK_COALESCE unset: requested");
        let (config, db) = p2_fixture();
        let mut ctx = make_exec_ctx(&config, &db);
        let classic = book_coalesce_blocker_for(BookMode::Classic, true, true);
        assert_eq!(classic, None, "Classic + resident + advance: no blocker");
        let capped = crate::exec_pipeline::CheckpointPolicy {
            max_bytes: Some(256 << 20),
            ..ckpt_every(5)
        };
        let warns = |logs: &str| {
            logs.lines()
                .filter(|l| l.contains("WARN") && l.contains("TORUS_BOOK_COALESCE"))
                .count()
        };
        // (checkpoint, hash activation, book blocker, reason fragment)
        type Case = (
            Option<crate::exec_pipeline::CheckpointPolicy>,
            Option<u64>,
            Option<&'static str>,
            &'static str,
        );
        let blocked: Vec<Case> = vec![
            (None, None, classic, "no checkpoint interval"),
            (Some(capped), None, classic, "byte cap"),
            (Some(ckpt_every(5)), Some(1), classic, "running state hash"),
            (
                Some(ckpt_every(5)),
                None,
                book_coalesce_blocker_for(BookMode::LevelAuthorityChunked, true, true),
                "not Classic",
            ),
            (
                Some(ckpt_every(5)),
                None,
                book_coalesce_blocker_for(BookMode::OrderRows, true, true),
                "not Classic",
            ),
            (
                Some(ckpt_every(5)),
                None,
                book_coalesce_blocker_for(BookMode::Classic, false, true),
                "resident books are off",
            ),
            (
                Some(ckpt_every(5)),
                None,
                book_coalesce_blocker_for(BookMode::Classic, true, false),
                "untouched-block advance is off",
            ),
        ];
        for (ckpt, hash, book, reason) in blocked {
            ctx.checkpoint = ckpt;
            ctx.book_coalesce = true;
            let logs = capture_logs(|| ctx.configure_book_coalesce_with(default, hash, book));
            assert!(!ctx.book_coalesce, "{reason}: stays off");
            assert_eq!(warns(&logs), 1, "{reason}: one warning\n{logs}");
            assert!(logs.contains(reason), "{reason}: named\n{logs}");
            assert!(!logs.contains("save ON"), "{reason}\n{logs}");
        }
        // Every precondition holds: on, no warning, the ON line once (bench
        // harnesses grep for it).
        for ckpt in [ckpt_every(5), ckpt_never()] {
            ctx.checkpoint = Some(ckpt);
            let logs = capture_logs(|| ctx.configure_book_coalesce_with(default, None, classic));
            assert!(ctx.book_coalesce, "preconditions hold: on by default");
            assert_eq!(warns(&logs), 0, "{logs}");
            assert_eq!(
                logs.matches("L3.1 coalesced Classic book save ON").count(),
                1,
                "{logs}"
            );
        }
        // `0` / `false`: the kill switch, silent.
        for v in ["0", "false"] {
            let requested = crate::exec_pipeline::parse_book_coalesce(Some(v));
            let logs = capture_logs(|| ctx.configure_book_coalesce_with(requested, None, classic));
            assert!(!ctx.book_coalesce, "{v}: off");
            assert!(!logs.contains("TORUS_BOOK_COALESCE"), "{v}: silent\n{logs}");
        }
    }

    /// 8k L3.1 (e), mutation: a close that skips its coalesced encode (the
    /// books stay owed to a later close) fails the golden for every close
    /// kind L3.1 runs under (not the byte cap, which keeps it off), so the harness catches a missed trigger (the design's main risk:
    /// a checkpoint S silently holding old blobs). A skip whose debt then
    /// meets no open window fail-stops, which the harness also catches.
    #[test]
    fn l31_golden_catches_a_close_that_skips_its_encode() {
        let blocks = l31_blocks();
        let golden = l31_run(&blocks, None, false, None, &P2Fault::None, None, None);
        let interval = crate::exec_pipeline::CheckpointPolicy {
            interval: Some(std::time::Duration::from_millis(1)),
            ..Default::default()
        };
        for (kind, policy, fast, random) in [
            (CloseKind::Every, ckpt_every(5), None, None),
            (CloseKind::Attest, ckpt_never(), Some(true), None),
            (CloseKind::Epoch, ckpt_never(), Some(true), None),
            (CloseKind::Interval, interval, None, None),
            (CloseKind::TestDue, ckpt_never(), Some(true), Some(0x1a31)),
            (CloseKind::Barrier, ckpt_never(), None, None),
            (CloseKind::Shutdown, ckpt_never(), Some(true), None),
        ] {
            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                l31_run(
                    &blocks,
                    Some(policy),
                    true,
                    fast,
                    &P2Fault::None,
                    random,
                    Some(kind),
                )
            }));
            match outcome {
                Ok(run) => {
                    let found = l31_divergence(&golden, &run);
                    println!("L3.1 mutant, {kind:?} close skips its encode: {found:?}");
                    assert!(
                        found.is_some(),
                        "{kind:?}: a close that skips its encode passed the golden"
                    );
                }
                Err(panic) => {
                    let msg = panic
                        .downcast_ref::<String>()
                        .cloned()
                        .or_else(|| panic.downcast_ref::<&str>().map(|s| s.to_string()))
                        .unwrap_or_default();
                    println!("L3.1 mutant, {kind:?} close skips its encode: run failed ({msg})");
                    assert!(msg.contains("fail-stop"), "{kind:?}: {msg}");
                }
            }
        }
    }

    /// Item 6 Phase 3: the barrier fixture. `pipeline_fixture_blocks` (13
    /// blocks, epoch length 4) with an EVM tx in block 6 and a buffered slash
    /// at block 10; `policy` on a pipelined context (`None`: per block;
    /// `on = false`: serial). Returns the DB, the per-block write sets and
    /// the durable marker after each block.
    fn ckpt_barrier_run(
        on: bool,
        policy: Option<crate::exec_pipeline::CheckpointPolicy>,
    ) -> (StateDb, CapturedWrites, Vec<Option<u64>>) {
        let key = k256::ecdsa::SigningKey::from_slice(&[61u8; 32]).unwrap();
        let validator = Address::repeat_byte(0x77);
        let mut blocks = pipeline_fixture_blocks();
        blocks[5].evm_transactions = vec![signed_sstore_create(&key, 0)];
        blocks[5].header.evm_tx_count = 1;
        link_blocks(&mut blocks);
        let (mut config, db) = make_test_config_and_db();
        config.epoch_length = 4;
        fund_pipeline_fixture(&db);
        db.put_account(
            &k256_address(&key),
            &revm::state::AccountInfo {
                balance: U256::from(10u128.pow(18)),
                nonce: 0,
                code_hash: KECCAK_EMPTY_CODE,
                code: None,
                account_id: None,
            },
        )
        .unwrap();
        register_proposer(&db, validator);
        torus_state::running_hash::capture_begin(&db);
        let mut ctx = make_exec_ctx(&config, &db);
        ctx.checkpoint = policy;
        if on {
            ctx.attach_flush_worker(None);
        }
        let mut markers = Vec::new();
        for b in &blocks {
            let h = b.header.height;
            let durable = persist_committed_block_durably(&db, b);
            let slashes = if h == 10 {
                vec![PendingSlash {
                    validator,
                    fraction_bps: 500,
                    reason: SlashReason::DoubleSign,
                    tombstone: false,
                }]
            } else {
                vec![]
            };
            ctx.execute_committed_block_with(b, slashes, durable);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "fail-stop at {h}");
            if let Some(w) = ctx.flush_worker.as_ref() {
                assert!(w.wait_idle());
            }
            markers.push(read_native_applied_height(&db));
        }
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&db);
        (db, captured, markers)
    }

    /// Barrier blocks (EVM 6, slash 10, epoch boundaries 4 / 8 / 12) drain
    /// the since-checkpoint layer: with checkpoints never by time, the
    /// durable marker after every block is the last barrier at or below it
    /// (S == that height after each barrier), and shutdown checkpoints 13.
    /// Write sets, running hash and CF dump equal the per-block and serial
    /// runs.
    #[test]
    fn checkpoint_barriers_drain_layer() {
        let (db, captured, markers) = ckpt_barrier_run(true, Some(ckpt_never()));
        let expected: Vec<Option<u64>> = (1..=13u64)
            .map(|h| [4u64, 6, 8, 10, 12].into_iter().filter(|b| *b <= h).max())
            .collect();
        assert_eq!(markers, expected, "durable marker after each block");
        assert_eq!(
            read_native_applied_height(&db),
            Some(13),
            "shutdown checkpoint"
        );
        let evm_sender = k256::ecdsa::SigningKey::from_slice(&[61u8; 32]).unwrap();
        assert_eq!(
            db.get_account(&k256_address(&evm_sender))
                .unwrap()
                .unwrap()
                .nonce,
            1,
            "the EVM tx executed"
        );
        for (what, on, policy) in [("per-block", true, None), ("serial", false, None)] {
            let (db_ref, captured_ref, _) = ckpt_barrier_run(on, policy);
            assert_write_sets_equal(&captured_ref, &captured, &format!("never vs {what}"));
            assert_eq!(
                torus_state::running_hash::read_running_hash(&db_ref),
                torus_state::running_hash::read_running_hash(&db),
                "{what}: running hash"
            );
            assert_dumps_equal(
                &dump_all_cfs(&db_ref),
                &dump_all_cfs(&db),
                &format!("never vs {what}"),
            );
        }
    }

    /// Every attest height (`h % 100 == 0`) forces a checkpoint: 105 empty
    /// blocks without an epoch boundary, checkpoints never by time; nothing
    /// is durable before 100, the marker and the attest checkpoint row of
    /// 100 are durable right after it. Same dump as the per-block run.
    #[test]
    fn checkpoint_attest_heights_force_checkpoint() {
        let mut blocks: Vec<TorusBlock> = (1..=105).map(|h| make_block(h, vec![])).collect();
        link_blocks(&mut blocks);
        let run = |policy: Option<crate::exec_pipeline::CheckpointPolicy>| {
            let (mut config, db) = make_test_config_and_db();
            config.epoch_length = 1_000;
            let mut ctx = make_exec_ctx(&config, &db);
            ctx.checkpoint = policy;
            ctx.attach_flush_worker(None);
            let mut markers = Vec::new();
            for b in &blocks {
                dispatch_and_execute(&ctx, &db, b);
                assert!(!ctx.exec_failed.load(Ordering::SeqCst));
                assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
                let h = b.header.height;
                markers.push(read_native_applied_height(&db));
                if h == 100 {
                    assert!(
                        torus_state::running_hash::read_checkpoint(&db, 100).is_some(),
                        "attest checkpoint row 100 durable right after block 100"
                    );
                }
            }
            drop(ctx);
            (db, markers)
        };
        let (db, markers) = run(Some(ckpt_never()));
        let expected: Vec<Option<u64>> = (1..=105u64).map(|h| (h >= 100).then_some(100)).collect();
        assert_eq!(markers, expected, "durable marker after each block");
        assert_eq!(
            read_native_applied_height(&db),
            Some(105),
            "shutdown checkpoint"
        );
        let (db_ref, _) = run(None);
        assert_dumps_equal(
            &dump_all_cfs(&db_ref),
            &dump_all_cfs(&db),
            "never vs per-block",
        );
    }

    /// The byte cap counts the blocks a checkpoint at `n` would close (L +
    /// the folded n-1 + n), not only L: with a 1-byte cap every block's own
    /// rows (at least the applied marker) exceed it, so every block
    /// checkpoints at its own height (durable marker == h after each block),
    /// as with a per-block flush. Before the fix, L held only up to n-2 at
    /// the check, so the cap fired two blocks late. Same dump as per block.
    #[test]
    fn checkpoint_byte_cap_counts_folded_blocks() {
        let mut blocks: Vec<TorusBlock> = (1..=10).map(|h| make_block(h, vec![])).collect();
        link_blocks(&mut blocks);
        let run = |policy: Option<crate::exec_pipeline::CheckpointPolicy>| {
            let (mut config, db) = make_test_config_and_db();
            config.epoch_length = 1_000;
            let mut ctx = make_exec_ctx(&config, &db);
            ctx.checkpoint = policy;
            ctx.attach_flush_worker(None);
            let mut markers = Vec::new();
            for b in &blocks {
                dispatch_and_execute(&ctx, &db, b);
                assert!(!ctx.exec_failed.load(Ordering::SeqCst));
                assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
                markers.push(read_native_applied_height(&db));
            }
            drop(ctx);
            (db, markers)
        };
        let cap = crate::exec_pipeline::CheckpointPolicy {
            max_bytes: Some(1),
            ..Default::default()
        };
        let (db, markers) = run(Some(cap));
        let expected: Vec<Option<u64>> = (1..=10u64).map(Some).collect();
        assert_eq!(markers, expected, "durable marker after each block");
        let (db_ref, _) = run(None);
        assert_dumps_equal(
            &dump_all_cfs(&db_ref),
            &dump_all_cfs(&db),
            "1-byte cap vs per-block",
        );
    }

    // ---- s124 epoch-boundary fast path (TORUS_EPOCH_FAST_PATH) ----

    /// One run of [`fast_path_run`].
    struct FastPathRun {
        db: StateDb,
        /// Every hashed block's consensus write set.
        captured: CapturedWrites,
        /// The durable marker after each block (W idle).
        markers: Vec<Option<u64>>,
        /// The heights whose block took the pipelined path.
        pipelined: Vec<u64>,
        /// The persisted native root after shutdown.
        root: torus_types::B256,
    }

    /// The permanent staker of [`fast_path_run`]: its reward credits an EVM
    /// account at every boundary (`CF_ACCOUNTS`), so the boundary's dirty
    /// EVM accounts are not empty and the mirror resync runs (F2).
    fn fast_path_staker() -> Address {
        Address::repeat_byte(0x55)
    }

    /// s124 epoch fast path: `pipeline_fixture_blocks` (13 blocks, epoch
    /// length 4: boundaries 4 / 8 / 12) plus a permanent stake, with an EVM
    /// tx in block `evm_at` and a buffered slash at `slash_at`, on a context
    /// with W (`on`), checkpoint `policy` and `TORUS_EPOCH_FAST_PATH` =
    /// `fast`. A block took the pipelined path iff `last_job` is its frozen
    /// set right after it: a barrier clears `last_job` and the serial path
    /// never sets it.
    fn fast_path_run(
        on: bool,
        fast: bool,
        policy: Option<crate::exec_pipeline::CheckpointPolicy>,
        evm_at: Option<u64>,
        slash_at: Option<u64>,
    ) -> FastPathRun {
        fast_path_run_evm(on, fast, false, policy, evm_at, slash_at)
    }

    /// [`fast_path_run`] with the item 7 option 0 EVM fast path flag
    /// (`TORUS_EVM_FAST_PATH`) = `evm_fast`.
    fn fast_path_run_evm(
        on: bool,
        fast: bool,
        evm_fast: bool,
        policy: Option<crate::exec_pipeline::CheckpointPolicy>,
        evm_at: Option<u64>,
        slash_at: Option<u64>,
    ) -> FastPathRun {
        torus_state::native_trie::force_native_trie_maintenance_on_for_tests();
        let key = k256::ecdsa::SigningKey::from_slice(&[61u8; 32]).unwrap();
        let validator = Address::repeat_byte(0x77);
        let mut blocks = pipeline_fixture_blocks();
        if let Some(h) = evm_at {
            let b = &mut blocks[h as usize - 1];
            b.evm_transactions = vec![signed_sstore_create(&key, 0)];
            b.header.evm_tx_count = 1;
        }
        link_blocks(&mut blocks);
        let (mut config, db) = make_test_config_and_db();
        config.epoch_length = 4;
        fund_pipeline_fixture(&db);
        db.put_account(
            &k256_address(&key),
            &revm::state::AccountInfo {
                balance: U256::from(10u128.pow(18)),
                nonce: 0,
                code_hash: KECCAK_EMPTY_CODE,
                code: None,
                account_id: None,
            },
        )
        .unwrap();
        register_proposer(&db, validator);
        let stake = U256::from(10u128.pow(18));
        fund_evm_balance(&db, fast_path_staker(), stake);
        StakingManager::new(db.clone())
            .permanent_stake(fast_path_staker(), stake, 0)
            .unwrap();
        // The EVM trie over the accounts written above, as the node builds it
        // at boot: otherwise the first resync (the staker's reward at 4)
        // starts a partial trie and the EVM block's incremental root fails
        // its full-scan cross-check. With it, a resync W missed would too.
        torus_state::incremental::ensure_trie_built(&db).unwrap();
        torus_state::running_hash::capture_begin(&db);
        let mut ctx = make_exec_ctx(&config, &db);
        ctx.checkpoint = policy;
        ctx.epoch_fast_path = fast;
        ctx.evm_fast_path = evm_fast;
        if on {
            ctx.attach_flush_worker(None);
        }
        let (mut markers, mut pipelined) = (Vec::new(), Vec::new());
        for b in &blocks {
            let h = b.header.height;
            let durable = persist_committed_block_durably(&db, b);
            let slashes = if slash_at == Some(h) {
                vec![PendingSlash {
                    validator,
                    fraction_bps: 500,
                    reason: SlashReason::DoubleSign,
                    tombstone: false,
                }]
            } else {
                vec![]
            };
            ctx.execute_committed_block_with(b, slashes, durable);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst), "fail-stop at {h}");
            let top = ctx.last_job.lock().unwrap().as_ref().map(|p| p.height());
            if top == Some(h) {
                pipelined.push(h);
            }
            if let Some(w) = ctx.flush_worker.as_ref() {
                assert!(w.wait_idle());
            }
            markers.push(read_native_applied_height(&db));
        }
        drop(ctx);
        let captured = torus_state::running_hash::capture_take(&db);
        let root = torus_state::native_trie::persisted_native_root(&db).unwrap();
        FastPathRun {
            db,
            captured,
            markers,
            pipelined,
            root,
        }
    }

    /// `run` equals `base`: every block's consensus write set, the running
    /// hash, the persisted native root and every CF.
    fn assert_fast_path_runs_equal(base: &FastPathRun, run: &FastPathRun, what: &str) {
        assert_write_sets_equal(&base.captured, &run.captured, what);
        assert_eq!(
            torus_state::running_hash::read_running_hash(&base.db),
            torus_state::running_hash::read_running_hash(&run.db),
            "{what}: running hash"
        );
        assert_eq!(base.root, run.root, "{what}: persisted native root");
        assert_dumps_equal(&dump_all_cfs(&base.db), &dump_all_cfs(&run.db), what);
    }

    /// s124 epoch fast path (a) + (b): flag off, the boundary blocks 4 / 8 /
    /// 12 stay serial (barrier) as before; flag on, they (no EVM tx, no
    /// slash) take the pipelined path, with a per-block flush and with
    /// checkpoints (never by time; every 5 blocks), and the state equals the
    /// serial run (no W) and the flag-off run per block and in every CF. The
    /// boundaries credit the permanent staker's EVM account, so W runs the
    /// mirror resync (F2) for them. A boundary checkpoints at its own height,
    /// so the durable marker after each block equals the flag-off run's,
    /// where the serial flush makes the boundary (and its plan) durable.
    #[test]
    fn epoch_fast_path_boundaries_pipelined_and_match_serial() {
        let serial = fast_path_run(false, false, None, None, None);
        assert!(serial.pipelined.is_empty(), "no W: every block is serial");
        // Non-vacuous F2: the staker staked its whole balance before block 1.
        let credited = serial
            .db
            .get_account(&fast_path_staker())
            .unwrap()
            .map(|a| a.balance)
            .unwrap_or_default();
        assert!(credited > U256::ZERO, "the boundaries credit the staker");
        let all: Vec<u64> = (1..=13).collect();
        let off_pipelined: Vec<u64> = (1..=13).filter(|h| h % 4 != 0).collect();
        for (what, policy) in [
            ("per-block", None),
            ("never", Some(ckpt_never())),
            ("every 5", Some(ckpt_every(5))),
        ] {
            let off = fast_path_run(true, false, policy, None, None);
            assert_eq!(
                off.pipelined, off_pipelined,
                "{what}, flag off: boundaries serial"
            );
            let on = fast_path_run(true, true, policy, None, None);
            assert_eq!(on.pipelined, all, "{what}, flag on: boundaries pipelined");
            assert_fast_path_runs_equal(&serial, &on, &format!("{what}: flag on vs serial"));
            assert_fast_path_runs_equal(&off, &on, &format!("{what}: flag on vs flag off"));
            assert_eq!(
                on.markers, off.markers,
                "{what}: durable marker after each block (a boundary is durable at once)"
            );
        }
    }

    /// s124 epoch fast path (c), archy's liveness case: epoch length 4 (not a
    /// multiple of the attest interval 100), checkpoints never by time, the
    /// flag on. Boundary 4 runs pipelined and writes the plan for boundary 8.
    /// Consensus reads that plan only once the DURABLE marker reaches 4 (bug
    /// (b)), and checkpoint triggers run only when a block executes: had the
    /// plan stayed in the in-memory window, blocks 5..=7 would commit and
    /// execute, execution would idle and every leader would refuse block 8
    /// for good. The boundary checkpoints at its own height instead: after
    /// 5..=7 with W idle, validators read the set for 8 and the leader
    /// proposes block 8.
    #[test]
    fn epoch_fast_path_plan_durable_before_next_boundary() {
        let (mut app, db, config) = epoch4_app(1_010);
        let mut ctx = make_exec_ctx(&config, &db);
        ctx.checkpoint = Some(ckpt_never());
        ctx.epoch_fast_path = true;
        ctx.attach_flush_worker(None);
        let mut blocks: Vec<TorusBlock> = (1..=7).map(|h| make_block(h, vec![])).collect();
        link_blocks(&mut blocks);
        for b in &blocks {
            dispatch_and_execute(&ctx, &db, b);
            assert!(!ctx.exec_failed.load(Ordering::SeqCst));
            if b.header.height == 4 {
                // Read before asserting: a failed assert holding the guard
                // would poison `last_job` for the shutdown drain.
                let top = ctx.last_job.lock().unwrap().as_ref().map(|p| p.height());
                assert_eq!(top, Some(4), "boundary 4 took the pipelined path");
            }
        }
        // Execution idles: W finishes what it was handed, nothing else runs.
        assert!(ctx.flush_worker.as_ref().unwrap().wait_idle());
        assert!(
            app.epoch_validator_set_updates(8).is_ok(),
            "the plan for 8 is durable: validators do not refuse block 8"
        );
        let _ = app.build_proposal(blocks[6].header.clone());
        assert!(
            app.pending_proposals.contains_key(&8),
            "the leader proposes block 8"
        );
        assert_eq!(
            read_native_applied_height(&db),
            Some(4),
            "boundary 4 checkpointed at its own height"
        );
        drop(ctx);
    }

    /// s124 epoch fast path (d): with the flag on, a boundary block with an
    /// EVM tx (8) or a buffered slash (12) still takes the barrier and the
    /// serial path; only the plain boundary 4 is pipelined. The state equals
    /// the serial run per block and in every CF, and the EVM tx and the
    /// slash really landed.
    ///
    /// Item 7 option 0 (task 3.6): with the EVM fast path on too, the EVM
    /// boundary 8 is pipelined; the slash boundary 12 still barriers (a
    /// non-durable header does as well:
    /// `fast_path_evm_block_not_dispatch_durable_stays_serial`).
    #[test]
    fn epoch_fast_path_evm_or_slash_boundary_stays_serial() {
        let serial = fast_path_run(false, false, None, Some(8), Some(12));
        let expected: Vec<u64> = (1..=13).filter(|h| *h != 8 && *h != 12).collect();
        for (what, policy) in [("per-block", None), ("never", Some(ckpt_never()))] {
            let on = fast_path_run(true, true, policy, Some(8), Some(12));
            assert_eq!(
                on.pipelined, expected,
                "{what}: EVM boundary 8 and slash boundary 12 serial"
            );
            assert_fast_path_runs_equal(&serial, &on, &format!("{what}: flag on vs serial"));
            let evm_on = fast_path_run_evm(true, true, true, policy, Some(8), Some(12));
            let expected_evm_on: Vec<u64> = (1..=13).filter(|h| *h != 12).collect();
            assert_eq!(
                evm_on.pipelined, expected_evm_on,
                "{what}, EVM fast path on: EVM boundary 8 pipelined, slash boundary 12 serial"
            );
            assert_fast_path_runs_equal(
                &serial,
                &evm_on,
                &format!("{what}: EVM fast path on vs serial"),
            );
        }
        let evm_sender = k256::ecdsa::SigningKey::from_slice(&[61u8; 32]).unwrap();
        assert_eq!(
            serial
                .db
                .get_account(&k256_address(&evm_sender))
                .unwrap()
                .unwrap()
                .nonce,
            1,
            "the EVM tx executed"
        );
        let slashed = StakingManager::new(serial.db.clone())
            .get_validator(&Address::repeat_byte(0x77))
            .unwrap()
            .unwrap();
        assert!(
            slashed.self_stake < torus_economics::MIN_SELF_DELEGATION,
            "the slash landed"
        );
    }

    /// Item 7 option 0 (task 3.1): with `TORUS_EVM_FAST_PATH` off (`0` /
    /// `false` on a node since the s131 default flip; a test context is off
    /// unless it sets the field) every block with EVM txs still barriers and
    /// runs serially, with the epoch fast path on and W attached: only the
    /// EVM boundary 8 (and the slash boundary 12) leave the pipelined path,
    /// as before the flag existed, and the state equals the serial run.
    #[test]
    fn evm_fast_path_flag_off_evm_heights_stay_serial() {
        assert!(
            crate::exec_pipeline::parse_evm_fast_path(None),
            "unset: on (s131 default)"
        );
        assert!(
            !crate::exec_pipeline::parse_evm_fast_path(Some("0".to_string())),
            "0: off"
        );
        let (config, db) = make_test_config_and_db();
        assert!(
            !make_exec_ctx(&config, &db).evm_fast_path,
            "a test context: off"
        );
        let serial = fast_path_run(false, false, None, Some(8), Some(12));
        let expected: Vec<u64> = (1..=13).filter(|h| *h != 8 && *h != 12).collect();
        for (what, policy) in [
            ("per-block", None),
            ("never", Some(ckpt_never())),
            ("every 5", Some(ckpt_every(5))),
        ] {
            let off = fast_path_run_evm(true, true, false, policy, Some(8), Some(12));
            assert_eq!(
                off.pipelined, expected,
                "{what}: EVM height 8 serial with the flag off"
            );
            assert_fast_path_runs_equal(&serial, &off, &format!("{what}: flag off vs serial"));
        }
    }

    /// s124 epoch fast path (e), ported from s58 bb62bab1: item 6 Phase 3
    /// crash replay with the flag on. The crashed run (checkpoint every 5
    /// blocks) adds two crashes whose blocks run an epoch boundary on the
    /// fast path (P2's epoch length is 50): at 49 with W parked on the
    /// checkpoint that boundary 50 hands off, and at 99 with W parked on
    /// 99's digest while E runs boundary 100. Flag off those crashes cannot
    /// run (the boundary's barrier waits for the parked W: "E blocked").
    /// Same per-block write sets, running hash and CF dump as the uncrashed
    /// flag-off per-block run, one guard rebuild per crash.
    #[test]
    fn epoch_fast_path_checkpoint_crash_replay_matches_uncrashed() {
        let (blocks, _) = p2_blocks(false);
        let crashes = [
            (12, false),
            (23, true),
            (37, false),
            (49, true),
            (61, true),
            (78, true),
            (99, false),
            (112, false),
        ];
        ckpt_crash_replay_with(
            torus_bridge::native_executor::BookMode::Classic,
            &blocks,
            "epoch fast path checkpoint crashes",
            &crashes,
            Some(true),
        );
    }

    /// exp/archy-s58-bundle-dmt: the bundle's node-local flags together
    /// leave the state of all flags off. D (`TORUS_SETTLE_DEFER_RESULTS`), M
    /// (`TORUS_PARALLEL_MATCH_SETUP`) and T (`TORUS_FAST_SELL_TOP_UPS`) are
    /// on by default: the on run pins each per thread to its parse of the
    /// unset env, the off run to its parse of `0` (the executor reads them on
    /// the calling thread, E here). E (`TORUS_EPOCH_FAST_PATH`, default on)
    /// is the context field. Over the 130 P2 blocks (boundaries 50 / 100),
    /// pipelined with a checkpoint every 5 blocks: D+M+T and D+M+T+E each
    /// equal the all-off run per block (write sets), in the running hash,
    /// every CF and the persisted native root.
    /// The per-flag differentials are the bridge's
    /// `settle_defer_results_tests`, `parallel_match_setup_tests`,
    /// `sell_top_up_stitch_diff_tests` and the epoch fast path tests above.
    #[test]
    fn s58_bundle_dmt_and_epoch_fast_path_state_equals_flags_off() {
        use torus_bridge::native_executor::{
            parse_fast_sell_top_ups, parse_parallel_match_setup, parse_settle_defer_results,
            with_fast_sell_top_ups, with_parallel_match_setup, with_settle_defer_results, BookMode,
        };
        // On by default (unset), all off at "0": else the comparison is vacuous.
        for (env, want) in [(None, true), (Some("0"), false)] {
            assert_eq!(
                [
                    parse_settle_defer_results(env),
                    parse_parallel_match_setup(env),
                    parse_fast_sell_top_ups(env),
                ],
                [want; 3],
                "D, M, T at {env:?}"
            );
        }
        let (blocks, _) = p2_blocks(false);
        let run = |dmt: Option<&str>, fast: bool| {
            with_settle_defer_results(parse_settle_defer_results(dmt), || {
                with_parallel_match_setup(parse_parallel_match_setup(dmt), || {
                    with_fast_sell_top_ups(parse_fast_sell_top_ups(dmt), || {
                        p2_run_fast(
                            &blocks,
                            true,
                            Some(BookMode::Classic),
                            &P2Fault::None,
                            Some(ckpt_every(5)),
                            Some(fast),
                        )
                    })
                })
            })
        };
        let off = run(Some("0"), false);
        let persisted = |db: &StateDb| torus_state::native_trie::persisted_native_root(db).unwrap();
        for (what, fast) in [("D+M+T", false), ("D+M+T+E", true)] {
            let on = run(None, fast);
            assert_write_sets_equal(&off.captured, &on.captured, what);
            assert!(on.hash.is_some());
            assert_eq!(off.hash, on.hash, "{what}: running hash");
            assert_dumps_equal(&off.dump, &on.dump, what);
            assert_eq!(persisted(&off.db), persisted(&on.db), "{what}: native root");
            // T's list path granted top-ups (measured: 15 full).
            assert!(
                on.metrics.sell_top_ups_full.get() > 0,
                "{what}: no sell top-up"
            );
            // E: the boundaries 50 / 100 took the pipelined path (one upkeep
            // per pipelined block), flag off they take the barrier.
            let pipelined = |run: &P2Run| {
                metric_value(
                    &run.metrics.encode(),
                    "torus_exec_checkpoint_upkeep_seconds_count",
                )
            };
            let want = pipelined(&off) + if fast { 2.0 } else { 0.0 };
            assert_eq!(pipelined(&on), want, "{what}: pipelined blocks");
        }
    }

    /// 8k L3.3 (`TORUS_BOOK_FAST_ENCODE`, node-local, on by default): the
    /// Classic save's exact-size encoder writes the same book blobs as
    /// `borsh::to_vec`. Over the 130 P2 blocks with reduce-only places and
    /// cloids (resting orders with and without a cloid, pending stops,
    /// cancels, liquidations, epoch boundaries 50 / 100), pipelined with a
    /// checkpoint every 5 blocks, flag on equals flag off per block (write
    /// sets, receipts included), in the running hash, every CF and the
    /// persisted native root. The flag is pinned on this thread (E, where
    /// the save runs); the on run must have taken the fast path, the off run
    /// never.
    #[test]
    fn book_fast_encode_state_equals_flag_off() {
        use torus_bridge::native_executor::{
            book_fast_encodes_on_this_thread, parse_book_fast_encode, with_book_fast_encode,
            BookMode,
        };
        assert!(parse_book_fast_encode(None), "on by default");
        assert!(!parse_book_fast_encode(Some("0")));
        let (blocks, _, cloid_places) = p2_blocks_with(true, true);
        assert!(!cloid_places.is_empty(), "the stream places cloids");
        let run = |on: bool| {
            let before = book_fast_encodes_on_this_thread();
            let r = with_book_fast_encode(on, || {
                p2_run_with(
                    &blocks,
                    true,
                    Some(BookMode::Classic),
                    false,
                    &P2Fault::None,
                    Some(ckpt_every(5)),
                )
            });
            (r, book_fast_encodes_on_this_thread() - before)
        };
        let (off, off_fast) = run(false);
        let (on, on_fast) = run(true);
        assert_eq!(off_fast, 0, "flag off: no fast encode");
        assert!(on_fast > 0, "flag on: the Classic save took the fast path");
        assert_write_sets_equal(&off.captured, &on.captured, "book fast encode");
        assert!(on.hash.is_some(), "running hash active");
        assert_eq!(off.hash, on.hash, "running hash");
        assert_dumps_equal(&off.dump, &on.dump, "book fast encode");
        let persisted = |db: &StateDb| torus_state::native_trie::persisted_native_root(db).unwrap();
        assert_eq!(persisted(&off.db), persisted(&on.db), "native root");
        // Not vacuous: the books carried resting orders and stops.
        assert!(on.v4_max > 0, "V4 rested orders / stops");
        assert!(on.ro_resting_max > 0, "reduce-only orders rested");
    }

    thread_local! {
        /// 8k L2.2: engine threads pinned on every `p2_run_full` context
        /// made on this thread (`None` = production `execute_batch`).
        static P2_ENGINE_THREADS: std::cell::Cell<Option<usize>> = const { std::cell::Cell::new(None) };
    }

    /// 8k L2.2: runs `f` with every `p2_run_full` context on this thread
    /// pinned to the engine with `threads` workers (parallel Phase 2 and the
    /// forced parallel settle whenever two markets have work).
    fn with_p2_engine_threads<R>(threads: usize, f: impl FnOnce() -> R) -> R {
        struct Restore(Option<usize>);
        impl Drop for Restore {
            fn drop(&mut self) {
                P2_ENGINE_THREADS.with(|c| c.set(self.0));
            }
        }
        let _restore = Restore(P2_ENGINE_THREADS.with(|c| c.replace(Some(threads))));
        f()
    }

    /// 8k L2.2 (`TORUS_SETTLE_NO_MERGE`, node-local, on by default): pass B
    /// keeps each market's position cache unmerged and the end-of-call flush
    /// writes them with the batch cache in the same key order. Over the 130
    /// P2 blocks with reduce-only places and cloids (fills, closes and flips
    /// in three markets, cancels, liquidations, epoch boundaries 50 / 100),
    /// on the engine with 4 workers (so every call with two markets at work
    /// runs the parallel settle), pipelined with a checkpoint every 5 blocks,
    /// flag on equals flag off per block (write sets, receipts included), in
    /// the running hash h_n, every CF and the persisted native root. The flag
    /// is pinned on this thread (E, where pass B and the flush run); the on
    /// run must have taken the unmerged flush, the off run never.
    #[test]
    fn settle_no_merge_state_equals_flag_off() {
        use torus_bridge::native_executor::{
            parse_settle_no_merge, settle_no_merge_fallbacks_on_this_thread,
            settle_no_merge_flushes_on_this_thread, with_settle_no_merge, BookMode,
        };
        assert!(parse_settle_no_merge(None), "on by default");
        assert!(!parse_settle_no_merge(Some("0")));
        let (blocks, _, cloid_places) = p2_blocks_with(true, true);
        assert!(!cloid_places.is_empty(), "the stream places cloids");
        let run = |on: bool| {
            let before = settle_no_merge_flushes_on_this_thread();
            let fallbacks_before = settle_no_merge_fallbacks_on_this_thread();
            let r = with_p2_engine_threads(4, || {
                with_settle_no_merge(on, || {
                    p2_run_with(
                        &blocks,
                        true,
                        Some(BookMode::Classic),
                        false,
                        &P2Fault::None,
                        Some(ckpt_every(5)),
                    )
                })
            });
            // Codex P1 fix: plain rows keep the per-market caches provably
            // disjoint, so no flush falls back to merge + flush_all.
            assert_eq!(
                settle_no_merge_fallbacks_on_this_thread() - fallbacks_before,
                0,
                "no-merge fallbacks (on {on})"
            );
            (r, settle_no_merge_flushes_on_this_thread() - before)
        };
        let (off, off_runs) = run(false);
        let (on, on_runs) = run(true);
        assert_eq!(off_runs, 0, "flag off: no unmerged flush");
        assert!(on_runs > 20, "flag on: the parallel settle flushed unmerged ({on_runs})");
        assert_write_sets_equal(&off.captured, &on.captured, "settle no merge");
        assert!(on.hash.is_some(), "running hash active");
        assert_eq!(off.hash, on.hash, "running hash h_n");
        assert_dumps_equal(&off.dump, &on.dump, "settle no merge");
        let persisted = |db: &StateDb| torus_state::native_trie::persisted_native_root(db).unwrap();
        assert_eq!(persisted(&off.db), persisted(&on.db), "native root");
        assert!(on.ro_resting_max > 0, "reduce-only orders rested");
        assert!(on.ro_moved > 0, "positions under reduce-only orders moved");
    }

    /// The resident staleness guards read the applied marker through the
    /// overlay (parent layer first), never the DB: over the 130 P2 blocks
    /// with checkpoints never by time, R and the books are built once, as
    /// with a per-block flush.
    #[test]
    fn resident_guards_do_not_trip_with_interval() {
        use torus_bridge::native_executor::BookMode;
        let (blocks, _fed) = p2_blocks(false);
        let mode = Some(BookMode::Classic);
        let per_block = p2_run(&blocks, true, mode, false, &P2Fault::None);
        let never = p2_run_with(
            &blocks,
            true,
            mode,
            false,
            &P2Fault::None,
            Some(ckpt_never()),
        );
        assert!(never.max_lag >= 40, "max lag {}", never.max_lag);
        for (what, run) in [("per-block", &per_block), ("never", &never)] {
            assert_eq!(
                run.metrics.exec_resident_rows_rebuilds.get(),
                1,
                "{what}: R builds"
            );
            assert_eq!(
                run.metrics.exec_resident_rebuilds.get(),
                1,
                "{what}: book builds"
            );
        }
        // The layer is taken back unshared every block (no deep copies), and
        // checkpoints ran (attest height 100; barriers 50 / 100; shutdown).
        assert_eq!(never.metrics.exec_checkpoint_layer_shared.get(), 0);
        assert!(never.metrics.exec_checkpoints.get() >= 2);
        assert_eq!(per_block.metrics.exec_checkpoints.get(), 0);
    }

    /// p3s2g (results doc 47.1): Phase 3's exec-thread work sat outside every
    /// phase timer (`residual_untimed` 4.8 -> 18.8 ms per 100 actions). Two
    /// series time it, each once per pipelined block: the join of the
    /// previous block's layer merge at the start of the block
    /// (`exec_checkpoint_settle_wait_seconds`) and the end-of-block upkeep
    /// (`exec_checkpoint_upkeep_seconds`: trigger, checkpoint-time merges and
    /// hand-off, view publish). Interval 0 observes neither.
    #[test]
    fn checkpoint_exec_thread_work_is_timed() {
        use torus_bridge::native_executor::BookMode;
        let (blocks, _fed) = p2_blocks(false);
        let mode = Some(BookMode::Classic);
        let per_block = p2_run(&blocks, true, mode, false, &P2Fault::None);
        let every = p2_run_with(
            &blocks,
            true,
            mode,
            false,
            &P2Fault::None,
            Some(ckpt_every(5)),
        );
        let v = |run: &P2Run, name: &str| metric_value(&run.metrics.encode(), name);
        // Hand-offs count the pipelined blocks plus a 0 per serial native
        // (barrier) block, so they bound the pipelined count from above.
        let handoffs = v(&every, "torus_exec_handoff_wait_seconds_count");
        let pipelined = v(&every, "torus_exec_checkpoint_upkeep_seconds_count");
        assert!(
            (100.0..=handoffs).contains(&pipelined),
            "pipelined blocks: {pipelined} of {handoffs} hand-offs"
        );
        for name in [
            "torus_exec_checkpoint_settle_wait_seconds",
            "torus_exec_checkpoint_upkeep_seconds",
        ] {
            assert_eq!(v(&every, &format!("{name}_count")), pipelined, "{name}");
            assert!(v(&every, &format!("{name}_sum")) > 0.0, "{name}: timed");
            assert_eq!(
                v(&per_block, &format!("{name}_count")),
                0.0,
                "{name}: interval 0"
            );
        }
    }

    /// p3 merge wait (results doc 49: E waited 23.9 ms per native block at
    /// the start of the block for the previous block's merge into L). The
    /// merge hands L back without positions and balances (~92% of a block's
    /// keys), which a native block reads from R only; E joins that part at
    /// the end of the block. Over the 130 P2 blocks, checkpoints never by
    /// time, every merge's deferred half is held until E's next upkeep (or
    /// a drain, or a read blocking on it): no hold times out (E never
    /// waited for it mid-block), no read blocked on it, and the write sets,
    /// running hash and CF dump equal the per-block run.
    #[test]
    fn exec_does_not_wait_for_the_deferred_layer_merge() {
        use torus_bridge::native_executor::BookMode;
        let (blocks, _fed) = p2_blocks(false);
        let mode = Some(BookMode::Classic);
        let per_block = p2_run(&blocks, true, mode, false, &P2Fault::None);
        let gate = Arc::new(DeferredGate::default());
        let run = p2_run_with(
            &blocks,
            true,
            mode,
            false,
            &P2Fault::DeferredGate(gate.clone()),
            Some(ckpt_never()),
        );
        let stats = gate.stats();
        assert_eq!(
            stats.timeouts, 0,
            "E waited for a held deferred merge: {stats:?}"
        );
        assert!(stats.held >= 100, "merges held until upkeep: {stats:?}");
        assert_eq!(
            run.metrics.exec_checkpoint_deferred_read_waits.get(),
            0,
            "no read blocked on the deferred part"
        );
        let v = |name: &str| metric_value(&run.metrics.encode(), name);
        assert_eq!(
            v("torus_exec_checkpoint_deferred_join_seconds_count"),
            v("torus_exec_checkpoint_upkeep_seconds_count"),
            "the join is observed once per upkeep"
        );
        assert!(run.max_lag >= 40, "max lag {}", run.max_lag);
        assert_write_sets_equal(&per_block.captured, &run.captured, "gated vs per-block");
        assert_eq!(per_block.hash, run.hash, "running hash");
        assert_dumps_equal(&per_block.dump, &run.dump, "gated vs per-block");
        assert_eq!(run.metrics.exec_checkpoint_layer_shared.get(), 0);
    }

    /// Item 6 Phase 4 step 2: rows the node itself never writes, which
    /// `Users` keeps raw: a trader whose long position row decodes leniently
    /// (`is_long` byte 2: opaque, read raw through R) facing a regular short
    /// (both with a balance, OI symmetric, written through `apply_fill`), a
    /// positions key and a balances key under no trader, and a balance-only
    /// trader whose address starts with `cvlm`.
    fn p2_seed_irregular(db: &StateDb) {
        use torus_core::position::{position_key, MarginType, NativeBalance, PositionManager};
        let pm = PositionManager::new(db.clone());
        let (odd, even) = (Address::repeat_byte(0xA7), Address::repeat_byte(0xA8));
        for (t, long) in [(odd, true), (even, false)] {
            pm.put_native_balance(&t, &NativeBalance { available: px(1_000), order_margin: FixedPoint::ZERO })
                .unwrap();
            pm.apply_fill(&t, 1, long, px(1), px(100), MarginType::Cross).unwrap();
        }
        let key = position_key(&odd, 1);
        let mut row = db.get_cf_raw(torus_state::cf::CF_NATIVE_POSITIONS, &key).unwrap().expect("odd's position");
        assert_eq!(row[1 + 20 + 8], 1, "is_long byte");
        row[1 + 20 + 8] = 2;
        db.put_cf_raw(torus_state::cf::CF_NATIVE_POSITIONS, &key, &row).unwrap();
        db.put_cf_raw(torus_state::cf::CF_NATIVE_POSITIONS, b"short", b"under-no-trader").unwrap();
        db.put_cf_raw(torus_state::cf::CF_NATIVE_BALANCES, b"odd-balances-key", b"under-no-trader").unwrap();
        pm.put_native_balance(&p2_cvlm_user(), &NativeBalance { available: px(5), order_margin: FixedPoint::ZERO })
            .unwrap();
    }

    /// [`p2_seed_irregular`]'s balance-only trader whose address starts with `cvlm`.
    fn p2_cvlm_user() -> Address {
        let mut c = [0x11u8; 20];
        c[..4].copy_from_slice(b"cvlm");
        Address::new(c)
    }

    /// What [`p2_irregular_probe`] saw.
    #[derive(Debug, Default)]
    struct IrregularProbeStats {
        /// Native blocks probed.
        blocks: u64,
        /// Of them, with R attached to the block's overlay.
        resident: u64,
        /// Of them, with R attached and a layer merge's deferred part not yet
        /// released by the gate (`spawned > released`).
        held: u64,
    }

    /// Codex r1 note on step 2: execution's reads of the rows `Users` keeps
    /// raw and of the balance-only `cvlm` user, mid-block (after the
    /// liquidation step, which with the value-sum walk on pages through both
    /// CFs). Point reads, prefix and seek reads of the two keys under no
    /// trader and the `cvlm` user's balance (raw and typed) equal the seeded
    /// rows; with R attached no read blocked on the deferred part
    /// (`deferred_read_waits` unchanged: answered by R, above L).
    fn p2_irregular_probe(
        gate: Option<Arc<DeferredGate>>,
        stats: Arc<std::sync::Mutex<IrregularProbeStats>>,
    ) -> BlockProbe {
        use torus_state::cf::{CF_NATIVE_BALANCES, CF_NATIVE_POSITIONS};
        Arc::new(move |ctx: &NativeExecContext<NativeStateOverlay>| {
            let h = ctx.block_height;
            let held = gate.as_ref().is_some_and(|g| {
                let s = g.stats();
                s.spawned > s.released
            });
            let waits = || ctx.metrics.as_ref().map_or(0, |m| m.exec_checkpoint_deferred_read_waits.get());
            let before = waits();
            let st = &ctx.state;
            let raw = |v: &[u8]| Some(v.to_vec());
            assert_eq!(st.get_cf_raw(CF_NATIVE_POSITIONS, b"short").unwrap(), raw(b"under-no-trader"), "block {h}: short positions key");
            assert_eq!(
                st.get_cf_raw(CF_NATIVE_BALANCES, b"odd-balances-key").unwrap(),
                raw(b"under-no-trader"),
                "block {h}: balances key under no trader"
            );
            assert_eq!(
                st.iterate_cf(CF_NATIVE_POSITIONS, Some(b"sho")).unwrap(),
                vec![(b"short".to_vec(), b"under-no-trader".to_vec())],
                "block {h}: positions prefix read"
            );
            assert_eq!(
                st.iterate_cf_from(CF_NATIVE_BALANCES, b"odd-", 1).unwrap(),
                vec![(b"odd-balances-key".to_vec(), b"under-no-trader".to_vec())],
                "block {h}: balances seek"
            );
            let c = p2_cvlm_user();
            let want = torus_core::position::NativeBalance { available: px(5), order_margin: FixedPoint::ZERO };
            let row = st.get_cf_raw(CF_NATIVE_BALANCES, c.as_slice()).unwrap().expect("cvlm user's balance row");
            assert_eq!(row, borsh::to_vec(&want).unwrap(), "block {h}: cvlm user's balance row");
            let typed = ctx.positions.get_native_balance(&c).unwrap();
            assert_eq!((typed.available, typed.order_margin), (want.available, want.order_margin), "block {h}: typed");
            let under = st.iterate_cf(CF_NATIVE_BALANCES, Some(b"cvlm")).unwrap();
            assert!(under.contains(&(c.to_vec(), row.clone())), "block {h}: cvlm-headed prefix read lists the user");
            assert_eq!(st.iterate_cf_from(CF_NATIVE_BALANCES, c.as_slice(), 1).unwrap(), vec![(c.to_vec(), row)], "block {h}: seek");
            let resident = st.has_resident();
            if resident {
                assert_eq!(waits(), before, "block {h}: a read of the two CFs blocked on the deferred part");
            }
            let mut s = stats.lock().unwrap();
            s.blocks += 1;
            s.resident += u64::from(resident);
            s.held += u64::from(resident && held);
        })
    }

    /// Item 6 Phase 4 step 2 (plan Task 2.2, rows 9 / 12): with positions
    /// and balances read from `Users` (irregular rows included, kept raw), no
    /// read of the two CFs goes past R: over the 130 P2 blocks at interval
    /// "never", every layer merge's deferred half held until E's next upkeep,
    /// no read blocked on it and E never waited mid-block. The write sets
    /// (every `h_n`), running hash and CF dump equal the per-block run with R
    /// and the runs without R (serial and pipelined, today's DB path).
    #[test]
    fn users_reads_never_reach_the_deferred_part() {
        use torus_bridge::native_executor::BookMode;
        let (blocks, _fed) = p2_blocks(false);
        let mode = Some(BookMode::Classic);
        let seed: &dyn Fn(&StateDb) = &p2_seed_irregular;
        let gate = Arc::new(DeferredGate::default());
        // Codex r1 note: execution reads the rows under no trader and the
        // balance-only `cvlm` user through R while the merge is held.
        let seen = Arc::new(std::sync::Mutex::new(IrregularProbeStats::default()));
        let probe = p2_irregular_probe(Some(gate.clone()), seen.clone());
        let gated = p2_run_seeded(
            &blocks,
            true,
            mode,
            false,
            &P2Fault::DeferredGate(gate.clone()),
            Some(ckpt_never()),
            seed,
            false,
            Some(&probe),
        );
        let probed = std::mem::take(&mut *seen.lock().unwrap());
        assert!(probed.blocks >= 100 && probed.resident == probed.blocks, "R attached at every probe: {probed:?}");
        assert!(probed.held >= 100, "probed while a deferred merge was held: {probed:?}");
        let stats = gate.stats();
        assert_eq!(stats.timeouts, 0, "E waited for a held deferred merge: {stats:?}");
        assert!(stats.held >= 100, "merges held until upkeep: {stats:?}");
        assert_eq!(gated.metrics.exec_checkpoint_deferred_read_waits.get(), 0, "no read blocked on the deferred part");
        assert!(gated.max_lag >= 40, "max lag {}", gated.max_lag);
        assert!(gated.r_db_checked >= 2, "R (through Users) == DB at the durable heights: {}", gated.r_db_checked);
        let per_block = p2_run_seeded(&blocks, true, mode, false, &P2Fault::None, None, seed, false, None);
        assert!(per_block.r_db_checked >= 100, "{}", per_block.r_db_checked);
        // Without R the probe reads the layers and the DB: same values.
        let off_probe = p2_irregular_probe(None, seen.clone());
        let off = p2_run_seeded(&blocks, true, mode, false, &P2Fault::None, Some(ckpt_never()), seed, true, Some(&off_probe));
        let off_probed = std::mem::take(&mut *seen.lock().unwrap());
        assert!(off_probed.blocks == probed.blocks && off_probed.resident == 0, "{off_probed:?}");
        // The value-sum walk (both CFs, every row) read the same rows through
        // R as without it (the last block's sum).
        let value_sum = |run: &P2Run| metric_value(&run.metrics.encode(), "torus_liquidation_value_sum");
        assert_eq!(value_sum(&gated), value_sum(&off), "value-sum walk through R == without R");
        let serial_off = p2_run_seeded(&blocks, false, mode, false, &P2Fault::None, None, seed, true, None);
        assert_eq!(off.r_db_checked + serial_off.r_db_checked, 0, "no R");
        for (what, run) in [("per-block", &per_block), ("never without R", &off), ("serial without R", &serial_off)] {
            assert_write_sets_equal(&run.captured, &gated.captured, &format!("gated vs {what}"));
            assert_eq!(run.hash, gated.hash, "gated vs {what}: running hash");
            assert_dumps_equal(&run.dump, &gated.dump, &format!("gated vs {what}"));
        }
        // The seeded rows were state (and the lenient row is still raw or was rewritten by a block).
        let has = |cf: &str, k: &[u8]| gated.dump.iter().any(|(c, rows)| *c == cf && rows.iter().any(|(key, _)| key == k));
        assert!(has(torus_state::cf::CF_NATIVE_POSITIONS, b"short") && has(torus_state::cf::CF_NATIVE_BALANCES, b"odd-balances-key"));
    }

    /// Item 6 Phase 4 step 2 (plan Task 2.2): after every block whose
    /// writes are all durable, the holder's R — positions and balances read
    /// through `Users` — equals the DB scan of R's CFs (and `Users` equals a
    /// cold build of its own rows), at interval 0 (serial and pipelined),
    /// every 5 blocks (15 s-like) and never by time; the runs land the same
    /// state as the serial one.
    #[test]
    fn resident_rows_equal_db_after_every_flush_every_interval() {
        use torus_bridge::native_executor::BookMode;
        let (blocks, _fed) = p2_blocks(false);
        let mode = Some(BookMode::Classic);
        let serial = p2_run(&blocks, false, mode, false, &P2Fault::None);
        assert!(serial.r_db_checked >= 100, "serial: {}", serial.r_db_checked);
        for (name, policy, min) in [("per-block", None, 100), ("every 5", Some(ckpt_every(5)), 15), ("never", Some(ckpt_never()), 2)] {
            let run = p2_run_with(&blocks, true, mode, false, &P2Fault::None, policy);
            assert!(run.r_db_checked >= min, "{name}: R == DB checked after {} blocks", run.r_db_checked);
            assert_write_sets_equal(&serial.captured, &run.captured, &format!("{name} vs serial"));
            assert_eq!(serial.hash, run.hash, "{name} vs serial: running hash");
            assert_dumps_equal(&serial.dump, &run.dump, &format!("{name} vs serial"));
        }
    }

    // ---- Item 6 Phase 3 task 1.7: crash and replay at interval > 0 ----

    /// `(k, mid_checkpoint)` crash points: no epoch boundary (50 / 100) in
    /// the blocks each crash runs.
    const CKPT_CRASHES: [(u64, bool); 6] = [
        (12, false),
        (23, true),
        (37, false),
        (61, true),
        (78, true),
        (112, false),
    ];

    /// A crashed run digests some heights twice (before the crash on W, then
    /// in the replay): both write sets must agree. Returns one per height.
    fn dedup_captured(captured: &CapturedWrites, what: &str) -> CapturedWrites {
        let mut out: CapturedWrites = Vec::new();
        for (h, w) in captured {
            match out.iter().find(|(oh, _)| oh == h) {
                Some((_, ow)) => assert!(
                    ow == w,
                    "{what}: height {h} digested twice, write sets differ"
                ),
                None => out.push((*h, w.clone())),
            }
        }
        out.sort_by_key(|(h, _)| *h);
        out
    }

    /// The 130 P2 blocks with a checkpoint every 5 blocks and 6 crashes
    /// (3 with a checkpoint batch in flight): per-block `h_n`, running hash
    /// and full CF dump equal the uncrashed per-block run; every crash lost
    /// blocks, and the guard rebuilt the books once per crash.
    fn ckpt_crash_replay(mode: torus_bridge::native_executor::BookMode) {
        let (blocks, _) = p2_blocks(false);
        ckpt_crash_replay_on(mode, &blocks, &format!("{mode:?} checkpoint crashes"));
    }

    /// [`ckpt_crash_replay`] on `blocks`; returns `(uncrashed per-block
    /// run, crashed run)`.
    fn ckpt_crash_replay_on(
        mode: torus_bridge::native_executor::BookMode,
        blocks: &[TorusBlock],
        what: &str,
    ) -> (P2Run, P2Run) {
        ckpt_crash_replay_with(mode, blocks, what, &CKPT_CRASHES, None)
    }

    /// [`ckpt_crash_replay_on`] with the crash points `crashes` and, for
    /// `fast: Some(_)`, the epoch-boundary fast path set to it on the
    /// crashed run and off on the reference (`None`: both keep the env's).
    fn ckpt_crash_replay_with(
        mode: torus_bridge::native_executor::BookMode,
        blocks: &[TorusBlock],
        what: &str,
        crashes: &[(u64, bool)],
        fast: Option<bool>,
    ) -> (P2Run, P2Run) {
        let reference = p2_run_fast(
            blocks,
            true,
            Some(mode),
            &P2Fault::None,
            None,
            fast.map(|_| false),
        );
        let fault = P2Fault::CkptCrash(crashes.to_vec());
        let run = p2_run_fast(blocks, true, Some(mode), &fault, Some(ckpt_every(5)), fast);
        assert_eq!(run.faults, crashes.len() as u64, "{what}");
        let captured = dedup_captured(&run.captured, what);
        assert_eq!(
            captured.iter().map(|(h, _)| *h).collect::<Vec<_>>(),
            (1..=P2_BLOCKS).collect::<Vec<_>>(),
            "{what}: every height hashed"
        );
        assert_write_sets_equal(&reference.captured, &captured, what);
        assert!(run.hash.is_some());
        assert_eq!(reference.hash, run.hash, "{what}: running hash");
        assert_dumps_equal(&reference.dump, &run.dump, what);
        assert_eq!(
            run.metrics.exec_resident_rebuilds.get(),
            1 + crashes.len() as u64,
            "{what}: one guard rebuild per crash"
        );
        (reference, run)
    }

    /// s118 (Phase 3 step 2 follow-up, review of c88d3073): [`ckpt_crash_replay`]
    /// with cloid traffic (`p2_blocks_with(false, true)`). Six crashes at a
    /// checkpoint every 5 blocks; the uncrashed per-block run is the
    /// reference. Equal per-block `h_n`, running hash, full CF dump (books
    /// with their orders' cloids, the action status records with every
    /// `DuplicateCloid`), the persisted native root at every checkpoint and
    /// at the end. The resident holder's carried cloid index equals a
    /// rebuild after every block, before and after each replay (the stale
    /// holder's is dropped by the guard and rebuilt). Non-vacuous, from the
    /// stored outcomes of the single places with a cloid: in the replayed
    /// spans `(durable, last]` a cloid placed at or before the durable
    /// checkpoint is rejected as a duplicate, and a cloid freed by a fill or
    /// cancel is placed again; in the 10 blocks after a replay a cloid placed
    /// before the crash is rejected, and one freed is placed again. A cloid
    /// lost by the checkpoint or the replay (missing from the books or the
    /// index) accepts a duplicate there, one resurrected rejects a reuse:
    /// either changes the action status and books, so the dumps differ.
    /// (s118 mutant: a book load that forgets its pending stops' cloids
    /// fails this test; the cloid-free [`ckpt_crash_replay`] passes on it.)
    fn ckpt_crash_replay_cloids(mode: torus_bridge::native_executor::BookMode) {
        use torus_state::action_status::FailureReason;
        let (blocks, fed, singles) = p2_blocks_with(false, true);
        assert!(fed.cloids >= 300 && fed.cancels_by_cloid >= 30, "{fed:?}");
        let what = format!("{mode:?} checkpoint crashes, cloids");
        let (reference, run) = ckpt_crash_replay_on(mode, &blocks, &what);
        assert_eq!(run.crash_windows.len(), CKPT_CRASHES.len(), "{what}");
        // State roots: at each checkpoint S and at the end.
        assert!(
            run.roots.len() >= 10,
            "{what}: checkpoints {}",
            run.roots.len()
        );
        for (s, root) in &run.roots {
            let want = reference
                .roots
                .iter()
                .find(|(h, _)| h == s)
                .map(|(_, r)| *r);
            assert_eq!(Some(*root), want, "{what}: native root at checkpoint {s}");
        }
        let persisted = |db: &StateDb| torus_state::native_trie::persisted_native_root(db).unwrap();
        assert_eq!(
            persisted(&run.db),
            persisted(&reference.db),
            "{what}: final root"
        );
        // The carried cloid index was built and checked after most blocks
        // (in the crashed run too: the crash blocks run off the loop).
        assert!(
            reference.cloid_checked >= P2_BLOCKS - 10,
            "{what}: reference {}",
            reference.cloid_checked
        );
        assert!(
            run.cloid_checked >= P2_BLOCKS - 40,
            "{what}: crashed {}",
            run.cloid_checked
        );

        // Outcomes of the single places with a cloid (the crashed run's
        // records; equal to the reference's by the dump).
        let mut last_ok: std::collections::HashMap<(u8, u128), u64> = Default::default();
        let mut tried: std::collections::HashSet<(u8, u128, u64)> = Default::default();
        // (placed ok at, duplicate at) and (placed ok at, placed again at).
        let (mut dups, mut reuses) = (Vec::new(), Vec::new());
        for &(h, idx, t, c) in &singles {
            let status = action_status(&run.db, h).expect("a block with actions has a record");
            assert!(!status.native_skipped[idx], "{what}: {h}/{idx} executed");
            let failed = status
                .native_failed
                .iter()
                .find(|f| f.index as usize == idx)
                .map(|f| f.reason);
            let first_in_block = tried.insert((t, c, h));
            match (failed, last_ok.get(&(t, c))) {
                (Some(FailureReason::DuplicateCloid), Some(&h0)) if first_in_block && h0 < h => {
                    dups.push((h0, h));
                }
                (None, prev) => {
                    if let Some(&h0) = prev {
                        reuses.push((h0, h));
                    }
                    last_ok.insert((t, c), h);
                }
                _ => {}
            }
        }
        let count = |pairs: &[(u64, u64)], hit: &dyn Fn(u64, u64, u64, u64) -> bool| {
            pairs
                .iter()
                .filter(|&&(h0, h)| run.crash_windows.iter().any(|&(d, l)| hit(h0, h, d, l)))
                .count()
        };
        let replayed_dup = count(&dups, &|h0, h, d, l| h0 <= d && d < h && h <= l);
        let replayed_reuse = count(&reuses, &|_, h, d, l| d < h && h <= l);
        let after_dup = count(&dups, &|h0, h, _, l| h0 <= l && l < h && h <= l + 10);
        let after_reuse = count(&reuses, &|h0, h, _, l| h0 <= l && l < h && h <= l + 10);
        println!(
            "{what}: fed {fed:?}; single cloid places {}, duplicates {}, reuses {}; windows {:?}; \
             replayed: duplicate of a checkpointed cloid {replayed_dup}, reuse {replayed_reuse}; \
             after replay: duplicate {after_dup}, reuse {after_reuse}",
            singles.len(),
            dups.len(),
            reuses.len(),
            run.crash_windows,
        );
        // Measured (s118): 11 / 27 replayed, 15 / 35 after; 53 / 109 total.
        assert!(
            replayed_dup >= 5 && replayed_reuse >= 10 && after_dup >= 5 && after_reuse >= 10,
            "{what}: cloid traffic across the crashes"
        );
        assert!(
            dups.len() >= 30 && reuses.len() >= 60,
            "{what}: {} duplicates, {} reuses",
            dups.len(),
            reuses.len()
        );
        let labelled = |m: &torus_telemetry::Metrics| {
            m.orders_rejected_reason[torus_telemetry::OrderRejectReason::DuplicateCloid as usize]
                .get()
        };
        assert!(labelled(&reference.metrics) >= dups.len() as u64, "{what}");
    }

